window.__D("text/likkutei-sichot/c177",{"p":[[1300271193,"ד. אבער אעפ\"כ, איז אויך דער וואס האט נאך ניט דעם כח צו אויפטאן דעם ענין פון „קנין הגוף\" (צו איבערמאכן אינגאנצן די מדות שבלב ורצון שבמוח אז זיי זאלן זיין קנוי להשם) — האט ער אן עצה ווי צו „מקנה\" זיין „פירותיו\" שלא באו לעולם, דורך דעם וואס ער איז „מקנה גוף לפירותיו . . כגון . . אילן לפירותיו\" (ד.ה. אז כאטש דעם גוף עצמו קען ער ניט מקנה זיין להקב\"ה, קען ער אבער מקנה זיין דעם „גוף (בלויז בשייכות) לפירותיו\").\nדי הסברה אין דעם:\nדי עבודה פון א בינוני איז ניט בא-גרענעצט בלויז29 צו זיינע „לבושי הנפש\" — אז יעדער מאל ווען בלבו וכו' ווערט נתעורר א תאווה ורצון איז ער בלויז לוחם צו פארמיידן די „הת-פשטות\" התאווה והרצון אין מחשבה דיבור ומעשה30 — נאר די עבודה איז אויך29 פועל אויף די מדות ושכל עצמו, אז ער איז כופה (ועד שעושה רושם (עכ\"פ) גם בנוגע לעתיד) — דעם רע שבלבו31 ומוחו.\nווי דער אלטער רבי32 איז מבאר, אז בשעת התפלה איז א בינוני מעורר ביי זיך אהבת ה' בהתגלות לבו33 וואס דאס פועל'ט אז דער רע שבלבו זאל דעמאלט זיין „כאדם שישן\"34 (און אט די אהבה לה' בשעת התפלה לאזט איבער א רושם אויפן אדם וואס גיט אים א כח ותוקף „להתגבר ולשלוט על הרע הזה המתאווה תאווה\"<sup data-n=\"35\">35</sup>.\nאון בפרט — וויבאלד אז די מדת האהבה פון א בינוני בשעת התפלה איז ביי אים מיט אן אמת36, וואס „(שפת אמת) תכון לעד\"37 — ער האט בכח צו מעורר זיין אט די אהבה לה' (און דורכ-דעם „איינשלעפערן\" דעם רע שבלבו) „בשעת התפלה מדי יום ביום\"36 — קומט אויס, אז א בינוני האט א (גע-וויסע) שליטה אויך אויף דעם „מהות ועצמות\" (די מדות וכו') פון דעם יצר הרע38.\nאון דאס גיט א תוספת ביאור אין דעם וואס דער אלטער רבי זאגט20 וועגן א „בינוני\", אז „לא עבר עבירה מימיו ולא יעבור לעולם\". ד.ה. מצד מצבו בהווה39 איז ער בטוח אז „לא יעבור לעולם\", אז אויך בעתיד וועט ער זיכער קענען שולט זיין אויפן יצר הרע און ניט טאן קיין עבירה —",[["29","29","ראה אוה\"ת משפטים (ע' א'קלא ואילך) שתי הדרגות בבינוני: עבד כנעני — שמצד „בחי' נצח והסכם הוא מקבל עליו עומ\"ש כל היום כולו ומושל ברוחו כו'\"; ועבד עברי — כנגד יצירה (בחי' מדות) — שיש לו תשוקה כו' במדות שבלב (ע\"ש באורך. וקאי בבינוני — ראה שם ע' א'קלא, א'קמ-מא. וראה בארוכה דרך חיים ד\"ה להבין סדר התפלה פס\"ח-סט)."],["30","30","ראה תניא רפי\"ד: גם בשעה שהלב חומד כו'. שם רפט\"ו."],["31","31","וזוהי עיקר מלחמת הבינוני, לשלוט על הרע שבלב ע\"י שמעורר אהבת ה' בלבו (ראה תניא פי\"ג (יח, ב). פט\"ו-טז. ועוד) — והרי עיקר דרגת הבינוני הוא בחי' עבד עברי (מדות) — ראה אוה\"ת וד\"ח שם."],["32","32","שם פי\"ב-יג."],["33","33","או עכ\"פ האהבה שבתעלומות מוחו ולבו (תניא פט\"ז. ע\"ש, שהיא „האהבה המביאה לידי עשיית המצות בלבד\" (שם פט\"ז — כב, סע\"ב)."],["34","34","שם פי\"ג (יח, סע\"ב ואילך). ובפי\"ב (טז, ב) „ואז הרע שבחלל השמאלי כפוף ובטל לטובו\". ועוד. — וראה שם פל\"ה (מה, א) דגם בעת עשיית מצוה הן בבחי' גלות ושינה\"."],["35","35","שם ספי\"ב (יז, ב)."],["36","36","שם פי\"ג (יט, א). ע\"ש בארוכה. לקו\"ת ריש פרשתנו (מ, א)."],["37","37","משלי יב, יט."],["38","38","עיין אוה\"ת שם (ע' א'קלד. א'קמא). המשך תער\"ב ח\"א פקמ\"ג. ס\"פ רכ."],["39","39","ראה ליקוט פירושים כו' לתניא פי\"ב (ע' רכט. רלה)."]]],[1300271194,"ווייל א בינוני האט א שליטה אויך אויף די מדות40 וכו' פון דעם יצר הרע, נאר ניט אויף די עצם המדות כשלעצמן, נאר בלויז ביחס צו זייער התפשטות („פירות\")41 אין מחשבה דיבור ומעשה.\nאון דאס איז דער ענין פון „מקנה גוף לפירותיו\" אין עבודת האדם:\nאפילו אויב מ'האלט ניט ביי דער דרגא צו קענען איבערמאכן דעם עצם פון די מדות וכו' שבלבו (אז מ'זאל בכלל ניט האבן קיין תאוות וכו') — איז עס אבער בכחו צו פועל זיין (א כפי' כו') אויף זיינע מדות וכו' עכ\"פ בשייכות צו זייער „התפשטות\" („גוף לפירותיו\"); און דעמאלט זיינען אויך „פירותיו\" (מחשבות דיבורים ומעשים) שלא באו לעולם קנויים להשם — ער איז אין א מצב פון „לא יעבור לעולם\".\nה. אין אנדערע ווערטער מיינט עס:\nאע\"פ אז ניט יעדערער קען צוקומען צו דער דרגא פון „עבד ה'\", וואס „גופו קנוי\" להשם — איז אבער יעדער איד א שליח פון אויבערשטן וואס האט די כוחות דורכצופירן כוונת הבריאה לעשות לו ית' דירה בתחתונים, ווייל „שלוחו של אדם — העליון42 — כמותו\", און „כמותו דהמשלח ממש\"43.\nאון ווי גערעדט כמה פעמים, אז דער העכסטער אופן אין שליחות איז44, אז ניט נאר מעשה השליח, אדער אפילו דער כח העשי' שלו, איז זיך מתייחס צום משלח, נאר כללות מציאותו של השליח איז „כמותו דהמשלח ממש\" (ובדרך ממילא ווערט דער מעשה השליח פאררעכנט ווי מעשה המשלח).\n[נאר אעפ\"כ איז דאס ניט בדומה צו אן עבד45 וואס איז ניט קיין מציאות בפני עצמו כלל — כל גופו איז קנוי לרבו; משא\"כ ביי א שליח — אפילו אין דעם העכסטן אופן פון שליחות, וואס דער שליח עצמו (ניט נאר זיין מעשה אדער כח העשי') איז „כמותו דהמשלח ממש\" — איז עס נאר בשייכות צו דעם ענין השליחות (ע\"ד ווי „גוף לפירותיו\"), אבער ניט בנוגע לשאר עניניו].\nקומט אויס, אז יעדער איד האט דעם כח צו איבערגעבן כללות מציאותו צום אויבערשטן, אויף זיין א שליח ה' דורכ-צופירן כוונת הבריאה, וואס דורך דער „הקנאה\" כללית (עכ\"פ באופן פון „גוף לפירותיו\"), ווערן בדרך ממילא אלע זיינע פרטי עשיותיו (ודיבוריו ומחש-בותיו) „קנויים\" לה', מתאים לרצון המשלח.\nו. אין דעם איז דער רמב\"ם מחדש נאכמער, אז „דין ההקדש . . אינו כדין ההדיוט בקנייתו, שאילו אמר אדם כל מה שתלד בהמתי יהי' הקדש . . חייב",[["40","40","ולכאורה גם הבינוני שמצד עומ\"ש (ראה לעיל הערה 29) נאמר עליו „ולא יעבור לעולם\" (אע\"פ שהרע הוא בתקפו ומושל עליו רק מצד העול). וראה ד\"ה ואלה המשפטים תשל\"ח פ\"ה (סה\"מ — מלוקט ח\"א ע' שט). ואולי יש לומר, דמכיון שיש לו שליטה על לבושי הנפש (היינו כח המחדו\"מ שלו) ה\"ז כמו מקנה „גוף לפירותיו\" (ראה לעיל סעיף ב). אבל עיקר הענין ד„גוף לפירותיו\" הוא בזה שיש לו שליטה על (התפשטות) המדות דנפה\"ב — כי הנפש עצמה היא „עשר בחינותי', השכל ומדות\" (תניא רפי\"ב. וראה לקו\"ת ויקרא ביאור לד\"ה ולא תשבית פ\"א. ועוד) ולא לבושי הנפש, ושמם „לבושי\" מוכיח."],["41","41","ראה המשך תער\"ב שם."],["42","42","ראה לקו\"ת ויקרא (א, ג)."],["43","43","ל' הלקו\"ת שם."],["44","44","ראה בארוכה לקח טוב להר\"י ענגל בתחילתו."],["45","45","ראה גם לקו\"ש ח\"כ ע' 303."]]],[1300271195,"לקיים דברו\" — וואס אין עבודה רוחנית י\"ל דאס מיינט:\nווען איינער האלט ניט אפילו ביי דער דרגא צו קענען דורכפירן דעם קנין „גוף לפירותיו\" — ער האט ניט קיין שליטה אויפן „גוף\" פון זיינע מדות (אפילו ניט בשייכות „לפירותיו\"), אזוי אז ער איז לכאורה ניט שייך צו „מקנה\" זיין „פירותיו\" (פעולותיו) שלא באו לעולם (ובמילא — ביי יעדער עשי' כו' דארף ער דורכגיין נאך אמאל א מלחמה מיטן יצר אז עס זאל זיין אן עשי' כרצון קונו) —\nאיז במה דברים אמורים, בשעת עס רעדט זיך וועגן קניית הדיוט, וואס „אין אדם מצווה להקנות\", ד.ה. וועגן דברי הרשות של האדם; משא\"כ ווען עס רעדט זיך וועגן „דין ההקדש\", קדושה-דיקע ענינים, החלטות טובות אין ענינים פון תורה ומצות (וואס „הוא מצווה לקיים דבריו\") — איז אין הכי נמי אז קיין „קנין\" טוט זיך ניט אויף בהחלטתו — בהחפצא (בהדבר שמחוץ לאדם), עס ווערט אבער אויפגעטאן א חיוב בהאדם — בהגברא (ובמילא אויך א סיוע ונתינת כח ועזר) לקיים דבריו.\nאון די הסברה אין דעם:\nדי46 דברי הרשות של האדם זיינען בעיקרם פארבונדן מיט טבע (גופו ו)נפשו הבהמית, וועלכע איז צו זיי מתאווה מצד קיומו וחיותו47, נאר דער נפש האלקית קען פועל זיין אז די מעשים זאלן געטאן ווערן „לשם שמים\"48. אבער אויך דערנאך, פאר-בלייבן זיי „מעשיך\"48 (של האדם), דברי הרשות (ד.ה. פעולות שמצד הגוף כו').\nדאקעגן ענינים פון תומ\"צ זיינען מלכתחילה פעולות שמצד הנשמה. דער יצה\"ר פרואווט נאר שטערן דעם אידן צו מקיים זיין די מצוה. און די עשיית המצוה קומט דורכדעם וואס די נשמה איז כופה דעם יצר, ביז צו „תשש יצרו\"49, כדי זי (די נשמה) זאל קענען מקיים זיין די מצוה50.\nאון דאס איז דער טעם החילוק פון „הדיוט\" און „הקדש\":\nבשעת א איד נעמט אן החלטות טובות בשייכות צו די דברי הרשות שלו („קניית ההדיוט\"), איז וויבאלד אז די ענינים זיינען בעיקרם פעולות פון גוף ונפש הבהמית — און דער אדם האט נאך ניט קיין שליטה אויפן „גוף\" פון זיין יצה\"ר — האט זיך דא ניט אויפגעטאן קיין חיוב „ושעבוד\", ווייל ס'איז א זאך וואס איז ניט בבעלותו51:\nמשא\"כ בעניני הקדש — תורה ומצות — וועלכע זיינען בעיקרם פעולות של הנשמה (מ'דארף נאר מבטל זיין דעם שטער פון יצר הרע) — איז די החלטה טובה גופא שמצד הנשמה שוין מחייב",[["46","46","בהבא לקמן — ראה לקו\"ש חט\"ו ע' 245־6."],["47","47","ראה תניא רפ\"ז."],["48","48","אבות פ\"ב מי\"ב."],["49","49","ל' הרמב\"ם הל' גירושין ספ\"ב (בהשיעור דש\"ק זה — תשמ\"ו). ע\"ש."],["50","50","אלא מכיון שהנפה\"א מתלבשת בנפה\"ב, ועד „שבלעדו לא היתה נפה\"א פועלת בגוף כלל\" (תניא פל\"ה), לכן, ע\"י עשיית התומ\"צ דנפה\"א מתבררים כחות של הגוף ונפה\"ב."],["51","51","דגם בדבר שבא לעולם, אם הוא „דבר שאין ברשותו של מקנה אינו נקנה והרי הוא כדבר שלא בא לעולם\" (רמב\"ם הל' מכירה פכ\"ב ה\"ה). ולהעיר מד\"ה משביעין אותו להצ\"צ (קיצורים והערות לתניא (ע' מח) ועוד — נעתק בליקוט פירושים כו' לתניא פ\"א ע' יז ואילך) ד„איך מהני שבועה להנשמה על הגוף והיצה\"ר שזהו דבר שאינו ברשותו כ\"כ ולא בא לעולם עדיין\"."]]],[1300271196,"ומשעבד די נשמה52 דורכצופירן די החלטה.\n— א „הקנאה\" בפועל (בהחפצא של העשי') קען ניט זיין, ווייל דער יצה\"ר קען אין דעם שטערן ובמילא איז ניטא קיין וודאות אז עס וועט קומען לידי פועל:\nאבער לגבי הנשמה, וויבאלד אז זי איז מוכן בטבעה53 דורכצופירן די ענינים בפועל (היות אז זיי זיינען אירע פעולות, ס'איז „ברשותה ובבעלותה\") — איז חל אויף איר א חיוב ושעבוד לקיים דבריו (כאטש ס'איז עדיין לא בא לעולם — חוץ הימנה),\nאון א ציווי און חיוב פון תורה איז אויך כולל א סיוע ועזר מלמעלה, אז די נשמה זאל קענען זיך מתגבר זיין אויף די מניעות שמצד הגוף כו' און דורכ-פירן איר החלטה במעשה בפועל54.\nז. ויהי רצון, אז דורך דעם עסק אין הלכות קנין, זאל מען זוכה זיין בקרוב ממש צום קיום היעוד15 „ביום ההוא יוסיף אד' גו' לקנות את שאר עמו גו'\" — עס וועט מקויים ווערן דער16 „(עד יעבור עמך ה') עד יעבור עם זו קנית\"55, דער אויבערשטער וועט קונה זיין „עמו\" בשלימות56,\nאון דורכדעם — אויך די אנדערע „קניינים\" וואס „קנה הקב\"ה בעולמו\"57, ביז צום קנין פון „בית המקדש קנין אחד\"57, דעם ביהמ\"ק השלישי, שיבנה במהרה בימינו ממש.\n(משיחות ש\"פ ויחי תשמ\"ו, אחש\"פ תשכ\"ב)",[["52","52","ראה סהמ\"צ להצ\"צ מצוה לדון במו\"מ בסופה (לז, ב): משא\"כ ישראל שהם חלק אלקה ממעל אלא שהגוף מסתיר כו'."],["53","53","ראה רמב\"ם הל' גירושין שם."],["54","54","ראה סהמ\"צ להצ\"צ שם: מיד שנמשך כח ועוז מלמעלה להיות עוזרו . . בודאי יוגמר הקנין. ולהעיר מהמשך הרמב\"ם כאן (בהלכה שלאח\"ז — נעתק לעיל סעיף א) „והואיל והדבר כן אם צוה אדם . . לעניים . . זכו בהן העניים\", שמפשטות הלשון משמע, שמכיון שנתחייב השכיב מרע לקיים נדרו — „זכו בהן העניים\" (ולא רק שיש חיוב על היתומים ליתן להם). וראה נ\"כ הרמב\"ם שם. ואכ\"מ."],["55","55","ראה סידור ש' חג המצות בסופו, תו\"א שמות סד\"ה תפול עליהם (הגדול — רצד, א ואילך) ועוד — ד„עם זו קנית\" יהי' בהעברה (ועלי') הב' שיהי' לעת\"ל."],["56","56","משא\"כ בהגאולה מגלות בבל כו' — ראה מפרשים לישעי' שם."],["57","57","אבות פ\"ו, י. וראה ד\"ה חמשה קנינים (אוה\"ת שבועות ע' קעז ואילך). וראה הנסמן בהערה 12. לקו\"ש חל\"ה ע' 39 ואילך."]]],[1300271197,"<h3>בהר ב</h3>\nא. מ'האט שוין פיל מאל גערעדט, אז רש\"י בפירושו על התורה פאר־ענטפערט אלע שאלות וואס וערן נתעורר בפשוטו של מקרא (און אין די ערטער וואו רש\"י געפינט ניט קיין ענטפער (לויט'ן דרך הפשט) — זאגט ער „איני יודע\" וכיו\"ב¹).\nדארף מען לפ\"ז האבן א ביאור:\nאין אנהויב פון אונזער סדרה זאגט די תורה די דינים פון שמיטת קרקעות, און דערנאך — די דינים פון יובל (ובהמשך לזה — „וכי תמכרו גו' אל תונו גו'\"²). און נאך די דינים פון שמיטה ויובל כו' זאגט די תורה³: ועשיתם את חוקותי גו' ונתנה הארץ פרי' גו' וכי תאמרו מה נאכל גו' וצויתי את ברכתי גו' וזרעתם גו'.\nדארף מען פארשטיין: די שאלה „וכי תאמרו מה נאכל גו'\"⁴ שטעלט זיך דאך גלייך ביים לערנען די דינים פון שמיטה „ושבתה הארץ שבת לה' גו' שדך לא תזרע גו' לא תבצור גו'\"⁵; פארוואס פארענטפערט תורה די שאלה פון „מה נאכל\" ערשט לאחרי די דינים פון יובל⁶ (און אויך — „וכי תמכרו גו' אל תונו גו'\")?\n— ווען דער ענין וואלט געווען ניט באופן של שאלה („וכי תאמרו מה נאכל גו'\" והתשובה — „וציויתי גו'\"), וואלט מען געקענט פארענטפערן אז וציויתי גו' קומט בהמשך צו די ברכות וואס דער אויבערשטער זאגט צו אידן פאר מקיים זיין די מצות פון שמיטה ויובל⁷ („ועשיתם את חוקותי גו'\") — „וישבתם על הארץ לבטח ונתנה הארץ פרי' גו' וציויתי את ברכתי גו' ועשת את התבואה לשלש השנים\":\nוויבאלד אבער די תורה איז דא אויסן צו אראפנעמען די שאלה „וכי תאמרו מה נאכל\", האט מען דאס געדארפט באווארענען באלד ווען די שאלה וערט נתעורר (גלייך באם אנזאגן דעם דין פון שמיטה⁸).\nעס זיינען פאראן מפרשים⁹ וואס לערנען, אז די פסוקים „וכי תאמרו גו' וציויתי את ברכתי גו' לשלש השנים\" באציען זיך (אויך) אויף יובל (שלאחר שמיטה), וואס דעמאלט טאר מען ניט אקערן און זייען כו' צוויי יאר נאכאנאנד (שנת השמיטה און שנת היובל), און אויף דעם זאגט תורה „וציויתי את ברכתי גו' לשלש השנים\" — און דער־",[["1","1","פרש\"י תולדות כח, ה. ועוד (נסמנו בלקו\"ש ח\"ה ע' 1 הערה 2 בשוה\"ג)."],["2","2","כה, יד ואילך."],["3","3","שם, יח ואילך."],["4","4","שם, כ."],["5","5","שם, ב־ה."],["6","6","כמו שהקשה באלשיך כאן. ועוד."],["7","7","להעיר מפרש\"י עה\"פ (שם, יח) שבעון שמיטה כו' כנגד שבעים שמטות כו' — ולא הזכיר „יובל\". אבל ראה פרש\"י בחוקותי (כו, לה) „כנגד ע' שנות השמטה ויובל כו'\" (ע\"ש החשבון). ולהעיר מאברבנאל פרשתנו כאן (בסוף „הדרך הג'\") „היובל בכלל השמטות הוא\"."],["8","8","אבל אין להקשות מדוע לא נאמר זה בציווי על שמיטה לעיל בפ' משפטים (כג, יא) או פ' תשא (לד, כא) — כי שם נאמר הציווי רק בכללות (וראה רש\"י רמב\"ן ועוד ריש פרשתנו)."],["9","9","ראב\"ע (שם, יז), רמב\"ן (שם, כ), אברבנאל (בדרך הא' „והטענה הג'\"), ועוד."]]],[1300271198,"פאר שטייען די פסוקים הנ\"ל נאך די דינים פון יובל.\nאבער אין פרש\"י קען מען אזוי ניט איינלערנען, ווייל רש\"י¹⁰ לערנט אז די פסוקים „וציויתי את ברכתי גו' וזרעתם את השנה השמינית גו'\" ריידן ניט וועגן „שמיטה השביעית\" (וואס קומט גלייך בסמיכות פאר יובל), נאר — „מקרא זה אמר בשאר השמטות כולן\" (ניט לפני שנת היובל).\nועפ\"ז איז תמוה¹¹: פארוואס באווארנט עס ניט רש\"י, ווי אזוי ווארט מען מיט „מקרא זה\", ביז נאך די דינים פון יובל כו'?\nב. נאך א שאלה וואס רש\"י האט לכאורה געדארפט באווארענען:\nפון דעם לשון הכתוב „וכי תאמרו מה נאכל\" איז משמע אז עס איז ודאי אז מען וועט אזוי פרעגן\n[ווארום אויב כוונת הכתוב איז „שמא תאמרו\" — וואלט מער געפאסט דער לשון „ואם¹² תאמרו\" (ע\"ד „ואם אמור יאמר העבד\"¹³)],\nוע\"ד ווי רש\"י איז מפרש דעם פסוק¹⁴ (בנוגע א נביא השקר¹⁵) „וכי תאמר בלבבך איכה נדע גו'\" — „עתידים אתם לומר¹⁶ כשיבא חנני' כו'\".\nאיז ניט גלאטיק: פארוואס נוצט תורה א לשון וואס מיינט „עתידים אתם לומר\", כאילו אזוי דארף דאך זיין דער סדר ההנהגה¹⁷? —\nולכאורה: דאס פרעגן „וכי תאמרו מה נאכל\" ווייזט (לכאורה)¹⁸ אז מען פאר־לאזט זיך ניט אינגאנצן, ח\"ו, אויפן אויבערשטן. ע\"ד ווי מען האט שוין גע־לערנט ביי אברהם'ן אז א סימן אויף „והאמין בה'\" איז ווען „לא שאל לו אות\"¹⁹.\nנאכמער: גלייך פאר דער שאלה „וכי תאמרו גו'\" שטייט אין פסוק (כנ\"ל):",[["","","*) רש\"י משפטים כא, כח. ובכ\"מ."],["10","10","פרשתנו שם, כב. וראה גם פרש\"י שם, כא ובמפרשים שם."],["11","11","ראה גם אברבנאל כאן שהקשה על פרש\"י."],["12","12","וי\"ל שזוהי ג\"כ הקפידא — שאמר משה „והן\" ולא „ואם\" (שמות ד, א־ב ובפרש\"י)."],["13","13","משפטים כא, ה. וראה גם ויצא לא, ח."],["14","14","שופטים יח, כא. וראה רא\"ם וגור\"א שם, שהוכחת רש\"י היא מלשון „כי\" (ובבאר יצחק שם — שהיא מ„וכי\", בתוספת וא\"ו, והרי גם כאן נאמר „וכי תאמרו גו'\". אבל בלבוש שם שהוכחת רש\"י היא מהמשך הכתוב, ע\"ש). ולהעיר מפרש\"י עקב (ז, יז — הובא בלבוש ובאר יצחק הנ\"ל) „כי תאמר . . על כרחך לשון דילמא הוא שמא תאמר כו' ולא יתכן לפרשו כו'\" (ומשמע שאי\"ז פי' הפשוט). אבל ראה לקו\"ש חי\"ד ע' 78 הערה 3. וראה הערה 16. ואכ\"מ."],["15","15","ראה גם רמב\"ם הל' יסוה\"ת פ\"י ה\"א, שם ה\"ד (בהשיעור דיום א' פ' בהר תשד\"מ)."],["16","16","וכמפורש בתו\"כ פרשתנו עה\"פ — „וכי תאמרו עתידים אתם לומר\" (וראה מלבי\"ם כאן). ולכאורה מה שלא העתיק רש\"י זה בפירושו כאן — כי זהו פי' הפשוט (ומה שפי' כן בפ' שופטים, הוא בעיקר בשביל המשך פירושו שם — „כשיבא חנני' כו'\"). בפרש\"י ר\"ה (ג, א ד\"ה כדריש לקיש) מפורש ד„וכי תאמרו מה נאכל\" הוא ל' דילמא, שמא. אבל פרש\"י על הש\"ס — הוא פשוטו של הש\"ס, דרך ההלכה. וראה לקו\"ש חי\"ד הנ\"ל. ועצ\"ע."],["17","17","לכאורה אפ\"ל שהוא מפני שע\"פ טבע, כשהכתוב מדבר „בהווה\" — יהיו אנשים שישאלו כן (וראה מלבי\"ם כאן). ולהעיר שגם בנ\"י במדבר שאלו „מה נשתה\" (בשלח טו, כד), „מי יתן מותנו גו'\" (שם טז, ג) ועוד, אף שראו הנסים במצרים וקרי\"ס כו'. אבל — באם שאלה זו היא בלתי רצוי', לכאור' הו\"ל לרש\"י לפרש כן."],["18","18","ראה ספורנו כאן."],["19","19","לך טו, ו ובפרש\"י."]]],[1300271199,"„ונתנה הארץ פרי' ואכלתם לשובע וישבתם לבטח עלי'\". און רש\"י איז מפרש: „ונתנה הארץ וגו' וישבתם לבטח עלי' — שלא תדאגו משנת בצורת; ואכלתם לשובע — אף בתוך המעים תהא בו ברכה\".\nאיז ביותר תמוה²⁰: נאך דעם ווי די תורה זאגט אז דער אויבערשטער איז מבטיח אז עס וועלן ניט זיין קיינע דאגות מצד חסרון התבואה און אז עס וועט זיין א ברכה בלתי טבעית אין דער תבואה („אף בתוך המעים\") — ווי פאסט גלייך דערנאך די שאלה „וכי תאמרו מה נאכל\", ובפרט מיטן לשון „וכי\" — „עתידים אתם לומר\"?!\n— און מען געפינט ניט לכאורה אז רש\"י זאל פארענטפערן די שאלה בפי־רושו.\nג. ויש לומר אז דער טעם פארוואס רש\"י בפרשתנו זאגט ניט קיין תירוץ אויף די שאלות האמורות אין „וכי תאמרו\" — איז ווייל בשעת א בן חמש למקרא לערנט אין חומש און וועגן א שאלה אויף א מצוה מיט'ן לשון „וכי תאמרו\", דערמאנט ער זיך אויפן ערשטן מאל וואו ער האט געלערנט כעין זה — פריער אין סוף פרשת בא²¹: והי' כי ישאלך בנך גו'; און געדענקענדיק וואס רש\"י איז דארט מפרש דעם „כי ישאלך בנך גו'\", וערן ביי אים לויט דעם בדרך ממילא פארענטפערט די שאלות האמורות בפרשתנו:\nדער פסוק דארט זאגט „והי' כי ישאלך בנך מחר לאמר מה זאת\". שטעלט זיך רש\"י אויף „מה זאת\" און איז מפרש: „זה תנוק טפש שאינו יודע להעמיק שאלתו וסותם ושואל מה זאת, ובמקום אחר הוא אומר²² מה העדות והחוקים והמשפטים וגו' הרי זאת שאלת בן חכם. דברה תורה כנגד ארבעה בנים תם²³ רשע ושאינו יודע לשאול והשואל דרך חכמה\".\nאיז ניט פארשטאנדיק: למאי נפק\"מ אין פ' בא צו וויסן אז „במקום אחר\" איז אויך דא א „שאלת בן חכם\" (ובמילא, „דברה תורה כנגד ארבעה בנים כו'\")?\nאפילו אויב מ'זאל זאגן אז רש\"י וויל לאזן וויסן (מאיזה טעם שהוא) אז עס זיינען פאראן „ארבעה בנים\" — איז ניט גלאטיק, פארוואס זאגט ער דאס ניט פריער:\nבפירושו אויפן פסוק²⁴ „ועבדת את העבודה הזאת\" זאגט ער „חזר ושנאה בשביל דבר שנתחדש בה, בפרשה ראשונה נאמר²⁵ והי' כי יאמרו . . בבן רשע הכתוב מדבר . . וכאן והגדת לבנך²⁶ בבן שאינו יודע לשאול\" — האט",[["","","*) ובכת\"י רש\"י אחדים שתח\"י נמנו בפרש\"י כסדרם במכילתא (והגש\"פ) וירושלמי שבהערה 28."],["20","20","ראה ספורנו וכלי יקר (וראה גם מלבי\"ם) כאן. אבל ראה לקמן הערה 39."],["21","21","יג, יד. וראה שם לפנ\"ז יב, כו. וראה לקמן בארוכה."],["22","22","ואתחנן ו, כ."],["23","23","בדפוס ראשון דפרש\"י (ועד\"ז בכמה כת\"י רש\"י שתח\"י): רשע ושאינו מבין לשאול והשואל דרך סתומה והשואל דרך חכמה (ולפ\"ז נמנו כפי סדרם בקראי). אבל בדפוסי רש\"י שלפנינו (וכ\"ה בדפוס שני דפרש\"י) הוא כבפנים. — הטעם לסדרם בפרש\"י (לפי גירסא זו הנפוצה) נתבאר בהתוועדות (דליל ב' פסח) בה נאמרה שיחה זו."],["24","24","בא יג, ה."],["25","25","שם יב, כו."],["26","26","שם יג, ח (ולהעיר מפרש\"י שם, שיש בפסוק דשאינו יודע לשאול גם „רמז תשובה לבן רשע\". וראה מפרשי רש\"י. מפרשי הגש\"פ בפי' רשע מה הוא אומר. וראה לקמן הערה 35)."]]],[1300271200,"ער דארט געדארפט באווארענען מ'זאל ניט מיינען אז „דברה תורה\" בלויז כנגד שני בנים, נאר אז ווייטער אין דער פרשה קומט צו (אויך) שאלת ה„טפש\", „ובמקום אחר . . שאלת בן חכם\", אזוי אז „דברה תורה כנגד ארבעה בנים\"²⁷.\nד. וי\"ל דעם ביאור אין דעם:\nבכלל איז מען געוואוינט צו טייטשן די ווערטער „דברה תורה כנגד ארבעה בנים\" בשייכות צום חיוב פון סיפור ביציאת מצרים בליל פסח — אז די „שאלות\" פון די בנים זיינען בנוגע די מצות פון ליל פסח; און „דברה תורה כנגד ארבעה בנים\" מיינט אז תורה זאגט אז מ'זאל ענטפערן יעדערן פון די בנים לפי ענינו — אבער אלץ בנוגע לליל פסח.\nאיז אמת טאקע אז דאס איז דער מכוון פון די ווערטער לויטן דרך ההלכה (און ווי עס שטייט אין מכילתא²⁸, און אזוי זאגט מען אין הגדה של פסח) —\nאבער פרש\"י על התורה איז ענינו צו מפרש זיין פשוטו של מקרא, און אין פשטות הכתובים, איז די שאלה פון דעם „תנוק טפש\" (ניט וועגן די מצות פון ליל פסח, נאר) בנוגע למצות בכור*²⁸, וואס בהמשך לזה שטייט זיין שאלה.\n[לויט דעם וועט מען אויך פארשטיין פארוואס רש\"י נוצט דעם לשון „זה תנוק טפש²⁹ שאינו יודע להעמיק שאלתו\", און ניט — „תם\" (ווי דער לשון איז אין מכילתא³⁰ והגדה של פסח; ובפרט אז רש\"י אליין איז ממשיך (לויט דער גירסא הנפוצה בפרש\"י³¹) „דברה תורה כנגד ארבעה בנים תם כו'\")\n— ווייל פדיון בכור איז א מצוה וואס האט ניט קיין סך־פרטים, אזוי, אז אויך א בן וואס איז ניט קיין חכם (א תם) קען זיך אויך פאנאנדערקלייבן אין דעם, און ער וועט דעריבער ניט פרעגן סתם „מה זאת\"; און דער וואס פרעגט יע „מה זאת\" איז עס נאר דערפאר וואס ער איז א „תנוק טפש\".\nמשא\"כ דער „תם\" פון דער הגדה, וואס זיין שאלה איז וועגן די מצות פון פסח, קען שוין זיין פון א העכערן סוג (ניט קיין „טפש\"), ווייל בליל פסח איז פאראן א ריבוי סוגי מצות (עדות, חוקים און אויך משפטים), אין וועלכע עס איז שווער צו פאנאנדערקלייבן זיך אפילו פאר אזא וואס איז ניט קיין „טפש\", און די שאלה „מה זאת\" ווייזט נאר אז דער שואל איז א „תם\"³²].\nועד\"ז איז אויך די שאלת בן חכם בפשוטו של מקרא ניט בנוגע ליל פסח, נאר ער פרעגט וועגן מצות אין אלגע־מיין — „מה העדות והחוקים והמש־פטים אשר צוה ה\"א אתכם\" (און מ'ענטפערט אים „עבדים³³ היינו גו' ויוציאנו גו' ויצונו גו' את כל החוקים האלה ליראה גו'\", וואס דערמיט וערן געמיינט אלע מצות התורה).\nועפ\"ז איז מובן בפשטות פארוואס רש\"י ברענגט ניט די שאלות פון דעם „תנוק טפש\" און „שאלת בן חכם\" פריער",[["27","27","אבל אפשר לתרץ (בדוחק עכ\"פ) שרש\"י סומך על פירושו בסוף הפרשה, מכיון שהוא עדיין באותו ענין."],["28","28","ס\"פ בא עה\"פ והי' כי ישאלך. ובירושלמי פסחים פ\"י ה\"ד (בכמה שינויים). *28) וכפי' התיב\"ע, ספורנו, אוה\"ח ועוד שם. וראה לקו\"ש בא תשמ\"ח ס\"ו ואילך."],["29","29","וכ\"ה בירושלמי שם. יל\"ש בא שם. ועוד."],["30","30","בא שם."],["31","31","משא\"כ להגירסא שהובאה לעיל הערה 23."],["32","32","וראה לקמן הערה 36."],["33","33","ואתחנן שם, כא ואילך."]]],[1300271201,"ווען ער רעדט וועגן שאלת הרשע און שאינו יודע לשאול — ווייל דאס זיינען אינגאנצן באזונדערע ענינים:\nפריער רעדט זיך וועגן דער שאלת בן רשע און וועגן דעם „והגדת\" (צום שאינו יודע לשאול) בשייכות צו די מצות בליל פסח; האט עס ניט קיין שייכות מיט שאלת ה„טפש\", וועגן מצות פדיון בכור, ועד\"ז ניט מיט שאלת בן חכם וועגן „העדות והחוקים והמש־פטים\" (אלע מצות, אין אלגעמיין).\nה. עפ\"ז ווערט אבער נאך שטארקער די פריערדיקע שאלה: פארוואס איז רש\"י מוסיף (בהמשך צו „זה תנוק טפש . . ושואל מה זאת\") „ובמקום אחר הוא אומר . . שאלת בן חכם\" — ע\"פ הנ\"ל האט דאך די „שאלת בן חכם\" קיין שייכות ניט מיט שאלת ה„טפש\" (וואס איז א שאלה בלויז אויף פדיון בכור)!\nולאידך: אויב רש\"י פארבינדט זיי יע (אע\"פ אז זייערע שאלות זיינען ניט אין די זעלבע ענינים) — פארוואס פאר־בינדט זיי ניט רש\"י פריער, ביי שאלת הבן רשע און שאינו יודע לשאול (כנ\"ל)?\nאיז די הסברה בזה:\nבשעת מען לערנט אז בליל פסח איז דא א ציווי צו פארענטפערן די שאלה פון א בן רשע, ועד\"ז — „והגדת לבנך\" (שאינו יודע לשאול), וואלט מען גע־קענט לערנען, אז דאס איז א דין מיוחד ביי פסח: אזוי ווי יציאת מצרים איז אן ענין עיקרי בכל התורה כולה (ווי עס שטייט — בפשוטו של מקרא — אין א ריבוי פסוקים), מוז מען זיין זיכער אז אלע בנים וועלן זיך משתתף זיין אין די מצות פון ליל פסח. ובפרט נאך טענת פרעה „לכו נא הגברים\" — און ניט „טפכם\"³⁴.\nומהאי טעמא זאגט אן די תורה, אז אידן זאלן זיך פארנעמען אויך מיט א בן רשע און שאינו יודע לשאול, ווייל ביי די צוויי סוגים איז דא א חשש, אז אויב מ'וועט זיי ניט מבאר זיין די מצות פון ליל פסח, וועלן זיי ניט מקיים זיין די מצות: דער בן רשע איז דאך אזא וואס (בלשון רש\"י²⁴) „הוציא את עצמו מן הכלל\" — מוז מען אים צוריק „מכניס\" זיין אין דער „עבודה הזאת\" פון „זבח פסח\"³⁵; און א שאינו יודע לשאול איז אזא בן וואס פארשטייט אפילו ניט אז עס איז דא עפעס וואס צו פרעגן, אפילו ניט „מה זאת\" — דארף מען אים אריינ־ציען אין די מצות. און ווי רש\"י²⁴ איז מבאר דעם ענין פון „והגדת לבנך\" — „והכתוב מלמדך שתפתח לו אתה בדברי אגדה המושכין את הלב\".",[["34","34","בא יוד, יא ובפרש\"י שם."],["35","35","בא (יב, כו־כז) — בהתשובה להבן רשע, שמזה מובן שע\"י התשובה אליו („אשר פסח גו'\") משתתף הוא ב„זבח פסח\". ומה שפרש\"י להלן שם (יג, ח) „תשובה לבן רשע לומר עשה ה' לי . . שאילו היית שם לא היית כדאי ליגאל\" — הו\"ע נוסף (ודלא כמ\"ש במשכיל לדוד שם). — ועפ\"ז יש לבאר הטעם (ויתורץ) שנקט רש\"י (שם) הלשון „לא היית כדאי ליגאל\" (ע\"ד ל' הירושלמי שם „ראוי להגאל\") — ולא כלשון המכילתא (והגש\"פ) „לא היית נגאל\" — כי רק הרשעים שלא רצו לצאת ממצרים מתו בשלשת ימי אפילה (פרש\"י בא י, כב. שמו\"ר פי\"ד, ג. תנחומא וארא יד. ונת' בלקו\"ש חי\"א ע' 3 ואילך) ולא נגאלו ממצרים. אבל זה שהבן רשע „הוציא את עצמו מן הכלל\" בנוגע לק\"פ (מצה ומרור), אבל מודה הוא בשייכותו ליצי\"מ — אינו מוציאו מיצי\"מ, שלכן המענה אליו (דאילו הי' שם הי' נגאל (כמו שאר הרשעים בענינים אחרים (לא — באי רצון לצאת ממצרים) שיצאו ממצרים), אלא ש)לא הי' כדאי ליגאל. ועצ\"ק ל' רש\"י „עשה ה' לי ולא לך\"."]]],[1300271202,"משא\"כ ביי די סוגים פון „טפש\" (תם) און חכם וואלט מען געקענט מיינען, אז ס'איז ניט אזוי וויכטיק צו פארענטפערן זייערע שאלות, ווייל לגבי זיי איז ניטא דער חשש אז חסרון ההבנה וועט בריינ־גען צו ניט מקיים זיין די מצוה — עס איז בלויז א בקשת טעם והסברה. און דערפאר שטייט ניט אין תורה אז (און וואס) מען דארף זיי ענטפערן.\nבשעת אבער מען קומט צום פסוק „והי' כי ישאלך בנך\" ביי פדיון בכור, זעט מען אז (א) אויך ביי אנדערע מצות איז תורה מחייב צו ענטפערן אויף די שאלות פון א „בן\", און (ב) תורה זאגט אן (אז און — וואס) צו ענטפערן אויף די שאלות פון א „תנוק טפש\" —\nשטעלט זיך די שאלה: זיכער פרעגט אויך א בן חכם שאלות וועגן מצות, ואדרבא זייענדיק א חכם האט ער מסתם מער שאלות — איז אויב מ'דארף ענט־פערן די שאלה פון א „תנוק טפש\", איז עאכו\"כ אז די תורה האט געדארפט באווארענען צו פארנעמען זיך מיט די שאלות פון א בן חכם!\nזאגט רש\"י — אין הכי נמי: ובמקום אחר הוא אומר . . שאלת בן חכם.\nאון דאס איז דער דיוק לשון רש\"י בהמשך לזה — „דברה תורה כנגד ארבעה בנים\": דערמיט מיינט רש\"י — כפשטות הלשון — אז תורה בכלל (ניט נאר בשייכות מיט ליל פסח) רעדט וועגן אלע „ארבעה בנים\", ד. ה. מען געפינט אין תורה (שבכתב) א הוראה מ'זאל ענטפערן די שאלות פון אלע סוגי בנים, „תם³⁶ רשע ושאינו יודע לשאול והשואל דרך חכמה\".\nו. ע\"פ הנ\"ל — אז „דברה תורה כנגד ארבעה בנים\" — פארשטייט מען, אז אומעטום וואו מען געפינט אין תורה א „שאלה\" אויף א מצוה, דארף מען מברר זיין וועגן וועלכן סוג „בן\" עס רעדט דא די תורה.\n[ס'איז לאו דוקא א שאלה וואס מען מוז באווארענען בכדי צו פארזיכערן דעם קיום המצוה ביים שואל, אדער אפילו א שאלה וואס קומט מצד א ספק אדער חלישות אין אמונה — עס קען זיין א שאלת בן חכם, וואס דער צוועק פון זיין שאלה איז בכדי צו קלאר מאכן, פארשטיין פרטי הענין (ע\"ד די שאלת בן חכם — מה העדות והחוקים והמש־פטים)].\nאון אזוי אויך בענינינו: דערמיט וואס די תורה שטעלט די שאלה „וכי תאמרו\" ביים סיום דעם גאנצן ענין (אויך נאך די דינים פון יובל³⁷), און נאכמער — גלייך נאך די ברכות והבטחות פון אויבערשטן „ונתנה הארץ פרי' ואכלתם לשובע גו'\", מאכט תורה קלאר, אז דא איז עס ניט א שאלה פון א „בן רשע\" וועמען מען דארף דורך דעם ענטפער באווארענען ער זאל מקיים זיין מצות",[["36","36","עפ\"ז מובן הטעם שנקט רש\"י כאן „תם\" ולא „טפש\" כבתחלת פירושו (אבל ראה לעיל הערה 23) — כי כוונת רש\"י כאן היא לא להמדובר בפועל בפסוקים אלו דוקא, כ\"א רש\"י כותב כלל (בנוגע לכל התורה כולה) — „דברה תורה כנגד ארבעה בנים\". ולכן נקט הלשון „תם\" שהוא שם כללי (הכולל „טפש\" החסר רצון לחקור, לדעת וכו')."],["37","37","וגם לאחרי „ולא תונו\" (כה, יז) — שלא יהי' מקום לטעות שהשאלה „וכי תאמרו מה נאכל\" שייכת לקיום מצות (שמיטה או) יובל בנוגע לזריעת הארץ וכו'. — ועפ\"י המבואר בפנים יומתק ג\"כ מה ששאלות ה„תם\" וה„חכם\" — אף שלפי ההלכה היא בשייכות להמצוות דליל פסח (ויצי\"מ) — נכתבו בתורה לאחרי ההלכות דליל פסח (ובפרט שאלת בן חכם שנכתבה גם שלא בסמיכות לדיני פסח) — להדגיש שמקיימים הל' פסח ושאלתם היא, אדרבא, להוסיף בידיעה בעניני פסח, וכנ\"ל בפנים סעיף ה."]]],[1300271203,"שביעית (ווייל אין אזא פאל וואלט די תורה באווארנט גלייך ביים אנזאג פון מצות שביעית, כנ\"ל) נאר דאס איז א „שאלת בן חכם\"³⁸, און תוכן שאלתו איז:\nלערנענדיק די הבטחות פון דעם אויבערשטן „ונתנה הארץ פרי' ואכלתם לשובע גו'\" — ווייל א „בן חכם\" פאר־שטיין די פרטי ואופני הברכה: אויף וועלכן אופן וועט קומען די ברכת ה'³⁹ אין די יארן ווען „לא נזרע ולא נאסוף את תבואתנו\"?\n[ווארום עס קען זיין בכמה אופנים, און ביז — דורך געבן אין די יארן „מן\" מן השמים, אזוי ווי אין מדבר במשך פון ארבעים שנה — און מדי יום ביומו!].\n— ענטפערט מען אים, אז די ברכה וועט זיין אין אן אופן אז די ערד וועט אין דער שנה הששית ארויסגעבן א ריבוי תבואה, „ועשת את התבואה לשלש השנים\".\nז. בפנימיות הענינים:\nמען האט שוין גערעדט כמה פעמים⁴⁰ וועגן דעם וואס די תורה שטעלט אן ענין בדרך שאלה ותשובה — „וכי תאמרו מה נאכל גו' וצויתי את ברכתי גו'\" — און וויבאלד אז „התורה היא נצחית\"⁴¹, קומט אויס אז די שאלה „וכי תאמרו מה נאכל\" איז א שאלה נצחית. אויך נאכדעם ווי מען האט געזען די תוצאות טובות פון (דער תשובה —) „וצויתי את ברכתי גו'\" ביי די פריער־דיקע שמטות, קען קומען איבעראנייעס די שאלה „וכי תאמרו מה נאכל\" —\nווייל שמיטה איז די עבודה פון ביטול היש, ד. ה. אז בעצם איז דער „עובד\" א „יש\", נאר ער איז מבטל זיין יש מצד קבלת עול מלכות שמים, און מצד זיין יש בלייבט ביי אים א נתינת מקום אויף א שאלה, קשיא — און יעדן מאל בא־זונדער דארף מען אים זאגן „וצויתי את ברכתי גו'\".\nאבער לפי ביאור הנ\"ל, אז דא רעדט זיך וועגן „שאלת בן חכם\", וואס זיינע שאלות זיינען דאך ניט מצד היש ח\"ו, נאר, אדרבה, מצד החכמה — פארוואס איז דא אזא שאלה ביי א „בן חכם\"?\nאיז דער ביאור אין דעם: דער נס פון „וצויתי את ברכתי גו' בשנה הששית ועשת את התבואה לשלש השנים\" איז ניט נאר העכער פון טבע⁴², נאר ס'איז היפך הטבע לגמרי: לויט דרכי הטבע ווערט א שדה „שוואכער\" (מאגערער) פון יאר צו יאר⁴³\n— ויתרה מזה — דער דרך הטבע איז איינער פון די טעמים⁴⁴ אויף שמיטת",[["38","38","להעיר מאוה\"ח כאן."],["39","39","בספורנו וכלי יקר (וראה גם מלבי\"ם) כאן, ש„ואכלתם לשובע — בתוך המעים תהא בו ברכה\" היא הברכה שיהי' מה לאכול בשנה השביעית, כי במעוט התבואה דשנה הששית „תהא בו ברכה (בתוך המעים)\" ובמילא יהי' מה לאכול גם בשנה השביעית. אלא „וכי תאמרו מה נאכל\" (שיהי' ספק אצלכם האם יהי' כן) אזי יתן ריבוי תבואה בפשטות, „ועשת את התבואה לשלש השנים\". אבל: (א) בפרש\"י לא נזכר שברכה זו שייכת לשנה הששית דוקא, ובפשטות היא ברכה כללית שתהי' בכל השנים (ולא — בכדי שיהי' מה לאכול בשנה השביעית דוקא). (ב) משינוי לשון רש\"י בפ' בחוקותי (כו, ה) „אוכל קמעא והוא מתברך במעיו\" משמע, שכוונת רש\"י בפרשתנו „אף בתוך המעים תהא בו ברכה\", אינה להענין ד„אוכל קמעא כו'\". וראה לקו\"ש חי\"ט ע' 116 הערה 14. ואכ\"מ."],["40","40","לקו\"ש ח\"ז ע' 172. וראה גם לקו\"ש ח\"א ע' 107. ועוד. ולהעיר מאוה\"ת (להה\"מ) ריש פרשתנו."],["41","41","תניא רפ\"ז."],["42","42","ראה בארוכה כלי יקר פרשתנו עה\"פ (כה, ב) ושבתה גו'. וראה גם לקו\"ש ח\"ב ע' 548־9."],["43","43","ראה כלי יקר שם (ועוד) בנוגע ל„שש שנים תזרע שדך גו'\" (שם, ג)."],["44","44","מו\"נ ח\"ג פל\"ט. ובאברבנאל פרשתנו הקשה עליו. וראה לקו\"ש שם."]]],[1300271204,"קרקעות „ושבתה הארץ שבת לה'\" כדי „שתוסיף הארץ תבואתה ותתחזק בעמדה שמוטה\" —\nאון דוקא אין „שנה הששית\", ווען די ערד איז אין איר „שוואכסטן\" מעמד ומצב, גיט זי ארויס תבואה „לשלש השנים\"!\nאון ויבאלד דאס איז א נס וואס האט ניט קיין אחיזה כלל אין טבע — ואדרבה: ס'איז דוקא אין אן אופן פון היפך הטבע לגמרי — און ענין וואס איז לגמרי העכער פון שכל —\nפרעגט דער בן חכם „וכי תאמרו מה נאכל\": אפילו נאכן ענטפער פון „וצויתי את ברכתי\", בלייבט עס אן ענין וואס איז לגמרי העכער פון שכל.\nח. עס איז ידוע⁴⁵ אז די „שש שנים\" און די „שנה השביעית\" זיינען כנגד די שית אלפי שנין דהוי עלמא און דעם אלף השביעי.\nאיז אין דעם פאראן די שאלה „וכי תאמרו מה נאכל בשנה השביעית\"⁴⁶: געפינענדיק זיך „בשנה הששית\", אין דעם אלף הששי פאר ביאת המשיח, וואס די אלע ענינים וגילויים פון ימות המשיח זיינען „תלוי במעשנו ועבו־דתנו\"⁴⁷ איצטער — ווערט די שאלה „מה נאכל בשנה השביעית\": זייענדיק באלף הששי, וואס מצד ירידת הדורות זיינען מיר „שוואכער\" פון פריערדיקע דורות, אכשור דרא בתמי' — היינט ווי קענען מיר ממשיך זיין די גאולה, בריינ־גען „בשנה השביעית\"?\nזאגט דער אויבערשטער ומבטיח „וצויתי את ברכתי גו'\", מען טוט די עבודה פון „שנה הששית\", די עבודה בזמן הגלות וועלכע איז מתוך מסירת נפש וביטול שלמעלה מטעם ודעת, גיט דער אויבערשטער די ברכה מלמעלה, אז די זריעה פון שנה הששית — ניט קוקנדיק־אויף דעם וואס־ס'איז א „שדה כחושה\" כו' — וועט עס זיין בברכה, ובברכתו של הקב\"ה, און נאכמער — עס וועט זיין תבואה „לשלש השנים\", מ'איז ממשיך די ענינים וגילויים פון לעתיד לבא גילוי אחר גילוי אחר גילוי — וועלכע טיילן זיך בכלל אין דריי עליות⁴⁸ — „יחיינו⁴⁹ מיומים ביום השלישי יקימנו ונחי' לפניו\".\n(משיחות ש\"פ בהר תשל\"ג, תשי\"ט; ליל ב' דפסח תשכ\"ח)",[["45","45","ראה סנהדרין צז, סע\"א. ראב\"ע ורמב\"ן פרשתנו (שם, ב). אברבנאל. ועוד."],["46","46","להעיר מאוה\"ת פרשתנו ריש ע' קפז. ובארוכה ד\"ה וכי תאמרו תרע\"ח."],["47","47","תניא רפל\"ז."],["48","48","ראה המשך תרס\"ו ע' קה. וראה ס' הליקוטים — דא\"ח דהצ\"צ מע' לעתיד לבא (ע' תרכט ואילך. וש\"נ) ע\"ד ג' התקופות: ימוה\"מ, תחהה\"מ ואלף השביעי. ועוד."],["49","49","הושע ו, ב. וראה אוה\"ת עה\"פ."]]],[1300271205,"<h3>בחוקותי*</h3>\nא. אין פרק הסיום פון הלכות מלכים¹ זאגט דער רמב\"ם: אל יעלה² על הלב שבימות המשיח יבטל דבר ממנהגו של עולם, או יהי' שם חידוש במעשה בראשית, אלא עולם כמנהגו נוהג³, וזה שנאמר בישעי'⁴ וגר זאב . . משל וחידה . . שיהיו ישראל יושבין לבטח עם רשעי עכו\"ם⁵ המשולים כזאב ונמר, שנאמר⁶ זאב . . ויחזרו כולם לדת האמת, ולא יגזלו ולא ישחיתו, אלא יאכלו דבר המותר . . שנאמר⁷ וארי' . . וכן כל כיוצא באלו הדברים בענין המשיח הם משלים. ובימות המלך המשיח יודע לכל לאי זה דבר הי' משל ומה ענין רמזו בהן.\nאון דערנאך איז דער רמב\"ם ממשיך⁸ „אמרו חכמים⁹ אין בין כו'\", וכדלקמן ס\"ח.\nפון די סתירות צו דעת הרמב\"ם הנ\"ל¹⁰ — אז בימות המשיח וועט ניט בטל ווערן „דבר ממנהגו של עולם . . אלא עולם כמנהגו נוהג\" — געפינט מען לכאורה דעם מאמר אין תורת כהנים¹¹ בפרשתנו אויפן פסוק¹² „ועץ השדה יתן פריו\" — „ומנין שאף אילני סרק עתידים להיות עושים פירות ת\"ל ועץ השדה יתן פריו\"; און עד\"ז שטייט אין סוף מס' כתובות „אמר רב חייא בר אשי אמר רב עתידין כל אילני סרק שבארץ ישראל שיטענו פירות שנאמר¹³ כי עץ נשא פריו תאנה וגפן נתנו חילם\" — וואס דאס איז דאך אן ענין פון ביטול מנהגו של עולם¹⁴.",[["","","*) הדרן על הרמב\"ם (וסיום מס' כתובות)."],["1","1","פי\"ב ה\"א."],["2","2","ראה בפי' ואם יעלה על הדעת — ברמב\"ם רפ\"א (הדרן לרמב\"ם (קה\"ת, ברוקלין, יא ניסן תשמ\"ה) ס\"ט)."],["3","3","וכ\"ה בהל' תשובה פ\"ט בסופו („כמנהגו הולך\"). פיה\"מ סנהדרין — הובא לקמן הערה 77."],["4","4","יא, ו. — מה שהקשה הרמב\"ם ממה שנאמר בישעי' — ולא הקשה ממש\"נ בתורה (פרשתנו כו, ו) „והשבתי חי' רעה\" (וכהשגת הראב\"ד, הובא לקמן בפנים ס\"ג) — כי פסוק זה אפשר לפרשו כהרמב\"ן עה\"פ (וראה אגרת תחיית המתים להרמב\"ם) „שלא יבואו חיות רעות בארצכם כי בהיות השובע וברכות הטובה והיות הערים מלאות אדם לא תבואנה חיות בישוב\". ולפי\"ז אינו ביטול מנהגו של עולם ואין צריך לדחוק בכתוב שנאמר דרך משל. וראה לקמן בפנים סעיף ג."],["5","5","שינוי הצענזור וצ\"ל „גויים\" או „אומות העולם\"."],["6","6","ירמי' ה, ו."],["7","7","ישעי' שם, ז."],["8","8","שם ה\"ב. וכ\"ה במקומות שבהערה 3."],["9","9","ברכות לד, ב. וש\"נ."],["10","10","וראה דברי הרמב\"ם עצמו בזה (אגרת תחה\"מ שלו אות ו' (הובא לקמן סט\"ז))."],["11","11","הובא בפרש\"י עה\"פ."],["12","12","כו, ד."],["13","13","יואל ב, כב."],["14","14","ולהעיר דהחילוק בין שני סוגי אילנות אלו, עץ מאכל ואילני סרק, הוא גם בהלכה (וראה גם לקמן הערה 52): בעץ מאכל נאמר (שופטים כ, יט) „לא תשחית את עצה\", „רק עץ אשר תדע כי לא עץ מאכל הוא אותו תשחית וכרת\" (שם, כ), משא\"כ אילני מאכל (ב\"ק צא, סע\"ב. רמב\"ם הל' מלכים פ\"ו ה\"ח-ט)•. •) אין להקשות (ע\"פ הנ\"ל בפנים): מכיון שאילני מאכל אסור לקצוץ אפילו בחורף, שאז אין עושין פירות, כיון שבקיץ עושין — למה מותר לקצוץ אילני סרק בזה\"ז, הרי (אע\"פ שעכשיו אילני סרק הם) יטענו פירות לעת\"ל? כי התורה בעצמה חילקה בזה, ואמרה „עץ אשר תדע כי לא עץ מאכל הוא אותו תשחית גו'\", דהיינו"]]],[1300271206,"ב. לכאורה וואלט מען געקענט ענטפערן¹⁴•, אז לדעת הרמב\"ם זיינען אויך די מאמרי חז\"ל הנ\"ל א „משל וחידה\", ולדוגמא¹⁵:\nעץ מאכל מיינט (כמחז\"ל¹⁶) תלמידי חכמים, און מיט „אילני סרק\" ווערט גע־מיינט — עמי הארץ; און לעתיד לבא וועלן אויך אילני סרק — עמי הארץ — ארויסגעבן פירות, דאס הייסט — זיי וועלן ווערן תלמידי חכמים¹⁷ (אדער אן אנדער פירוש כיו\"ב¹⁸).\nמען קען אבער אזוי ניט לערנען, ווייל [נוסף אויף דעם וואס בכלל איז שווער צו זאגן¹⁹ אף דברי תנאים ואמוראים (משא\"כ דברי הנביאים) אז זיי זיינען בלויז א משל, איז נאכמער שווער בנדו\"ד, ווייל]\nדער מאמר הנ\"ל אין תו\"כ קומט בהמשך צו כמה ברכות וואס זייער תוכן איז דוקא ברכות גשמיות, כולל אויך די ברכה פון פסוק•19 „ונתנה הארץ יבולה ועץ השדה יתן פריו\" — „לא כדרך שהי' עושה עכשיו אלא כדרך שעושה בימי אדה\"ר . . נזרעת ועושה פירות בן יומה . . נטוע ועושה פירות בן יומה . . העץ נאכל\", והיינו אז די ברכה איז כפשוטה, בגשמיות ממש²⁰.\nועד\"ז אין כתובות ווערט די מימרא געבראכט בהמשך²¹ צו כמה מאמרים²² וואס מוזן געטייטשט ווערן כפשוטם, ולדוגמא²³: „ר' חנינא מתקן מתקלי' כו' קטיגוריא בת\"ח כו'\" — איז מסתבר אז אויך דער מאמר (עתידין כל אילני סרק כו') מיינט כפשוטו²⁴.",[["","","14•) ודוחק גדול לומר שהרמב\"ם ס\"ל שהמאמר בתו\"כ והמ\"ד בגמ' סוף כתובות הוא דלא כשמואל דאין בין עוה\"ז לימוה\"מ אלא כו' (שהרמב\"ם פסק כוותי' — ראה לקמן ס\"ח)•. וכדמוכח גם מזה שבפיה\"מ (שהובא לקמן הערה 77) מסביר מרז\"ל ודעת החכם דארץ ישראל תוציא גלוסקאות, ולא כתב שהוא דלא כשמואל (וכדעת חכמים בשבת סג, א)."],["15","15","ראה עד\"ז בענף יוסף לע\"י כתובות שם. ולהעיר גם מעיון יעקב שם."],["16","16","ראה תענית ז, א."],["17","17","ראה רמב\"ם סוף הל' מלכים."],["18","18","ע\"פ מרז\"ל סוטה (מו, סע\"א. וראה ב\"ר פ\"ל, ו. ועוד. וראה לקו\"ש ח\"ד ע' 1114 ואילך). „מאי פירות . . מצות\" — שגם אלו שבזה\"ז הם רק בסוג ד„מלאים מצות כרמון\" (ברכות נז, א. וש\"נ), לעת\"ל יעשו הרבה מצות ומע\"ט."],["19","19","אבל ראה רמב\"ם הל' תשובה פ\"ח ה\"ב (וראב\"ד שם). פיה\"מ שבהערה 77. שהאיסור הוא לקצוץ אילן שהוא (עתה) בסוג „עץ מאכל\" (ואילן שהוא בסוג זה — גם בחורף אסור לקצוץ); אבל אילן שאינו בסוג זה, שהוא אילן סרק, אע\"פ שלעת\"ל יטענון פירות — אינו בכלל האיסור (ובפרט ע\"פ דלקמן בפנים סעיף ו, דזה שלעת\"ל יטענו פירות הוא חידוש בהאילנות). •) ובפרט דבעל המאמר בכתובות הוא רב. 19•) פרשתנו כו, ד."],["20","20","משא\"כ במחז\"ל שבת (ל, ב) „עתידים אילנות שמוציאין פירות בכל יום\" (בלי הדגשה „בדרך שעושה בימי אדה\"ר\"), אין מוכרח שהוא כפשוטו. וראה לקמן הערה 77."],["21","21","ראה תוס' כתובות קיב, ב ד\"ה עתידין: לפי שרוצה לסיים בדבר טוב נקט לה הכא. אבל ע\"פ הידוע שגם כשמרז\"ל בא כדי לסיים בטוב וכיו\"ב ישנה שייכות ביניהם — מסתבר לומר, שעכ\"פ שווים הם בזה שכולם פירושם כפשוטם. וראה לעיל בגמ' שם קיא, ב „דאיירי בהני מילי\" (ל' התוס' שם). וראה הערה 24."],["22","22","שם קיב, א."],["23","23","שם, סע\"א ואילך."],["24","24","וגם (במאמר זה עצמו) — הרי מביא ראי' מהכתוב „עץ נשא פריו תאנה וגפן נתנו חילם\" שמדובר בפשטות ע\"ד גידול הפירות. משא\"כ לפנ\"ז בכתובות שם (קיא, ב) „אין לך כל אילן סרק שבא\"י שאינו מוציא משוי שתי אתונות\", שלמדין מהכתוב (ויחי מט, יא) „ולשורקה בני אתונו\", שאי\"ז „פשטי' דקרא\". וראה המשך הגמ' שם."]]],[1300271207,"ג. והנה אויף דברי הרמב\"ם הנ\"ל איז דא די השגה פון ראב\"ד²⁵ פון דעם פסוק (בפרשתנו²⁶) „והשבתי חי' רעה מן הארץ\", וואס איז (ניט קיין משל וחידה, נאר) אן ענין כפשוטו.\nאון דער רדב\"ז על אתר ענטפערט השגת הראב\"ד: ואין זו השגה כשם ששאר הכתובים משל גם זה משל (און איז ממשיך) אבל מה שראוי להאמין בזה שהדברים הם גם כפשוטם בארץ ישראל כדכתיב²⁷ לא ירעו ולא ישחיתו בכל הר קדשי כי מלאה הארץ, הארץ הידועה. וכן והשבתי חי' רעה מן הארץ, אבל בשאר ארצות עולם כמנהגו נוהג והכתובים הם משל שכן כתוב²⁸ ולא ישא גוי אל גוי חרב ולא ילמדו עוד מלחמה ובא\"י²⁹ יתקיים הפשט והמשל.\nועפ\"ז יש לומר, לכאורה, אז די פלוג־תא פון רמב\"ם מיטן ראב\"ד איז תלוי אין דעם חילוק צווישן די צוויי מאמרי חז\"ל הנ\"ל (פון תו\"כ און מס' כתובות) בשיי־כות צו אילני סרק:\nאין גמרא שטייט „אילני סרק שבארץ ישראל\", משא\"כ אין תורת כהנים שטייט „אילני סרק\" סתם, וואס פון פשטות הלשון איז משמע אז עס רעדט זיך ניט נאר וועגן די אילני סרק פון ארץ ישראל, נאר וועגן אלע אילני סרק שבכל העולם כולו³⁰.\nאון דער חילוק ביניהם איז: לפי התו\"כ וועט לעת\"ל זיין א שינוי אין מנהגו של עולם, אבער לויט דער גמרא וועט אין וועלט בכלל (אין חוץ לארץ) ניט זיין קיין שינוי ממנהגו של עולם, נאר אין א\"י וועט זיין א הנהגה מיוחדת.\nאון דער ראב\"ד נעמט אן כשיטת התו\"כ אז „אילני סרק (סתם) עתידים להיות עושים פירות\", דמזה מוכח, כנ\"ל, אז ס'וועט זיין ביטול מנהגו של עולם.\n[וואס אזוי איז עס אויך בנוגע זיין השגה פון פסוק „והשבתי חי' רעה מן הארץ\" אז דאס מיינט כפשוטו (דלכאו־רה, קען מען לערנען אז אויך דער פסוק מיינט בדרך משל (כנ\"ל), אבער ער איז דאס שולל) — היות אז פון דרשת התו\"כ עה\"פ — ר' יהודה אומר מעבירן מן העולם ר' שמעון אומר משביתן שלא יזיקו (ובפרט אז זיי זיינען משנה פון לשון הפסוק „מן הארץ\" און זאגן „מן העולם\") — איז מוכח אז דאס מיינט כפשוטן];\nמשא\"כ דער רמב\"ם נעמט אן (לפי דעת הרדב\"ז) כלשון הגמרא, אז דאס רעדט זיך בלויז בנוגע אילני סרק שבארץ ישראל, וואס דערפאר איז „ראוי להאמין . . שהדברים הם גם כפשוטם בארץ ישראל . . אבל בשאר ארצות עולם כמנהגו נוהג\".\nד. אבער דער פירוש הרדב\"ז איז לכאור' ניט מובן, ובפרט מסביר זיין לפי\"ז דעת הרמב\"ם:\nא) ווייבאלד דער רמב\"ם זאגט סתם אז בימות המשיח וועט ניט בטל ווערן",[["25","25","וכן בהל' תשובה פ\"ח שם."],["26","26","כו, ו."],["27","27","ישעי' יא, ט."],["28","28","שם ב, ד (ושם: לא ישא)."],["29","29","ראה ג\"כ רמב\"ן הנ\"ל הערה 4. אגרת תחיית המתים שם."],["30","30","ובפרט שבהפסוק עליו קאי (כו, ד) לא נאמר „בארצכם\", „הארץ\" וכיו\"ב (ע\"ד שנאמר בפסוק שם, ה-ו). ודוחק לומר שבא בהמשך לתחילת הכתוב „ונתנה הארץ יבולה\". אלא שי\"ל שכל הברכות לישראל — בפשטות הכוונה לבנ\"י בזמנים כתיקונם — כשישראל בארצם. וראה דרשת התו\"כ בפירוש „ונתתי גשמיכם בעתם\"."]]],[1300271208,"„דבר ממנהגו של עולם\" — איז מובן אז אין דעם איז בכלל אויך א\"י, ווייל אויב אין א\"י וועלן זיין אט די נסים בגשמיות איז דאס (אויך) ביטול מנהגו של עולם³¹.\nב) אין דער צייט פון בן כוזיבא, וואס „דימה הוא (ר' עקיבא) וכל חכמי דורו שהוא המלך המשיח³²\" — „דימה\" עד כדי כך אז מ'איז געגיינגען במלחמה (פקו\"נ) ע\"פ ציוויו. (וואס דערפון איז דער רמב\"ם³³ מוכיח אז דער מלך המשיח דארף ניט מאכן קיין אותות ומופתים, און אז אויך בימיו וועט זיין עולם כמנהגו נוהג, וכדלקמן סעיף יו\"ד) — זיינען די נסים ניט געווען אויך ניט אין ארץ ישראל.\nדעריבער איז מסתבר לומר, אז לדעת הרמב\"ם וועט לעת\"ל אויך אין ארץ ישראל זיין עולם כמנהגו נוהג.\nה. אין ספר עבודת הקודש³⁴ איז ער מסביר, אז „עולם כמנהגו נוהג\" מיינט אז דער אויבערשטער וועט לעת\"ל ניט מחדש זיין דברים חוץ מן הטבע: אלע ענינים אין דער בריאה וועלן זיין „על טבעם ושרשם כמו שהיו בתחלת הויתם ובריאתם\"³⁵. איז דעריבער קיין סתירה ניט פון דרשת התו\"כ הנ\"ל אז „העץ עתיד להיות נטוע ועושה פירות בן יומה\" ומכמה מרז\"ל כיו\"ב — ווייל דערמיט וועט זיך ניט אויפטאן א חידוש וואס איז ניט אין גדר הטבע, היות אז בתחלת הבריאה איז דער מנהג טבעי געווען אז „עושה פירות בן יומה\"³⁶.\nעפ\"ז יש לומר אויך בנוגע די צוויי ענינים שבפרשתנו — והשבתי חי' רעה מן הארץ און אילני סרק יעשו פירות — אז לדעת הרמב\"ם הייסט דאס ניט ביטול דבר ממנהגו של עולם, ווייל אזוי איז געווען דער מצב בתחילת הבריאה קודם חטא עה\"ד — דעמאלט האבן אלע אילנות נושא פירות געווען און קיינע חיות האבן ניט מזיק געווען³⁷:\nנאר דורך דעם חטא עה\"ד, ווען דער אויבערשטער האט געזאגט „וקוץ",[["31","31","ואולי י\"ל כוונת הרדב\"ז שזה יהי' בא\"י לא בתור ביטול מנהגו של עולם כ\"א רק נס דבנ\"י בא\"י, שענין שנעשה בדרך נס, מוגבל בזמן או במקום אינו ביטול מנהגו של עולם• — ע\"ד המן וכו' בהיותם במדבר, שירד להם ארבעים שנה רצופות דבר יום ביומו, ומ\"מ אינו ביטול מנהגו של עולם, מכיון שזה הי' רק בזמן ומקום מסוים, ובשאר המקומות והזמנים נשאר הטבע בתקפו. וכן זה שא\"י היא „ארץ . . צבי\" (ירמי' ג, יט. וראה דניאל יא, מא — והנסמן עה\"פ ר\"ה יג, א) בזמן שיושבי' עלי' — רווחא, ובזמן שאין יושבי' עלי' — גמדא (גיטין נז, א. ועוד); ועשרה נסים שנעשו לאבותינו בביהמ\"ק (אבות פ\"ה מ\"ה — הפרק דשבת זו (תשמ\"ה)) — שכ\"ז אינו ביטול מנהגו של עולם, אלא נס המחודש מפני דבר שנתחדש. ועד\"ז — והשבתי חי' רעה מן הארץ. וצ\"ע בהא שאבני א\"י כבידות מאבני חו\"ל (כתובות קיב, סע\"א ותוד\"ה רב חנינא שם. ערוך ערך תקל. ריטב\"א כתובות שם) — אבל דוחק לפרש כן, שתהי' הנהגה קבועה ותמידית בא\"י בימוה\"מ — באופן של נס (ולא — יבטל מנהגו של עולם)."],["32","32","ל' הרמב\"ם הל' מלכים פי\"א ה\"ג."],["33","33","שם. •) ועפ\"ז בטלה התמי' על הרמב\"ם ממש\"נ (מיכה ז, טו): כימי צאתך מארמ\"צ אראנו נפלאות."],["34","34","ח\"ב פל\"ח."],["35","35","ל' עבודת הקודש שם."],["36","36","עיי\"ש בארוכה."],["37","37","רמב\"ן פרשתנו כו, ו. וראה גם רמב\"ן דרשת תורת ה' תמימה (ירושלים תשכ\"ג) ע' קנד-ה. [משא\"כ „וגר זאב עם כבש\" (שמפרש הרמב\"ם שהוא משל) — י\"ל דס\"ל להרמב\"ם (משא\"כ להרמב\"ן) שהוא ביטול מנהגו של עולם, לפי שגם קודם החטא, כשלא הי' חיות רעות בעולם, היו בע\"ח טורפים זא\"ז בשביל מזונם (אבל לא להזיק) ולא הי' מצב של „וגר זאב עם כבש\". ואכמ\"ל. ועצ\"ע]."]]],[1300271209,"ודרדר תצמיח גו'\"³⁸, זיינען א חלק פון די אילנות געווארן אילני סרק³⁹ און אין א טייל פון די חיות איז געווארן א נטי' טבעית צו מזיק זיין³⁷.\nווייבאלד אבער אז בימות המשיח וועט די וועלט צוקומען צום מצב אין וועלכן זי איז געשטאנען קודם חטא עה\"ד⁴⁰, איז דאס טבעו און „מנהגו של עולם\" באותו הזמן⁴¹.\nו. ויש לקשר זה מיט נאך א שינוי (עיקרי) צווישן לשון התו\"כ און לשון הגמרא בנוגע צו אילני סרק: אין תו\"כ איז דער לשון „אילני סרק עתידים להיות עושים פירות\", משא\"כ אין גמרא איז דער לשון „שיטענו פירות\".\n„עושים פירות\" (ווי אין תו\"כ) איז משמע, אז די אילני סרק וועלן ארויס־געבן פירות אין דעם זעלבן אופן ווי די אלע אילני מאכל זיינען „עושים פירות\": משא\"כ לויט דער גמרא איז דאס באופן של „יטענו\", וואס ווייזט ניט אויף א גידול רגיל פון אן אילן, נאר זיי זיינען „טוען\" א זאך וואס איז בעצם ניט שייך צו זיי\n[און דאס איז בהתאם מיטן חילוק בהפסוקים פון וועלכע זיי לערנען דאס אפ: דער תו\"כ לערנט עס אפ פון פסוק\n(שבפרשתנו) „ועץ השדה יתן פריו\", וואס ווייזט אויף א נתינה רגילה פון עצי השדה; און די גמרא לערנט עס אפ פון דעם כפל ושינוי הלשון אין פסוק „כי עץ נשא פריו תאנה וגפן נתנו חילם\", וכפרש\"י: „מדכתיב תאנה וגפן נתנו חילם הרי עץ פרי אמור מה ת\"ל כי עץ נשא פריו אף אילני סרק ישאו פרי\". ד.ה. דער פסוק איז מדגיש און א) טיילט אפ דעם „עץ\" (אילני סרק) פון תאנה וגפן („עץ פרי\"), ב) אז ביי „עץ פרי\" איז דאס באופן פון „נתנו חילם\", א נתינה און ג) לויט זייער תכונה און קראפט („נתנו חילם\") און ד) בא אילני סרק איז דאס באופן פון „נשא\", כאילו אז ער איז נושא א צווייטע זאך, ניט דורך גידול רגיל⁴²].\nועפ\"י הנ\"ל יש לומר, אז דער חילוק צווישן תו\"כ און גמרא איז פארבונדן מיט דער מחלוקת וואס מען געפינט אין בראשית רבה⁴³ — צי בתחלת הבריאה האבן אילני סרק (דעתה) געהאט פירות, אדער ניט⁴⁴:\nדער תו\"כ איז קאי בשיטת ר\"פ (אין ב\"ר), וואס ער לערנט אפ פון „עץ עושה פרי (אז) אפילו אילני סרק עשו פירות\"; ולפי זה איז דאס וואס „אילני סרק עתידים להיות עושים פירות\" ניט קיין שינוי של חידוש במעשה בראשית, נאר עס איז חוזר וניעור טבע אילן זה",[["38","38","בראשית ג, יט."],["39","39","ראה רמב\"ן עה\"ת בראשית א, יא: וא\"כ נאמר כי מקללת ארורה האדמה (שם ג, יז) היו סרק (וכ\"ה באוה\"ח עה\"פ). וראה דרשת תורת ה' תמימה הנ\"ל. קרבן אהרן לתו\"כ שם."],["40","40","ראה רמב\"ן שם ובדרשת תורת ה' תמימה הנ\"ל."],["41","41","ולהעיר (יתירה מזו) מירוש' שביעית פ\"ד ה\"ח: כי עץ נשא פריו מגיד שלא נשא פריו בעוה\"ז וגפן ותאינה נתנו חילם מגיד שלא נתנו חילם בעוה\"ז."],["42","42","ראה חדא\"ג כתובות שם."],["43","43","פ\"ה, ט."],["44","44","בירושלמי כלאים פ\"א ה\"ז (לפי' הפ\"מ), לב' המ\"ד היו אילני סרק בתחלת הבריאה שלא נשאו פירות, אלא שלחד מ\"ד בזה שהוציא אילני סרק „עברה על גזירותיו של הקב\"ה\" ולחד מ\"ד „שמחה בציוויה והוסיפה אילני סרק\" — „שהן צריכין לתשמישן של אדם לעצים ולבנין\". וראה מראה הפנים לירושלמי שם. מפרשים לב\"ר שם. וראה בהנסמן לעיל הערה 39."]]],[1300271210,"וועלכע איז געווען אין עם בתחילת הבריאה,\n(און דאס קומט בהמשך צו די פריער־דיקע דרשות אין תו\"כ אויף דעם פסוק „ועץ השדה יתן פריו\", „לא כדרך שהיא עושה עכשיו אלא כדרך שעשתה בימי אדה\"ר . . עץ פרי עושה פרי למינו⁴⁵ מלמד שבו ביום שהוא נטוע בו ביום עושה פירות\". ועד\"ז דער ענין פון „העץ עתיד להיות נאכל\" אז עס וועט זיין ווי ס'איז געווען בימי אדה\"ר, ווי מ'לערנט דאס אפ פון פסוק⁴⁵ „עץ פרי\").\nמשא\"כ די גמרא האלט ווי דער מ\"ד⁴⁶ אז בתחילת הבריאה האבן אילני סרק ניט נושא פירות געווען. קומט אויס אז דאס וואס זיי וועלן נושא פירות זיין לעתיד, איז א שינוי של חידוש. און דעריבער איז דאס באופן של „יטענו\", „נשא פריו\", ניט באופן רגיל וטבעי.\nז. אבער כד דייקת שפיר קען מען אזוי ניט לערנען, ווייל:\nא) דער פירוש הנ\"ל אין תו\"כ (אז ביי אילני סרק וועט דער שינוי קענען זיין (און זיין) לעתיד ווייל אזוי איז געווען בתחילת הבריאה) — איז ניט גלאטיק:\nביי די פריערדיקע ענינים פון פסוק, שטייט אין תו\"כ בפירוש אז דאס איז „כדרך שעשתה בימי אדה\"ר\" און מ'לערנט עס אפ פון די לשונות הפסו־קים בימי אדה\"ר (במעשה בראשית); משא\"כ בנוגע צו אילני סרק שטייט ניט אין תו\"כ „כדרך שעשתה בימי אדה\"ר\" (וכיו\"ב), און דאס וואס אילני סרק עתידים להיות עושים פירות לערנט מען\nאפ פון דעם פסוק שבפרשתנו (וועל־כער רעדט בדלעת\"ל) „ועץ השדה יתן פריו\".\nב) אפילו מ'זאל לערנען אז הנאמר „כדרך שעשתה בימי אדה\"ר\" גייט אויך אויף אילני סרק⁴⁷ און דעת התו\"כ איז כדעת ר\"פ אז ס'איז געווען אזוי אויך בתחלת הבריאה — איז ניט אינגאנצן גלאטיק: דעת ר\"פ איז, אז מצד הבריאה עצמה (מצד ציווי הקב\"ה) האבן גע־דארפט זיין אילני סרק, נאר די ארץ האט משנה געווען מהציווי און אילני סרק האבן ארויסגעגעבן פירות (און נאכן חטא איז דער שינוי בטל גע־וואורן). קומט אויס, אז מנהגו של עולם (מצ\"ע) איז פארקערט⁴⁸, אז עס זאלן זיין אילני סרק.\nג) ובכל אופן: ס'איז בכלל שווער צו לערנען אזוי דעת הרמב\"ם, וואורום פון תוכן והמשך דבריו איז מוכח אז ער איז שולל ניט נאר א חידוש במעשה בראשית, והיינו שולל א זאך וועלכע איז קיינמאל ניט געווען במעשה בראשית, נאר ער איז שולל „דבר ממנהגו של עולם⁴⁹ (נאר — „עולם כמנהגו נוהג\"),",[["47","47","והיינו שמ\"ש לפנ\"ז „לא כדרך שהיא עושה עכשיו אלא כדרך שעשתה בימי אדה\"ר\" היא הקדמה כללית, ואח\"כ מפרט הפרטים „ומנין שהעץ עתיד להיות נטוע . . בן יומה . . מנין שהעץ עתיד להיות נאכל כו' ומנין שאף אילני סרק כו'\". אבל ראה רמב\"ן בראשית א, כט (בסופו) דלא הי' כן (שהעץ נאכל) לפני החטא. וכ\"ה לפרש\"י בראשית (שם, יא) שבזה קלקלה „ולא עץ פרי\"."],["48","48","אף שלהרמב\"ן (בראשית א, יא) ועוד הוא כדלעיל ס\"ה-ו, שבטבע מתחילה עשו גם אילני סרק פירות."],["49","49","ועפ\"ז מובן ב' הלשונות ברמב\"ם שם. ומה שכתבם בסדר זה דוקא — י\"ל שהם בסדר דזו ואצ\"ל זו. וראה לשונו בפי\"א ריש ה\"ג הובא לקמן בפנים ס\"י."],["45","45","בראשית א, יא."],["46","46","כ\"ה בפשטות לדעת ר\"י בר\"ש — בב\"ר שם. ולהירושלמי כ\"ה לכו\"ע (כבהערה 44)."]]],[1300271211,"און עס איז דאך פשיטא אז די ענינים (שינוים) הנ\"ל זיינען ניט „מנהגו של עולם\":\nפירוש „מנהגו של עולם\" איז ווי עולם פירט זיך בפועל בקביעות — איז קיין נפק\"מ ניט ווען די קביעות ההנהגה איז געשאפן געווארן — צי בתחילת הבריאה ממש אדער שפעטער⁵⁰; לאחרי וואס ס'איז נקבע געווארן אין דער טבע פון אילני סרק אז זיי זאלן ניט ארויס־געבן קיין פירות און אז די חיות רעות זאלן מזיק זיין און די אילנות וחיות פירן זיך אזוי טויזנטער יארן בלי שינוי — איז דאס „מנהגו של עולם\". און אויב עס ווערט א שינוי, זיי פירן זיך היפך הנהגתם זו, איז דאס ביטול דבר ממנהגו של עולם.\n(ס'האט אינגאנצן ניט קיין ארט צו זאגן, אז טבעם דאילני סרק לא נשתנה, אויך בזה\"ז זיינען זיי אילנות עושים פירות, נאר דורך א סיבה שחוץ מהם (די גזירה פון דעם אויבערשטן) איז בפועל⁵¹ וואקסן ניט קיין פירות אויף זיי (ועד\"ז בנוגע לבע\"ח); נאר דער פירוש איז אז נאכן חטא עה\"ד איז בטל געווארן זייער פריערדיקער טבע⁵², בזה\"ז זיינען זיי בטבעם אילני סרק (און — חיות טור־פות)).\nח. וועט מען דאס פארשטיין בהקדם תוספת ביאור אין דעת הרמב\"ם:\nדאס וואס דער רמב\"ם נעמט אן אז בימות המשיח עולם כמנהגו נוהג איז, לכאורה, ווייל ער האלט ווי די דיעה וואס ער ברענגט⁵³ אז „אין בין העוה\"ז לימות המשיח אלא שיעבוד מלכיות בלבד\", דעת שמואל אין גמרא⁵⁴.\nזיינען באוואוסט די קושיות וואס דער לחם משנה⁵⁵ פרעגט אויף דעם: מ'גע־פינט אז דער רמב\"ם פסק'נט להלכה בסתירה לזה:\n(א) אין גמרא שטייט⁵⁴: ואמר ר' חייא בר אבא אמר ר' יוחנן כל הנביאים כולן לא נתנבאו אלא לימות המשיח אבל לעולם הבא עין לא ראתה אלקים זולתך⁵⁶. ופליגא דשמואל דאמר שמואל אין בין העוה\"ז לימות המשיח אלא שעבוד מלכיות בלבד כו'.\nאון דער רמב\"ם פסק'נט⁵⁷ ווי ר' חייא בר אבא (דפליג אשמואל): „אמרו חכמים כל הנביאים כולן לא ניבאו אלא לימות המשיח אבל העולם הבא עין לא ראתה אלקים זולתך\".\n(ב) די משנה זאגט⁵⁸: לא יצא האיש לא בסייף ולא בקשת כו' ואם יצא חייב חטאת. ר' אליעזר אומר תכשיטין הן לו, וחכמים אומרים אינן אלא לגנאי שנאמר²⁸ וכתתו חרבותם לאתים וחניתו־תיהם למזמרות, לא ישא גוי אל גוי חרב",[["50","50","והרי אפי' כללות ההנהגה הטבעית שנקבעה באופן ש„לא ישבותו\" נעשתה רק אחר המבול (נח ח, כב)."],["51","51","ע\"ד כשאין מטר יורד."],["52","52","וי\"ל שלכן מותר להרכיב אילני סרק זה על זה אע\"פ שאינו מינו (רמ\"א יו\"ד סרצ\"ה ס\"ו. וראה שם ס\"ג וש\"ך שם סק\"ג. וכ\"ה לדעת הרמב\"ם — ראה מראה הפנים לירושלמי שבהערה 44) — כי בזה\"ז אין בהם כלל הכח והטבע לעשות פירות, ולעת\"ל יהי' זה חידוש וביטול טבעם של עכשיו."],["53","53","הל' מלכים פי\"ב ה\"ב. הל' תשובה ספ\"ט."],["54","54","ברכות לד, ב."],["55","55","הל' תשובה פ\"ח ה\"ז."],["56","56","ישעי' סד, ג."],["57","57","הל' תשובה שם, וכן בפיה\"מ סנהדרין פ\"י (בהקדמתו ד\"ה ועתה אחל) הביא מאמר דר\"ח ב\"א אר\"י וגם הא דאין בין העוה\"ז כו'."],["58","58","שבת סג, א."]]],[1300271212,"ולא ילמדו עוד מלחמה (ואי תכשיטין נינהו לא יהו בטלין לעתיד — רש\"י). און אין גמרא דארט זיינען פאראן צוויי דיעות: לויט איין דיעה האלט אויך ר' אליעזר אז כלי זיין בטלין לימות המשיח „ופליגא דשמואל . . מסייע לי' לר' חייא בר אבא\", און לויט א צווייטער דיעה האלט ר' אליעזר אז אינן בטלין לימות המשיח, „היינו דשמואל ופליגא דר' חייא בר אבא\". אבער דעת חכמים איז לכו\"ע אז כלי זיין בטלין לימות המשיח, און דעריבער אם יצא בסייף כו' — חייב חטאת.\nאון דער רמב\"ם פסק'נט⁵⁹ ווי די חכמים, וועלכע האלטן לכל הדעות ניט ווי שמואל, כנ\"ל.\nט. איז דער ביאור בזה: לכאורה, ווי זאגט דער רמב\"ם אז בימות המשיח לא יבטל דבר ממנהגו של עולם און עס וועט ניט זיין קיין חידוש במעשה בראשית — ס'איז דאך א עיקר מי\"ג העיקרים⁶⁰ אז עס וועט זיין תחיית המתים⁶¹ (וואס איז ביטול מנהגו של עולם און חידוש במעשה בראשית)?\nבשלמא לויט די שיטות⁶² אז עולם התחי' איז עולם הבא (און דער תכלית\nשלימות השכר איז צו נשמות בגופים) — איז תחיית המתים, א באזונדער ענין, ניט קיין „חלק\" פון ימות המשיח:\nאבער לויט שיטת הרמב\"ם⁶³, אז עולם הבא מיינט עולם הנשמות (בלי גופים), און עולם התחי' איז ניט דער תכלית שלימות השכר, נאר תחיית המתים וועט זיין אין דעם זמן ותקופה פון ימות המשיח איידער די נשמה קומט צו עולם הבא — קומט אויס, אז לויט שיטת הרמב\"ם וועט זיין א חידוש במעשה בראשית (תחיית המתים) אין ימות המשיח. איז ווי קען מען זאגן אז בימות המשיח לא יבטל דבר ממנהגו של עולם?\nדארף מען זאגן, אז לויטן רמב\"ם זיינען דאס צוויי באזונדערע ענינים און — אין באזונדערע זמנים: עס איז דא דער ענין וזמן אין ימות המשיח וואס איז פארבונדן מיט ביאת המשיח, און עס איז דא א באזונדער ענין וזמן נוסף, וועל־כער וועט נתוסף ווערן לאחרי תקופת התחלת ימות המשיח. עס וועלן צו־קומען הנהגות, זאכן וועלכע דער אוי־בערשטער וועט טאן אין יענעם זמן, כולל אויך ענינים פון שינוי מנהגו של עולם⁶³•. דאס וועט זיין אין א שפע־",[["59","59","הל' שבת פי\"ט ה\"א (משיעורי הרמב\"ם דשבוע זה (תשמ\"ה) — בהחלוקה דג\"פ ליום)."],["60","60","פיה\"מ להרמב\"ם סנהדרין שם בסוף הקדמתו."],["61","61","ועד שהכופר בזה אין לו חלק לעוה\"ב (משנה סנהדרין שם. רמב\"ם הל' תשובה פ\"ג ה\"ו. ובפיה\"מ שם ד\"ה ועתה אחל: ואין דת ולא דבקות בדת יהודית למי שלא יאמין זה)."],["62","62","ראה ראב\"ד הל' תשובה פ\"ח ה\"ב ובכ\"מ שם. רמב\"ן בשער הגמול. וכ\"ה ההכרעה בתורת החסידות — ראה לקו\"ת צו טו, ג. ש\"ש סה, סע\"ד. דרמ\"צ יד, ב („וכ\"ה האמת ע\"פ הקבלה\"). וראה תשובות וביאורים (קה\"ת, ברוקלין, תשל\"ד) סי\"א ע' 57 הערה 23. וש\"נ."],["63","63","הל' תשובה שם. פיה\"מ סנהדרין שם. אגרת תחיית המתים (אות ו'). וראה עבודת הקודש ח\"ב פמ\"א בארוכה. •63) עפ\"ז יומתק זה שהרמב\"ם מפרט בפי\"א שם (הובא לקמן בפנים סיו\"ד): „אל יעלה על דעתך שהמלך המשיח צריך לעשות אותות ומופתים ומחדש דברים בעולם או מחי' מתים\" — כי נקט •) אגרות קודש כ\"ק אדמו\"ר שליט\"א כרך ב' ע' עו. המו\"ל."]]],[1300271213,"טערדיקן זמן⁶⁴ אין ימות המשיח גופא⁶⁵.\nיו\"ד. ועפ\"ז איז מובן וואס אין אנ־פאנג פרק יב, ווען דער רמב\"ם שרייבט „אל יעלה על הלב שבימות המשיח יבטל דבר ממנהגו של עולם\", ברענגט ער אויף דעם ניט קיין ראי' והוכחה, ווי ער ברענגט אין דעם פריערדיקן פרק⁶⁶ אויף דעם אז משיח דארף ניט באווייזן קיין אות ומופת\n— וז\"ל: ואל יעלה על דעתך שהמלך המשיח צריך לעשות אותות ומופתים ומחדש דברים בעולם או מחי' מתים וכיוצא בדברים אלו, אין הדבר כך⁶⁷ שהרי ר' עקיבא חכם גדול מחכמי המשנה הי' והוא הי' נושא כליו⁶⁸ של בן כוזיבא המלך והוא הי' אומר עליו שהוא המלך המשיח⁶⁹, ודימה הוא וכל חכמי דורו שהוא המלך המשיח, עד שנהרג בעונות⁶⁹•, כיון שנהרג נודע להם שאינו.",[["","","הבא כל הדברים שאכן יהיו סו\"ס בימוה\"מ (כמו שתהי' תחיית המתים), אלא שכ\"ז הוא ענין נוסף שיהי' בזמן לאחר\"ז מימוה\"מ גופא, ואי\"ז ענינו של המלך המשיח וימוה\"מ בתקופה הא' כבפנים. ולהעיר מפרקי הצלחה להרמב\"ם: וזאת היא ראי' גמורה על שתחה\"מ נתלית במשיח."],["64","64","ומ\"ש הרמב\"ם באגרת תחיית המתים שם: אלא יחי' את המתים בחפצו ורצונו כאשר ירצה ולמי שירצה או בימות המשיח או לפניו או כו' — אינו חולק על מרז\"ל בכ\"מ שתחי' בזמן מסוים, כ\"א כוונתו שבכוחו ית' להחיות את המתים (כאשר ירצה) בכל זמן שירצה, וכמובא בנ\"ך וש\"ס וכו'."],["65","65","גם בשל\"ה (כג, ב) ביאר שלדעת שמואל תהיינה ב' תקופות. אבל כתב „כי אפשר שכוונת שמואל הוא עד כלות אלף הששי הזה אבל אח\"כ מודה שמואל לכל מה שאמרנו\", היינו באלף הז'. וממשיך „ואפשר אף באלף הששי מודה שמואל לכל מה שאמרנו כו' אמנם הנולדים בקדושה לא ישלוט בהם המות עוד . . וכן המתים אשר יחיו בביאת משיח כו' או ישארו חיים וקיימים\" (והוא דלא כדעת הרמב\"ם). אבל ע\"פ המבואר בפנים מוכרח לומר שגם לדעת הרמב\"ם תהי' תקופה הב' באלף הששי, ימוה\"מ שבזמן הזה."],["66","66","פי\"א ה\"ג. •) ראה ג\"כ זח\"א קלט, א. וראה שם קלד, א. •) אף שאמרו ופליגא דשמואל, י\"ל דפליגא ר\"ל יש חילוק כי כל אחד מדבר ענין אחר\" (של\"ה שם)."],["67","67","ולכן שולל הרמב\"ם (ע\"פ הלכה זו) — מרז\"ל דבדקוהו ולא הי' מורח ודאין וקטלוהו (סנהדרין צג, ב), כ\"א „שנהרג בעונות\" כדלקמן. וראה לקמן הערה 69•."],["68","68","המקור ע\"ז — וכן מקור ההיתר לחכם גדול (רב מובהק דכל הדור ופרנס דכל הדור — ספרי ס\"פ ברכה) — להיות נושא כלים — הרי יתרה מזו הנהגת דוד המלך (ש\"א טז, כא). ולהעיר שה\"ז מלחמת הצלה דכל ישראל ואה\"ק כו', וקרוב לומר שהי' פקו\"נ בגוף המלחמה לבטל (הגזירות ו)הריגות שיהיו כמה בנ\"י בחיים•."],["69","69","לא רק ב„חזקת משיח\". וראה לעיל סוס\"ד. •69) וראה גם רמב\"ם הל' תעניות פ\"ה ה\"ג: ודימו כל ישראל וגדולי החכמים שהוא המלך המשיח ונפל ביד הרומיים• ונהרגו כולם. בהשגת הראב\"ד בהל' מלכים: „והלא בן כוזיבא הי' אומר אנא הוא מלכא משיחא ושלחו חכמים לבדקו אי מורח ודאין או לא וכיון דלא עביד הכי קטלוהו\" (סנהדרין צג, ב), ובנ\"כ שם (מגדל עוז, כסף משנה, רדב\"ז (בתירוץ שני), לח\"מ) תירצו שאגדות חלוקות הן, כי באיכ\"ר (עה\"פ בלע ה' ולא חמל — ב, ב. וכ\"ה בירושלמי תענית פ\"ד ה\"ה) איתא — דלא כבגמ' — שאומות העולם הרגוהו ולא חכמים, והרמב\"ם פסק כדיעה זו. ואף דאפושי מחלוקת לא מפשינן, ובפרט מחלוקת במציאות — מי הרג את בן כוזיבא? י\"ל דאין מחלוקת במציאות, לכו\"ע (גם לדעת •) ולכן הי' נושא כליו, ולא משום ש„הי' אומר עליו שהוא המלך המשיח\". ועפ\"ז צ\"ל דהמשך ל' הרמב\"ם „והוא הי' אומר כו'\" ה\"ז ענין נוסף. •) בדפוס רומי ר\"מ „הגוים\". וראה לעיל הערה 5."]]],[1300271214,"ולא שאלו ממנו חכמים לא אות ולא מופת:\nאע\"פ אז אין די צוויי פרקים רעדט דער רמב\"ם וועגן צוויי באזונדערע ענינים: אין פרק יא וועגן מלך המשיח עצמו — וואס ער וועט אויפטאן און — אופן ביאתו; און בפרק יב — וועגן דעם מצב העולם בימות המשיח — רעדט ער אבער בפרק יב וועגן דעם מצב העולם און ווי עס איז פארבונדן מיט ביאת המשיח,\nובמילא איז די ראי' שבפרק יא לגבי מלך המשיח כחה יפה אויך לגבי דעם וואס ער רעדט אין פרק יב וועגן דעם מצב העולם בימות המשיח וואס איז פארבונדן מיט ביאתו, ומהם — אז עולם כמנהגו נוהג —\n— ווארום אויב גדר פון „ימות המשיח\" וואלט געווען ביטול מנהגו של עולם וחידוש במעשה בראשית, וואלט אויסגעקומען, אז דאס איז ענינו של משיח — ביאתו של משיח ברענגט מיט זיך אז עס זאל זיין ביטול מנהגו של עולם וחידוש במעשה בראשית, און דעמאלט וואלט מען גערארפט אנ־נעמען, אז „משיח צריך לעשות אותות ומופתים ומחדש דברים בעולם\", ובמילא איז די בחינה ובדיקה פון אמיתתו אז ער איז משיח (ווייבאלד אז אין דעם שטייט אויס חידושו, כנ\"ל);\nאון ווייבאלד אז דער רמב\"ם איז מכריח (פון ר' עקיבא וכל חכמי דורו בשייכות לבן כוזיבא) אז משיח דארף ניט מאכן קיין אות ומופת, איז דערפון",[["","","הגמ' והראב\"ד) נהרג לפועל ע\"י אומות העולם; ולכו\"ע (גם להרמב\"ם••) היו מחכמי הדור שסברו שאינו משיח, וכמו ר' יוחנן בן תורתא שאמר לר' עקיבא „עקיבא יעלו עשבים בלחייך ועדיין בן דוד לא בא\" (ירושלמי ואיכ\"ר שם) והם שלחו לבדקו אם הוא מורח ודאין, וכשראו שאינו מורח ודאין, ולפי דעתם (משא\"כ לדעת רע\"ק וכן פסק הרמב\"ם) ה\"ז סימן שאינו מלך המשיח, ומכיון שעשה מלחמות עם העמים בחזקת שהוא המלך המשיח אף שלא הי' מורח ודאין (כי סבר כרע\"ק) ונפלו רבים מבנ\"י כו' — יש לו דין רודף (ראה סנהדרין עג, א. וש\"נ) שצריך להרגו. אבל בפועל אוה\"ע הרגוהו. ובסגנון לשון הרדב\"ז שם: „ויש לפרש הא דאמרינן בפרק חלק, כיון דחזיוהו דלא מורח ודאין קטלוהו כלומר רפו ידיהם ממנו ובאו הגויים והרגוהו\"•••. ומחלוקת הרמב\"ם והראב\"ד בזה היא••••: לשיטת הרמב\"ם (ע\"פ דעת רע\"ק) שמשיח אינו צריך לעשות אותות ומופתים — הרי פשוט שנהרג לא מחמת שלא הי' מורח ודאין, שהרי גם מופת זה אינו צריך להראות (בתחילת ביאתו). ולכן כתב „שנהרג בעונות\". והראב\"ד שפוסק (ע\"פ הגמ' סנהדרין ודעת ר\"י בן תורתא) שמשיח צריך לעשות אותות ומופתים מיד בתחילת התגלותו — ס\"ל שנהרג מחמת שלא הי' מורח ודאין, ואע\"פ שבפועל הרגוהו אוה\"ע, גברא קטילא (ע\"פ פס\"ד ב\"ד) קטלו (כרדב\"ז לעיל) ואולי יתירה מזה — כשאין ב\"ד יכולים לקיים עונש שפסקו מקיימין אותו ע\"י אחר (טושו\"ע חו\"מ ס\"ב ובנ\"כ שם) — משא\"כ להרדב\"ז דקשה מגט, ש„אם הגוים מעצמן אנסוהו עד שכתב הואיל והדין נותן שיכתוב הרי זה גט פסול\" אף שלא בטל (רמב\"ם הל' גירושין ספ\"ב). ••) ומ\"ש הרמב\"ם (בהל' מלכים) „ודימה הוא וכל חכמי דורו שהוא המלך המשיח\" — עכצ\"ל שכוונת הרמב\"ם היא רק שבתחילה „דימו\" כל חכמי דורו שהוא משיח, אבל אח\"כ כמה מהם הסיקו שאינו משיח (כמפורש בחז\"ל, כבפנים ההערה), אלא שהרמב\"ם לא פסק כמותם. גם י\"ל שהרמב\"ם ס\"ל שרוב חכמי ישראל, או עכ\"פ „גדולי החכמים\" (כלשונו בהל' תעניות שם) סברו כרע\"ק, ולכן כתב „כל\". ולהעיר שבא' מכתבי הרמב\"ם, הלשון „ודימו הוא וחכמי דורו\", בלי תיבת „כל\" (ע\"ד לשונו בהל' תעניות שם). •••) ובתשובות וחי' מרב סעדי' אבן דנאן (נדפס בתשובות הרמב\"ם פאר הדור סי' רכה, ועוד): ורז\"ל אמרו בסנהדרין פ\"ח שחכמי ישראל הרגוהו על שאמר שהוא משיח והוא לא הי' מזרע דוד. אבל ראה ברטנורה לדות ד, ו. ••••) ראה כס\"מ, דהא דאמרו בפרק חלק אתיא דלא כשמואל כו' ורבינו סובר כשמואל כו'."]]],[1300271215,"מובן ומוכח אז ביאת משיח ברענגט ניט מיט זיך ביטול מנהגו של עולם⁷⁰.\nיא. ועפ\"ז איז פארשטאנדיק, אז דאס וואס דער רמב\"ם איז מאריך אין פרק יב בנוגע דעם מצב העולם בימות המשיח — איז דאס אלץ בנוגע דעם ענין וזמן אין ימות המשיח וועלכער איז פאר־בונדן מיט מלך המשיח וביאתו.\nדאס הייסט: פריער — אין פרק יא איז דער רמב\"ם מבאר⁷¹ וואס עס איז ענינו של מלך המשיח — „המלך המשיח עתיד לעמוד ולהחזיר מלכות דוד ליושנה לממשלה הראשונה ובונה המקדש ומקבץ נדחי ישראל וחוזרין כל המשפטים כו'\", ער וועט ברענגען די שלימות אין מצות והלכות התורה⁷².\nדערנאך — אין פרק יב רעדט דער רמב\"ם ווי דער מצב העולם וועט זיין בהתאם לזה, ווי ער איז מסיים⁷³ אז אידן\nוועלן זיין „פנויין בתורה וחכמתה . . ובאותו הזמן לא יהי' שם לא רעב ולא מלחמה כו' ולא יהי' עסק כל העולם אלא לדעת את ה' בלבד ולפיכך יהיו ישראל חכמים גדולים וכו'\" — (ועיקר⁷⁴) קיום המצות והלכות התורה איז אין אן עולם וואס כמנהגו נוהג.\nיב. ע\"פ כהנ\"ל וועט מען אויך פאר־שטיין שיטת הרמב\"ם בשייכות די פאר־שידענע פסוקים ומאמרי חז\"ל וועגן די יעודים וכו' דלעתיד:\nדי יעודים און נבואות וועלכע ריידן וועגן משיח'ן גופא, וואס ער וועט טאן און וואס עס וועט ארויסקומען בעולם ע\"י ביאתו — לערנט דער רמב\"ם אז זיי זיינען ניט קיין ענין פון ביטול מנהגו של עולם. און דערפאר איז ער מפרש דעם פסוק „וגר זאב עם כבש גו'\", וואס שטייט בהמשך צו „ויצא חוטר מגזע ישי גו'\"⁷⁵, אז דאס איז „משל וחידה\".\n[און טייטשט אפ בפירוש וואס איז דער משל וחידה פון דעם פסוק „שיהיו ישראל יושבין לבטח עם רשעי עכו\"ם\" — ואע\"פ וואס ער איז ממשיך „וכן כל כיוצא באלו הדברים בענין המשיח הם משלים\" און זאגט ניט וואס די נמשלים זיינען, אדרבה ער פירט אויס „ובימות המלך המשיח יודע לכל לאי זה דבר הי' משל\" — וואורום ער קומט (בעיקר) מסביר זיין אין דעם פסוק וועלכער קומט בהמשך צו „ויצא חוטר גו'\" מבואר ענינו של משיח, אז אידן וועלן",[["70","70","ומה שאעפ\"כ מתחיל ברפי\"ב „אל יעלה על הלב שבימות המשיח כו'\" הרי מדייק (לא „אל יעלה על הדעת\", ע\"ד הל' בפי\"א שם, כ\"א) „על הלב\"• — שאינו בא לשלול קס\"ד בדעת שבימות המשיח יבטל דבר ממנהגו של עולם, כ\"א אף שבדעת, עד כמה ששכלו ודעתו משיגים מעלת ועניין המשיח (ובמילא — דימות המשיח) — אינו שולט ומושל על לביטול מנהגו של עולם, בכ\"ז אפשר אשר מצד אה\"ר ותשוקת הלב להמעלות ד„ישכיל . . ירום ונשא וגבה מאד\" (ישעי' נב, יג. וראה רמב\"ם הל' תשובה פ\"ט ה\"ב ולקמן כאן. שער האמונה לאדמהאמ\"צ פנ\"ו ואילך. ביאוה\"ז כב, ג) יעלה על לבו שיבטל דבר ממנהגו של עולם. וג\"ז בא לשלול. ואכ\"מ."],["71","71","ה\"א."],["72","72","ראה בארוכה לקו\"ש חי\"ח ע' 277 ואילך. וש\"נ."],["73","73","פי\"ב ה\"ד-ה. •) ולהעיר שבכת\"י תימן גם כאן הלשון „על הדעת\"."],["74","74","להעיר משני הפירושים בענין: והנשיאים הביאו (יומא עה, סע\"א. תיב\"ע ויקהל לה, כז (רבינו בחיי שם). פרש\"י שם מספרי נשא ז, ג. ועוד): חטים שירדו בעבים (מנחות סט, ב. רש\"י ותוס' שם). ועוד."],["75","75","ישעי' יא, א ואילך."]]],[1300271216,"ניט האבן קיין בלבולים פון אוה\"ע ובמילא „יהיו פנויין בתורה וחכמתה\" כו'⁷⁶];\nמשא\"כ די פסוקים און מאמרי רז\"ל וועלכע ריידן ניט בהמשך צו משיח וביאתו, נאר וועגן נבואות וייעודים וואס וועלן זיין לעתיד לבא, כולל די אויבנ־דערמאנטע: „והשבתי חי' רעה מן הארץ\" און מרז\"ל הנ\"ל אז אילני סרק עתידים להיות עושים פירות — איז דער רמב\"ם טאקע מפרש אז זיי זיינען ניט קיין משל נאר כפשוטם, און דאס וועט זיין אין א שפעטערדיקער תקופה (תקופה אין ימות המשיח גופא)⁷⁷.\nיג. ע\"פ הנ\"ל וועט מען אויך פאר־שטיין דעם חילוק צווישן דעם מאמר אין תו\"כ און די מימרא אין כתובות:\nדי גמרא אין כתובות „עתידין כל אילני סרק שבא\"י שיטענו פירות\", וואס ווייזט אז דאס איז ניט קיין ענין טבעי, נאר אן ענין מיוחד, און אין א\"י דוקא, רעדט וועגן דער ערשטער תקופה, וואס דעמאלט — לדעת מ\"ד זה בכתובות — וועט זיין א חידוש (נס) אין ארץ ישראל,\nאין תו\"כ וואו עס שטייט סתם „אף אילני סרק עתידים להיות עושים פירות\", אז אזוי וועט זיין דער טבע פון די אילנות און — בכל העולם, רעדט זיך וועגן דער צווייטער תקופה אין ימות המשיח, וואס דעמאלט וועט זיין א שינוי של חידוש במעשה בראשית, במילא וועט ווערן דער טבע (אויך) פון דעם אילן סרק להוציא פירות.\nיד. ועפ\"ז מובן אז ס'איז ניט קיין סתירה פון דברי הרמב\"ם אז „אין בין העוה\"ז לימות המשיח אלא שיעבוד מלכיות בלבד\", וואס גייט אויף דער ערשטער תקופה פון ימות המשיח, צו זיין פסק אז „כל הנביאים כולן (לא) ניבאו (אלא) לימות המשיח וכו'\" — וואס גייט אויף דער שפעטערדיקער תקופה אין ימות המשיח.\nאון ס'איז אויך מובן זיין פסק אז היוצא בכלי זיין בשבת חייב חטאת, ווייל דעם פסוק „וכתתו חרבותם לאתים\", וואס רעדט וועגן דעם מצב בעולם וואס וועט זיין לעתיד לבא, לערנט דער רמב\"ם כפשוטו, און ניט דרך משל בלבד — און דאס וועט זיין אין דער שפע־טערדיקער תקופה פון ימות המשיח. און היות אז כלי זיין בטלים אין יענער תקופה (עכ\"פ) פון דער גאולה⁷⁸, איז עס",[["76","76","ולהעיר מדיוק לשון הרמב\"ם „וכן כל כיוצא באלו הדברים בענין המשיח (ולא בימות המשיח) הם משלים\"."],["77","77","ומה שהרמב\"ם כתב בפירוש המשניות (סנהדרין בהקדמה לפ' חלק) דמחז\"ל שבת (ל, סע\"ב) עתידה א\"י שתוציא גלוסקאות וכלי מילת; הפי' „לפי שבנ\"א אומרים כשימצא אדם דבר מוכן ומזומן פלוני מצא פת אפוי ותבשיל מבושל . . ולכן קצף החכם הזה שאמר המאמר על תלמידו כשלא הבין דברו וחשב שהוא על פשוטו והשיבו כפי השגתו ולא היתה אותה התשובה תשובה האמיתית והראי' על שלא השיב לו על אמיתתו — מה שהביא ראי' אל תען כסיל כאולתו\" — שמפרש דלא כפשוטו, אף שבפשטות מזה שאחוי לי' ר\"ג משמע שכוונתו כפשוטו — כי הכתוב „יהי פסת בר בארץ\" (תהלים עב, טז) שממנו למדו ש„עתידה כו'\" — בא בהמשך להכתוב (שם, א) לשלמה אלקים משפטיך למלך תן וצדקתך לבן מלך דקאי על מלך המשיח. ועד\"ז הוא בנוגע לשאר המימרות בשבת שם לפנ\"ז — אף שבכולם אחוי לי' (שמשמע שהכל כפשוטו), כי בכל הפסוקים מדובר בהמשך לביאת מלך המשיח והגאולה שעל ידו, ולא סתם תיאור מצב שיהי' בעולם בפ\"ע."],["78","78","משא\"כ בתקופה הא' דימוה\"מ, אף שגם אז „לא יהי' שם לא רעב ולא מלחמה\" (רמב\"ם הל' מלכים ספי\"ב) — אין ראי' שכלי זיין יבטלו, כי אם"]]],[1300271217,"א באווייז אז כלי זיין, זיינען ניט קיין תכשיטין.\nטו. ע\"פ הנ\"ל איז פארענטפערט נאך אן ענין:\nאין דער גמרא הנ\"ל (כל הנביאים לא נתנבאו אלא לימות המשיח כו') ווערט געבראכט בהמשך לזה: ואמר ר' חייא כו' כל הנביאים כולן לא נתנבאו אלא לבעלי תשובה, אבל צדיקים גמורים עין לא ראתה אלקים זולתך. ופליגא דר' אבהו דא\"ר אבהו מקום שבעלי תשובה עומדין⁷⁹ צדיקים גמורים אינם עומדין⁸⁰.\nאון ווייבאלד אז אין גמרא ווערן ביידע מימרות פון רחב\"א אר\"י געבראכט בהמשך זו לזו — איז משמע אז זיי זיינען שייך איינע צו דער צווייטער. ד.ה.: לשיטתו אז „כל הנביאים כולן לא נתנבאו אלא לימות המשיח כו'\", דארף מען אויך זאגן אז „כל הנביאים כולן לא נתנבאו אלא לבע\"ת כו'\" — ניט ווי ר' אבהו (און ניט ווי שמואל).\nגעפינט מען אבער אז דער רמב\"ם, כאטש ער זאגט „אמרו חכמים כל הנב־יאים כולן לא ניבאו אלא לימות המשיח\nכו'\" (כנ\"ל ס\"ח), פסק'נט ער⁸¹: „אמרו חכמים מקום שבע\"ת עומדין אין צדיקים גמורין יכולין לעמוד בו\",\nוע\"פ הנ\"ל איז מובן: ווייל דאס וואס רחב\"א אר\"י האלט אז צדיקים גמורים זיינען גרעסער ווי בע\"ת — איז דאס לשיטתי' אז אויך בתחילת ימות המשיח וועט זיין ביטול מנהגו של עולם און אויף דעם „נתנבאו כל הנביאים\";\nאבער לשיטת הרמב\"ם אז בתחילת ימות המשיח איז עולם כמנהגו נוהג — איז דאס ניט מכריח אז צדיקים גדולים מבעלי תשובה⁸².\nטז. לאחרי כל הנ\"ל איז אבער נאך אלץ ניט מוסבר: ווייבאלד אז דער גדר פון ימות המשיח (וואס קומט בהמשך צו ביאת המשיח) איז (לדעת הרמב\"ם) פארבונדן מיט דעם וואס עולם כמנהגו נוהג — פארוואס איז מוכרח אז בימות המשיח גופא זאל זיין נאך א תקופה וואס דעמאלט וועט זיין ביטול מנהגו של עולם? און (— ועיקר) וואס איז די סיבה נפלאה, וועלכע וועט שאפן און ברענגען א חידוש נפלא — די הנהגה פון דער צווייטער תקופה?\nוועט מען דאס פארשטיין בהקדם וואס דער רמב\"ם שרייבט אין אגרת תחיית המתים שלו⁸³, אז דאס וואס ער האט מפרש געווען די יעודים דלעתיד (וגר זאב עם כבש וכיו\"ב) אז זיי זיינען „משל וחידה\" — „אין דברנו זה",[["","","שמכיון „שהטובה תהי' מושפעת הרבה וכל המעדנים מצויין כעפר\" (כהמשך לשון הרמב\"ם שם) „לא יהי' רעב ומלחמה\" בפועל, אבל לא שישתנה טבע בנ\"א, ויבטלו הכלי זיין. ולהעיר מ„יקומו נא הנערים וישחקו לפנינו\" (ש\"ב ב, יד) — בכלי זיין (חרב) אבל באופן של שחוק (לראות מי מלומד בשימוש בחרב יותר, ועד שפך דם) ולא מלחמה (מצו\"ד שם ועוד). וראה כלים רפכ\"ד."],["79","79","וי\"ל דלר' אבהו עין לא ראתה אלקים זולתך — על בע\"ת נאמר."],["80","80","גירסת הרמב\"ם (הל' תשובה דלקמן בפנים): אין צד\"ג יכולין לעמוד. וכ\"ה בדק\"ס ברכות מ„גליון\". ובכ\"מ בדא\"ח „צ\"ג אין יכולין לעמוד (שם)\"."],["81","81","הל' תשובה פ\"ז ה\"ד."],["82","82","טעמו של הרמב\"ם לפסוק כרב אבהו (וכן מובא בפשיטות בכמה מקומות בדא\"ח) — ראה לקו\"ש חי\"ד ע' 361 ואילך."],["83","83","אות ו'."]]],[1300271218,"החלטי⁸⁴ כו' שהם משל\", און עס קען זיין אז זיי זאלן נתקיים ווערן כפשוטם⁸⁵.\nולכאורה: לפי הנתבאר לעיל (סעיף יא־יב) איז דאך מוכרח צו לערנען אז די יעודים וואס רעדן בשייכות צו משיח וביאתו זיינען ניט קיין ביטול דבר ממנהגו של עולם — ווייל דער גדר פון משיח איז צו אויפטאן אין דעם עולם ווי ער איז „כמנהגו נוהג\" דוקא (כנ\"ל)?\nיז. ויש לומר הביאור בזה:\nעס איז ידוע וואס די גמרא זאגט⁸⁶ לגבי די סתירת הפסוקים „כתיב⁸⁷ וארו עם ענני שמיא כבר אינש אתה וכתיב⁸⁸ עני ורוכב על חמור, זכו עם ענני שמיא לא זכו עני ורוכב על חמור\" (ועד\"ז פאר־ענטפערט די גמרא⁸⁹ די סתירות אין אנ־דערע פסוקים כיו\"ב).\nדערפון איז מובן לגבי אנדערע ענינים שבימות המשיח, אז בשעת אידן זיינען אין א מצב של „זכו\", וועלן אלע ענינים זיין דעמאלט באופן אחר לגמרי, אופן נסי⁹⁰.\n[וואס דאס איז איינער פון די אופני התיווך אין דער פלוגתא בנוגע בנין המקדש דלעתיד: בכמה מקומות⁹¹\nשטייט אז דער מקדש השלישי איז „בנוי ומשוכלל הוא יגלה ויבוא משמים\"⁹², און אין אנדערע ערטער שטייט⁹³ (און אזוי פסק'נט דער רמב\"ם⁹⁴) — אז משיח בונה מקדש:\nדאס איז תלוי אין די צוויי אופנים הנ\"ל אין דער גאולה, אז אויב „זכו\" איז „יגלה ויבוא משמים\", משא\"כ אויב לא זכו וועט זיין דער בנין בידי אדם⁹⁵ (ע\"י משיח⁹⁶)].\nאון דאס וואס דער רמב\"ם פסק'נט בס' היד, ספר הלכות הלכות, אז עס וועט ניט זיין קיין ביטול דבר ממנהגו",[["84","84","כ\"ה בתרגום קאפח. ובתרגום ר' שמואל אבן תיבון „אין דברנו זה גזירה\"."],["85","85","עיי\"ש בפרטיות."],["86","86","סנהדרין צח, א."],["87","87","דניאל ז, יג."],["88","88","זכרי' ט, ט."],["89","89","סנהדרין שם."],["90","90","ראה כרו\"פ (יו\"ד סק\"י סוף בית הספק): אוצר בלום על־פי סנהדרין שם — שבזה תלוי ג\"כ אם אליהו בא מאתמול לפני ביאת המשיח. וראה רמב\"ם הל' מלכים פי\"ב ה\"ב."],["91","91","פרש\"י סוכה מא, סע\"א. ר\"ה ל, סע\"א. וכ\"ה בתוס' סוכה שם. שבועות טו, ריש ע\"ב ד\"ה אין, ומסיים „וכן מפרש במדרש תנחומא\" (וי\"ל שהכוונה לתנחומא פקודי יא). זח\"א כח, א. ח\"ב נט, סע\"א. קח, סע\"א. ח\"ג רכא, א. יל\"ש תהלים רמז תתמא בסופו, תתמח בסופו. וראה תנחומא (באבער) בראשית יז (בסופו)."],["92","92","ל' רש\"י סוכה שם."],["93","93","ירושלמי מגילה פ\"א הי\"א. ויק\"ר פ\"ט, ו. במדב\"ר פי\"ג, ב. וראה גם ירושלמי פסחים פ\"ט ה\"א (תוספתא פסחים פ\"ח, ב) — לגי' ופי' המנ\"ח מצוה שם."],["94","94","הל' מלכים רפי\"א ובסופו."],["95","95","עפ\"ז מתורצת ג\"כ הדיעה הנ\"ל שהמקדש יגלה ויבוא משמים, ולכאורה: הרי מסופר במדרש (ב\"ר ספס\"ד) ש„בימי ריב\"ח גזרה מלכות הרשעה שיבנה ביהמ\"ק הושיבו כו' והיו מספקין לעולי גולה כסף וזהב וכל צרכם כו'\" כדי לבנות ביהמ\"ק (ולא ציפו שיגלה ויבוא משמים) — ותמוה דעה הנ\"ל, שה\"ז מעשה רב שיבנה בידי אדם (וראה גם מנ\"ח מצוה צה) — אלא דבימי ריב\"ח הי' מצב דלא זכו (וכדמוכח מזה גופא שהיו זקוקים לזה שתגזור מלכות הרשעה), ולכן הי' ביהמ\"ק נבנה ע\"י בנ\"י דוקא."],["96","96","כלשון הרמב\"ם שם. והוא דעת ר' אליעזר בויק\"ר ובמדב\"ר שם — משא\"כ בשאר מקומות הנ\"ל (הערה 93) לא נאמר שיהי' ע\"י משיח דוקא. ובזה מתורץ זה שבימי ריב\"ח רצו לבנות ביהמ\"ק בלא משיח — כי זה שמשיח (דוקא) יבנה ביהמ\"ק הוא חידוש תלמיד ותיק — ר\"א שהי' לאחר זמן ריב\"ח."]]],[1300271219,"של עולם — איז עס ווייל דער ענין פון משיח וביאתו והגאולה בכלל — איז א הלכה, הלכה ברורה ופסוקה. און אזוי איז אויך דער אופן אין דעם, אז ער איז ניט תלוי באופן דמעשה בנ\"א (משא\"כ הגאולה באופן דארו עם ענני שמי' וכיו\"ב — וועלכער איז תלוי אין דעם אז ביי אידן איז א מצב פון „זכו\" — וואס איז ניט ברור ופסוק, ווייל הכל בידי שמים חוץ מיר\"ש⁹⁷ והרשות לכל אדם נתונה כו'⁹⁸),\nאון דעריבער איז דער רמב\"ם מתאר די גאולה אין דעם אופן ווי ס'איז א הלכה, מוכרח צו זיין (אומאפהענגיק פון דעם מצב פון אידן).\nיח. בעומק יותר: דאס וואס דער רמב\"ם מתאר די גאולה באופן אז עס וועט ניט זיין קיין ביטול דבר ממנהגו של עולם איז (ניט ווייל דער רמב\"ם מתאר די גאולה אז זי וועט קומען באופן של לא זכו ח\"ו, נאר) ווייל דער רמב\"ם לערנט, אז דאס וואס חז\"ל זאגן אז ווען ס'איז א מצב פון „זכו\" וועלן זיין כו\"כ עילויים מיט א הנהגה נסית כו', איז דאס אן ענין נוסף אויף עצם גדרו של משיח.\nדאס הייסט: מצד גדרו של משיח וביאתו — איז דער סדר פון „עולם כמנהגו נוהג\", ווייל דער אויפטו פון ביאת המשיח בהלכה איז — וואס דורך אים וועט זיין די שלימות פון קיום מצות והלכות של תורה (וואס איז פארבונדן מיט אן עולם וואס „כמנהגו נוהג\");\nנאר בשעת אידן זיינען אין א מצב נעלה פון „זכו\", וועט זיין אן ענין נוסף,\nאז דער אויבערשטער וועט באווייזן נסים וכו' אויף צו ארויסווייזן די תוספת החביבות און מעלה פון אידן.\n[ועד\"ז בנוגע דעם תיווך הנ\"ל בבנין המקדש דלעתיד: דער פירוש בזה איז (ניט אז דער „יגלה ויבוא משמים\" איז בסתירה צו „משיח בונה מקדש\", נאר) — אז מצד גדר ההלכה איז דער ענין פון בנין ביהמ\"ק א חיוב מצוה אויף אידן, וכמש\"נ⁹⁹ ועשו לי מקדש און דערפאר פסק'נט דער רמב\"ם אז משיח — וואס דורך אים „חוזרין¹⁰⁰ כל המשפטים בימיו כשהיו מקודם\" און מונין מלך (און דערנאך) בונה ביהמ\"ק¹⁰¹ — מלך המשיח וועט דורכפירן די מצוה פון בנין ביהמ\"ק;\nאון דער מצב פון „זכו\" טוט אויף א הוספה, אז אין דעם „מקדש דלמטה\" יבא און זאל זיך „אנטאן\" דער „מקדש דלמעלה\", „יבא ויגלה משמים\"¹⁰²].\nיט. ועפ\"ז איז מובן דער הכרח אויף דער צווייטער תקופה בימות המשיח — ווארום לאחרי ביאת המשיח (באיזה אופן שהיא), ווייבאלד אז אידן וועלן דעמאלט ניט האבן קיין „נוגש ומבטל\"¹⁰³ ש„אינן מניחות להן לעסוק בתורה ובמצות כהוגן\"¹⁰⁴, ואדרבה — מ'וועט זיין „פנויין בתורה וחכמתה\"¹⁰³ ביז אז אפילו „עסק כל העולם\" (כל",[["97","97","ברכות לג, ב."],["98","98","רמב\"ם הל' תשובה רפ\"ה."],["99","99","ראה רמב\"ם הל' ביהב\"ח בתחלתן: ועשו לי מקדש כו' בנין העתיד להבנות כו'."],["100","100","רמב\"ם הל' מלכים רפי\"א."],["101","101","רמב\"ם הל' מלכים בתחלתו. וראה לקו\"ש חט\"ז ע' 304 והערה 49 שם."],["102","102","ראה גם לקו\"ש חי\"ח ע' 418 ואילך ובהנסמן שם."],["103","103","רמב\"ם הל' מלכים פי\"ב ה\"ד."],["104","104","רמב\"ם הל' תשובה פ\"ט ה\"ב."]]],[1300271220,"האומות) וועט זיין „לדעת את ה' בלבד ולפיכך יהיו ישראל חכמים גדולים כו' כמים לים מכסים\"¹⁰⁵ — וואס דאס איז די שלימות המצב פון „זכו\" — וועט דאך דאס ברענגען מיט זיך בהכרח די (צווייטע) תקופה (אין ימות המשיח גופא), ווען עס וועט זיין ביטול מנהגו של עולם, די הנהגה נסית (כולל דעם ענין היסודי — כלשון הרמב\"ם¹⁰⁶ — תחיית המתים).\nאון דערפאר: אין ספר היד, וואו דער רמב\"ם איז מסביר דעם גדר פון משיח\nוביאתו ע\"פ הלכה — איז ער מסביר ווי דער מצב העולם וועט זיין אין א (זמן ו)אופן פון „עולם כמנהגו נוהג\" (בהתאם צו ענינו וגדרו של משיח);\nאבער אין אגרת תחיית המתים איז ער מוסיף (ביאור בספר היד) אז „אין דברנו זה החלטי\" — ווייל ווען עס איז א מצב פון „זכו\" נאך זייענדיג אין גלות, וועט בפועל זיין — גלייך בתחילת הגאולה — די הנהגה מיוחדת מלמעלה, די הנהגה פון ביטול מנהגו של עולם וכימי צאתך מארץ מצרים אראנו נפלאות¹⁰⁷.\n(משיחות חודש ניסן תשל\"ג)",[["105","105","רמב\"ם סוף הל' מלכים. וראה לקמן ע' 246 ואילך."],["106","106","פיה\"מ בהקדמתו לפ' חלק: הוא יסוד מיסודי משה רבינו ע\"ה. ובתרגום קאפח: מיסודות תורת משה רבינו. וראה לעיל הערה 61 המשך לשונו."],["107","107","מיכה ז, טו. וראה זח\"א השמטות סכ\"ה. אוה\"ת להצ\"צ (נ\"ך כרך א') ע' תפז סק\"ז-ח."]]],[1300271221,"<h3>בחוקותי ב</h3>\nא. אין די פסוקים שבפרשתנו, ביים סוף פון דער תוכחה, ווערט געזאגט<sup data-n=\"1\">1</sup>: „והתודו את עונם ואת עון אבותם גו׳ והבאתי אותם בארץ אויביהם או אז יכנע לבבם הערל ואז ירצו את עונם. ובפסוק נאכדעם<sup data-n=\"2\">2</sup>: וזכרתי את בריתי יעקב גו׳”.\nפרעגן מפרשים<sup data-n=\"3\">3</sup>: וויבאלד ס׳וועט זיין „והתודו את עונם גו׳” — תשובה, ווי קומט בהמשך לזה „והבאתי אותם בארץ אויביהם”, ד.ה. אז דאס ברענגט עונשים אויף זיי? לכאורה האט געדארפט שטיין גלייך נאך „והתודו גו׳” „וזכרתי את בריתי גו׳”.\nמפרשים ענטפערן דערויף פאר־שידענע תירוצים. מען דארף אבער פארשטיין: דאס איז דאך א שאלה לפי פשוטו של מקרא, און מען געפינט ניט אז רש״י זאל דאס באווארענען, פאר־ענטפערן די שאלה.\nלכאורה וואלט מען געקענט ענט־פערן: אויף „והתודו את עונם ואת עון אבותם” שטייט אין תורת כהנים: „לצד התשובה הם הדברים שמיד שהם מתודים על עונותיהם מיד אני חוזר ומרחם עליהם שנאמר והתודו כו׳”. און דערנאך, אויפן פסוק „והבאתי אותם בארץ אויביהם” זאגט דער תורת כהנים: „זו מדה טובה לישראל שלא יהו ישראל אומרים הואיל וגלינו לבין אומות העולם נעשה כמעשיהם, אני איני מניחם אלא\nאני מעמיד נביאיי עליהם ומחזירין אותם למוטב תחת כנפיי”.\nזיינען מפרשים<sup data-n=\"4\">4</sup> מבאר, אז דערמיט פארענטפערט דער תורת כהנים די שאלה האמורה — ווי פאסט אריין „והבאתי אותם בארץ אויביהם” נאך „והתודו גו׳”, וואס „לצד התשובה אמור”<sup data-n=\"5\">5</sup>, אז „והבאתי גו׳” איז (ניט ווי עס וואלט זיך אויסגעוויזן פון פשטות לשון הכתוב — א „קללה ופורענות”, נאר) „יעוד טוב ומדה טובה לישראל”.\nאון וויבאלד אז רש״י ברענגט דעם פירוש פון תורת כהנים אויפן פסוק „והבאתי גו׳” — „זו מדה טובה לישראל שלא יהיו אומרים כו׳ אני איני מניחם כו׳ ומחזירן לתחת כנפי” — קומט אויס, אז רש״י באווארנט דערמיט די שאלה הנ״ל.\nאבער ס׳איז א דוחק גדול צו זאגן אז דאס (צו פארענטפערן די שאלה הנ״ל) איז כוונת רש״י מיט דעם פירוש, ווייל (נוסף על זה אז לפי זה האט רש״י גע־דארפט אויך מסביר זיין די פריערדיקע ווערטער בפסוק „אף אני אלך עמם בקרי” און זאגן ווי אזוי דאס איז א „מדה טובה לישראל”<sup data-n=\"6\">6</sup>, איז) פון דעם פרש״י",[["1","1","כו, מ־מא."],["2","2","שם, מב."],["3","3","ראה רמב״ן, עקידה, אברבנאל, כלי יקר, אור החיים, ועוד."],["4","4","קרבן אהרן לתורת כהנים."],["5","5","ראה קרבן אהרן שם לפנ״ז (אות ג) על מ״ש בתו״כ „לצד התשובה כו׳” — שעד עכשיו נשלמו הקללות ומכאן ואילך הוא אומר התקנה להם להמלט מכל זה אחר שיחטאו והיא התשובה כו׳. ע״ש."],["6","6","ראה תו״כ עה״פ אף אני אלך עמם בקרי. ובקרבן אהרן שם „הם עשו את דיני עראי ולא עזבו אותם לגמרי, אף אני אעשה אותם עראי ולא אעזוב אותם לגמרי”."]]],[1300271222,"אויף „והבאתי” גופא איז מוכח להיפך: רש״י ברענגט א ראי׳ (אז „אני איני מניחם אלא מעמיד אני את נביאי ומחזירן כו׳”) פון פסוק<sup data-n=\"7\">7</sup> „והעולה על רוחכם גו׳ אם לא ביד חזקה גו׳”<sup data-n=\"8\">8</sup>, וואס דערפון איז פארשטאנדיק אז איידער עס קומט „והבאתי גו׳” איז נאך ניט געווען קיין ענין פון תשובה (און דעריבער פאר־דערט זיך א „יד חזקה”).\nנאך מער: דא גופא איז דער פסוק ממשיך „(והבאתי גו׳) או אז יכנע לבבם הערל”, ד.ה. אז ערשט „אז” — נאך „והבאתי גו׳” — וועט זיין „יכנע לבבם הערל”<sup data-n=\"9\">9</sup>, דער ענין התשובה, קען מען דאך ניט לערנען אין פשוטו של מקרא, אז „והבאתי גו׳” איז א „יעוד טוב” ושכר פאר דער פריערדיקעם „והתודו גו׳” — תשובה.\nוהדרא קושיא לדוכתא: וויבאלד אז שוין פריער איז געווען „והתודו את עונם גו׳”, פארוואס זאל דערנאך קומען „אף אני אלך עמם בקרי והבאתי אותם גו׳”? און „אז” — ערשט דערנאך — „יכנע לבבם הערל”<sup data-n=\"10\">10</sup>?\nב. וועט מען דאס פארשטיין בהקדים דעם חילוק כללי צווישן פירושי תורת כהנים און רש״י אין די פסוקים:\nאין תו״כ, סיי אויפן פסוק „והתודו גו׳” און סיי אויפן פסוק „או אז יכנע לבבם הערל”, איז ער מקדים „לצד התשובה הם הדברים”. ד.ה. אז דא רעדט זיך אז אידן האבן שוין תשובה געטאן. אבער רש״י ברענגט ניט אראפ פון תורת כהנים דעם ענין „לצד התשובה הם הדברים”.\nלאידך גיסא, אויף די ווערטער „ואז ירצו את עונם” איז רש״י מוסיף: „יכפרו על עונם ביסוריהם”. וואס דאס איז ניטא אין תו״כ; נאכן־פירוש־אין־„יכנע לבבם הערל” — „לצד התשובה הן הדברים” — פירט אויס דער תו״כ אז נאך זייער תשובה „אני חוזר ומרחם עליהן שנאמר או אז יכנע לבבם הערל ואז ירצו את עונם”.\nפון די דיוקים הנ״ל זעט מען אז לויטן תו״כ איז דא געווען תשובה<sup data-n=\"11\">11</sup>; משא״כ לויט רש״י — פשוטו של מקרא — איז קיין תשובה דא נאך ניט געווען. און דערפאר מוז רש״י צוגעבן, אז די כפרה אויף די עונות קומט „ביסוריהם”, ווייל אידן האבן ניט תשובה געטאן.\nדארף מען פארשטיין: וואס איז דער הכרח אין פשוטו של מקרא צו לערנען (ניט ווי דער תו״כ, נאר) אז אידן האבן ניט תשובה געטאן. ולכאורה, דער פסוק",[["7","7","יחזקאל כ, לב־לג."],["8","8","ואף שגם בתו״כ הביא כל המשך הפסוק ולא רק בקיצור כבפרש״י, הרי מכיון שבתו״כ הרי זה בא בהמשך להפי׳ ב„והתודו”, „לצד התשובה הם הדברים כו׳” כנ״ל, מובן, שזה בא כהוספה בענין זה (על אלו שלא התודו, או שלא היתה התשובה כדבעי. וראה בארוכה במפרשים שבהערה 3). אבל בפרש״י הרי לא נאמר לפני זה ההדגשה „לצד תשובה כו׳” כנ״ל. ולהעיר גם מהשינוי בין לשון רש״י והתו״כ: בתו״כ „ומחזירין אותם למוטב תחת כנפי”, ובפרש״י „ומחזירן לתחת כנפי” ומשמיט „למוטב”."],["9","9","והוא לב׳ הפירושים ברש״י ד״ה או אז. וראה מפרשי רש״י. ועוד."],["10","10","ומובן שע״פ פשש״מ (פרש״י) אין לפרש היפך סדר הכתובים — כמ״ש בראב״ע עה״פ אף אני גו׳ והבאתי גו׳ — „כן עשיתי להביאם אל ארץ אויביהם עד שיכנע לבבם” בעבר — כ״א ווי דער רמב״ן ברענגט פירושו וממשיך און פרעגט עס אפ „ועל דעתי ירמוז כי אחר הוידוי כו׳ יביא אותם עוד בארץ אויביהם”."],["11","11","ראה קרבן אהרן לתו״כ שם ד״ה שמיד הם מכניעים, מה שהביא מבעל אות אמת."]]],[1300271223,"זאגט דאך „והתודו גו׳ אז יכנע לבבם הערל” — טא ווי זאגט רש״י אז די כפרה אויף זייערע עונות איז (ניט ווייל זיי האבן תשובה געטאן, נאר) „ביסו־ריהם”?\nג. ויש לומר, אז רש״י לערנט עס אפ פון דעם וואס עס שטייט גלייך נאך „ואז ירצו את עונם” — „וזכרתי את בריתי יעקב גו׳”, אז דורך וזכרתי וועט קומען די גאולה (ווי רש״י איז מפרש אז אין די ווערטער „וזכרתי את בריתי יעקב” איז מרומז אז אליהו וועט קומען און מבשר זיין „גאולת בניו”).\nדלכאורה איז ניט מובן: וויבאלד אז עס האט זיך שוין אויפגעטאן דער „ירצו את עונם” — אידן האבן שוין באקומען א כפרה אויף עונם — פארוואס דארפן זיי ערשט אנקומען צו זכירת זכות אבות אויף צו זוכה זיין צו דער גאולה?\nובפרט ווי רש״י איז מאריך אויף וויפל מען דארף אנקומען צו זייער זכות — „ואם (יעקב) אינו כדאי הרי יצחק עמו ואם אינו כדאי הרי אברהם עמו”<sup data-n=\"12\">12</sup>, ד.ה. אז עס קען זיין עס זאל ניט גענוג זיין דער זכות פון איינעם פון די אבות, נאר מ׳וועט מוזן אנקומען צו דעם זכות פון אלע דריי צוזאמען — איז דאך אוודאי קשה: אויב אפילו אידן דארפן אנקומען צו זכות אבות, פארוואס זאל זיין א הוי אמינא אז זכות יעקב אליין איז ניט גענוג, בשעת אידן האבן שוין ניט קיין עונות?!\nאין אור החיים<sup data-n=\"13\">13</sup> שטייט: „הוידוי יועיל\nלהקל מעליהם הגזירות הרעות אבל להשיבם לכנם<sup data-n=\"14\">14</sup> צריך זכות אבות”.\nאבער דאס גופא פאדערט הסברה: די גאנצע — און איינציקע — סיבה אויף גלות איז — די עונות (ומפני חטאינו גלינו מארצנו), און ווי עס שטייט אין אנהויב פון דער תוכחה<sup data-n=\"15\">15</sup>: ואם לא תשמעו לי גו׳. איז דערפון פארשטאנ־דיק, אז תיכף ווי עס ווערט בטל די סיבת הגלות — „עונם”, דארף בדרך ממילא בטל ווערן דער מסובב, דער גלות, און עס קומט די גאולה.\nהיינט וויבאלד אז דא איז געווען „והתודו גו׳ ירצו את עונם” — פאר־וואס דארף מען אנקומען צו „וזכרתי גו׳” אויף זוכה זיין צו דער גאולה?\nד. דערפון איז רש״י מכריח, אז כאטש דא האט זיך אויפגעטאן דער „ירצו את עונם” — איז אבער ביי אידן גופא ניט געוואָרן א שינוי. עס איז בלויז וואס „יכפרו על עונם ביסוריהם”, אבער ניט זיי האבן זיך געביטן<sup data-n=\"16\">16</sup>.\nאון דערפאר זאגט רש״י אויף „יכנע לבבם הערל” (ניט ווי אין תו״כ אז דאס איז אן ענין פון תשובה, נאר) אז דאס איז א המשך צו „והבאתי גו׳”, וואס רש״י איז מפרש (כנ״ל) אז דאס איז א הנהגה",[["12","12","ומקורו בתו״כ. אבל בתו״כ: א) נאמר בסדר הפכי, ב) לא נאמר „עמו”. ונתבארו השינויים בלקו״ש חלק ל״ב ע׳ 168 ואילך."],["13","13","כו, מב."],["14","14","מל׳ כיור וכנו — היינו למקומם (בא״י)."],["15","15","כו, יד."],["16","16","ואולי יש לומר שזהו דיוק לשון רש״י „יכפרו על עונם ביסוריהם”, דלכאורה הקב״ה מכפר על עונם ע״י יסורים והול״ל „יתכפר עונם ביסורים” וכלשון הכתוב „ופקדתי בשבט פשעם ובנגעים עונם” (תהלים פט, לג). אלא שכפרה זו של יסורים ע״י הקב״ה היא לאחרי התשובה, כשתשובתו רצוי לפניו ית׳, כמו שהאריך אדה״ז באגה״ת פ״א. אבל בנדו״ד, מכיון שאין זה יסורים שלאחרי התשובה כנ״ל, נמצא שזהו כאילו „יכפרו . . ביסוריהם”."]]],[1300271224,"מלמעלה אין אן אופן פון „ביד חזקה אמלוך עליכם”, מצד דער „יד חזקה” ווערט „יכנע לבבם הערל”: די יסורים כו׳ ברעכן די הארץ. אבער דאס איז ניט אן ענין פון תשובה.\nאון דערפאר מוז מען אנקומען צו זכירת ברית אבות: כדי צו זוכה זיין צו גאולה איז (ניט גענוג צו אראפנעמען די עוונות ביסוריהם, נאר) אידן מוזן נשתנה ווערן. גלות און גאולה זיינען צוויי פארקערטע מצבים, ובלשון הפסוק: אין זמן הגלות איז א הנהגה פון „אלך עמכם בקרי”<sup data-n=\"17\">17</sup>, משא״כ בזמן הגאולה איז „ופניתי אליכם”, „ונתתי משכני בתוככם . . . והתהלכתי בתוככם”<sup data-n=\"18\">18</sup> — גילוי און הארת פנים פון דעם אויבערשטן.\nדעריבער איז ניט גענוג צו אפווישן די עונות, נאר עס מוז זיין א שינוי אין אידן, זיי זאלן זיין גרייט צו דעם מצב הפכי פון גאולה. און וויבאלד אז דא איז בלויז געווען „יכפרו על עונם ביסו־ריהם” — ווי וועלן אידן קומען צו דער גאולה? איז דער פסוק ממשיך ומבאר „וזכרתי את בריתי יעקב גו׳” — דאס וועט קומען מצד דעם ברית וואס דער אויבערשטער האט כורת געווען מיט די אבות. היות און עס איז דא א כריתת ברית מיט די אבות, איז דער אוי־בערשטער מקיים זיין הבטחה מיט זייערע קינדער, ניט קוקנדיק אויף זייער מעמד ומצב (מצד עצמם).\nה. ע״פ כל הנ״ל איז אויך פארענט־פערט פארוואס רש״י דארף ניט באווארענען ווי אזוי פאסט דער „אף אני\nאלך גו׳ והבאתי אותם גו׳” נאכן „והתודו את עונם גו׳”:\nכשם ווי „יכנע לבבם הערל” איז ניט קיין ענין פון תשובה (לויט פרש״י) כנ״ל, נאר א תוצאה פון דער „יד חזקה” מיט וועלכער דער אויבערשטער איז מולך אויף אידן „בארץ אויביהם”, עד״ז איז בנוגע „והתודו את עונם ואת עון אבותם”, אז דאס איז ניט קיין ענין פון וידוי וואס קומט צוזאמען מיט תשובה, נאר דאס איז א המשך צום פריערדיקן פסוק: בשעת עס וועט זיין א מצב פון „ימקו בעונם גו׳ ואף בעונות אבותם”<sup data-n=\"19\">19</sup>, וועט עס ברענגען אז אידן וועלן זיך מתודה זיין אויף „עונם ואת עון אבותם”. ד.ה. דער וידוי איז ניט קיין אויסדרוק פון זייער רצון צו תשובה, נאר אזוי ווי זיי פילן „יסוריהם” די ליידן פון עונם און עון אבות, זיינען זיי מודה אז עונם איז ניט געווען כדאי, אבער ניט אז עס איז געווען א זינד (א שרץ).\n[וע״ד ווי דער כלי יקר<sup data-n=\"20\">20</sup> איז מבאר, אז אויך נאכן וידוי בלייבן זיי „במעלם אשר מעלו בי”, איז דער וידוי „כטובל ושרץ בידו”].\nו. דאס איז אבער נאך ניט גלאטיק:\nווי דערמאנט פריער, איז רש״י מפרש דעם פסוק „והבאתי אותם” אז „זו מדה טובה לישראל”, און פון דעם וואס דאס קומט גלייך בהמשך צו „והתודו את עונם גו׳” איז מובן, אז די „מדה טובה לישראל” קומט אלס תוצאה פון „והתודו”.\nאיז ניט מובן: אויב מ׳זאל זאגן אז דער וידוי איז א תוצאה פון די יסורי הגלות",[["17","17","כו, מא. וראה גם לפני זה כו, כד. כח."],["18","18","כו, ט ואילך."],["19","19","כו, לט."],["20","20","ובארוכה עקידה ואברבנאל שם. ועוד."]]],[1300271225,"אבער ס׳איז ניטא דערביי קיין תשובה — ווי דער כלי יקר זאגט „כטובל ושרץ בידו” — פארוואס זאל דאס ברענגען צו „והבאתי אותם . . זו מדה טובה לישראל”?\nמוז מען זאגן, אז אע״פ וואס דער וידוי איז ניט קיין ענין פון תשובה, איז עס אבער עכ״פ אן ענין טוב וואס איז גורם אז דער אויבערשטער זאל זיך פירן מיט אידן אין אן אופן פון מדה טובה, „מחזירן לתחת כנפי”.\nז. וועט מען דאס פארשטיין בהקדים הביאור אין ענין הוידוי ע״ד ההלכה — וואס מען געפינט כמה פרטים אין גדר הוידוי:\nאין אנהויב הל׳ תשובה<sup data-n=\"21\">21</sup> פסק׳נט דער רמב״ם „כשיעשה תשובה וישוב מחטאו חייב להתודות”, דער וידוי קומט דוקא נאך דעם ווי דער מענטש האט שוין תשובה געטאן. און ווי דער רמב״ם איז מבאר אין דעם פרק שלאח״ז<sup data-n=\"22\">22</sup>, אז די זאך פון וידוי איז, וואס ער זאגט ארויס בשפתיו „עניינות אלו שגמר בלבו”. ד.ה. פריער דארף זיין תשובה וואס ענינה איז „ויגמור בלבו שלא יעשהו עוד . . יתנחם על שעבר כו׳”<sup data-n=\"23\">23</sup>, און נאכדעם ווערן אט די החלטות שבלב („עניינות אלו שגמר בלבו”) ארויסגעבראכט בדיבור דורך וידוי.\nאין חינוך<sup data-n=\"24\">24</sup>, אין דעם ביאור „שרשי המצוה” פון וידוי, גיט ער צו א צווייטן ענין אין וידוי: „גם מתוך הזכרת החטא בפרט יתנחם עליו ויזהר ממנו יותר פעם אחרת” — ד.ה. דער וידוי העלפט אויף דער ווייטערדיקער תשובה.\nויש לומר, אז מצד דעם ענין אין וידוי, איז דא אן ארט אויף ענין הוידוי נאך איידער מ׳טוט תשובה שלימה בלבו, ווייל דער וידוי גופא וועט אים ברענגען צו „יתנחם עליו”. וע״ד ווי דער רמב״ם איז מבאר אין הל׳ תעניות<sup data-n=\"25\">25</sup> דעם תוכן ומטרה פון די ארבעה צומות, וז״ל: „יש שם ימים שכל ישראל מתענים בהם מפני הצרות שאירעו בהן כדי לעורר הלבבות לפתוח דרכי התשובה ויהי׳ זה זכרון למעשינו הרעים ומעשה אבותינו שהי׳ כמעשינו עתה עד שגרם להם ולנו אותן הצרות, שבזכרון דברים אלו נשוב להיטיב שנאמר והתודו את עונם ואת עון אבותם וגו׳”. ד.ה. אז דער „זכרון דברים אלו” גופא — דאס דערמאנען זיך אויף דעם וואס „מעשינו הרעים ומעשה אבותינו” האבן גורם געווען „אותן הצרות” — וועט ברענגען צו „נשוב להיטיב”.\nועד״ז איז דא אן אופן אין וידוי וואס קומט נאך איידער מען טוט תשובה, וואס די מטרה פון דעם וידוי איז, אז דורך דעם זאל זיין „נשוב להיטיב”.\nח. עס איז אבער פאראן נאך אן אופן אין וידוי (לפני תשובה), וואס דאס איז — ווי דער רמב״ם זאגט אין הל׳ תשובה<sup data-n=\"26\">26</sup> — „המתודה בדברים ולא גמר",[["21","21","שכל הלכות תשובה ברמב״ם נלמדות (לפי החלוקה דג׳ פרקים ליום) במשך שבוע זה דפ׳ בחוקותי (תשד״מ): יום ג׳ — פרק א׳־ג׳; וכן הלאה. ועד״ז סהמ״צ דלקמן בפנים סעיף י״ב להלומדים סהמ״צ. ולהעיר שבשבוע זה (תשד״מ) ביום ד׳ חל פסח שני שענינו ענין התשובה — ראה היום יום ע׳ נג. לקו״ש חי״ח שיחה ג׳ ושיחה ד׳ לפ׳ בהעלותך. ועוד."],["22","22","פ״ב ה״ב."],["23","23","לשון הרמב״ם שם."],["24","24","מצוה שסד."],["25","25","רפ״ה."],["26","26","פ״ב ה״ג."]]],[1300271226,"בלבו לעזוב” און אזא וידוי פארגלייכט דער רמב״ם צו „טובל ושרץ בידו”.\nבהשקפה ראשונה זעט אויס, אז אזא וידוי איז כלל ניט אין גדר וידוי. ווארום היות אז די זאך פון וידוי איז (ווי דער רמב״ם זאגט גלייך פאר דעם, בסיום הלכה שלפנ״ז) „להתודות בשפתיו ולומר עניינות אלו שגמר בלבו”, דארף במילא אויסקומען אז אויב ס׳איז ניטא דער „גמר בלבו” איז אויך ניטא דער גאנצער גדר הוידוי.\nאבער לפי זה איז ניט פארשטאנדיק וואס דער רמב״ם גיט דערויף די דוגמא פון „טובל ושרץ בידו”: אויב ס׳איז ניטא די גאנצע זאך פון וידוי, איז דאס בדומה ניט צו אזא וואס איז „טובל (נאר דאס איז באופן פון) ושרץ בידו”, נאר צו אזא וואס האט איבערהויפט ניט26*) געהאט קיין טבילה<sup data-n=\"27\">27</sup>!\nדערפון זעט מען, אז דער עצם ענין הוידוי — זאגן בדיבור אז מ׳איז באגאנ־גען א חטא — אפילו ווען ס׳איז נאך ניטא די החלטה בלב אפצולאזן דעם חטא, איז דאס אליין אן ענין טוב — ס׳איז בדוגמא צום ענין הטבילה, וואס איז א פעולה וואס האט דעם כח אויפצוטאן טהרה; דער חסרון איז נאר, וואס\nבשעת „לא גמר בלבו לעזוב” איז דער וידוי באופן פון „ושרץ בידו” (בלבו האט ער א פארבונד מיטן חטא, ער האלט זיך נאך אין דער „טומאה”), דערפאר קען ער ניט ווערן טהור „עד שישליך השרץ”, עד שיגמור בלבו כו׳.\nט. די הסברה בזה:\nדער ענין הדיבור האט אין זיך כמה תכונות:\nא) דיבור ברענגט ארויס, איז מגלה די ענינים וועלכע געפינען זיך אינעווייניק בתוך לבו ומחשבתו של האדם.\nב) דיבור האט די אייגנשאפט צו ארויסרופן (א תוספת) התעוררות אינעם נושא ותוכן המדובר (ע״ד ווי עס שטייט אין ספרים<sup data-n=\"28\">28</sup>, אז בשעת איינער איז בכעס זאל ער ניט ריידן בעת ההיא, ווייל דורך דיבור ווערט נאך מער פארשטארקט דער כעס).\nג) בשעת איינער רעדט ארויס בדיבור א זאך וואס איז פארקערט פון דעם וואס ער פילט אין פנימה, דערפילט ער בשעת מעשה א רגש פון א מנוחה ביז א רגש פון בושה. ווייל כאטש דאס רעדן איז בלויז אן ענין חיצוני, וויבאלד אבער אז א מענטש איז במהותו א „מדבר” (כמבואר בכס״מ<sup data-n=\"29\">29</sup>, איז דעריבער בהכרח אז א זאך וואס ער ברענגט ארויס אין דיבור זאל אים אנרירן און דערפאר מאכט עס אים „ענג” ווען ער זאגט עפעס אזוינס וואס איז בסתירה צו דעם וואס ער איז מרגיש בלבו.",[["","","26*) וראה חינוך (מצוה שסד) „מוטב שלא יתודה על זה” (אלא ששם קאי במי שעדיין לא השיב „החמס אשר בכפיו”). מדבר קדמות מע׳ ו׳ אות י׳ (בשם הזהר)."],["27","27","להעיר מהשינוי בלשון הרמב״ם מלשון הגמרא (תענית טז, א שהובא בכס״מ), שבגמרא: למה הוא דומה לאדם שתופס שרץ בידו שאפי׳ (ובכס״מ: שאע״פ) טובל בכל מימות שבעולם לא עלתה לו טבילה, ובלשון הרמב״ם „הרי זה דומה לטובל ושרץ בידו” מודגש יותר שהוידוי הוא דוגמת הטבילה."],["28","28","ראה ספר המאמרים תרנ״ט ע׳ ה (בשם ר״ח)."],["29","29","ראה לקו״ש ח״י ס״ע 115 ואילך ובהנסמן שם. ולהעיר מלקו״ש חכ״ב ע׳ 67 בנוגע לגדר דלשון הרע."]]],[1300271227,"יו״ד. עד״ז זיינען פאראן די דריי ענינים אין ענין הוידוי (בדיבור<sup data-n=\"30\">30</sup>:\nדער עיקר חיוב פון וידוי איז, כנ״ל ברמב״ם: „להתודות בשפתיו ולומר עניינות אלו שגמר בלבו” — דער דיבור זאל ארויסברענגען בגלוי די תשובה שבלב. און ווי דער חינוך<sup data-n=\"31\">31</sup> איז דאס מבאר מער בארוכה: „לפי שבהודאת העון בפה תתגלה מחשבת החוטא ודעתו שהוא מאמין באמת כי גלוי וידוע לפני הא־ל ב״ה כל מעשהו כו׳”.\nא צווייטער ענין אין וידוי איז, וואס דער וידוי גופא<sup data-n=\"32\">32</sup>, אפילו נאך איידער ער מאכט די החלטה גמורה בלבו אפצו־לאזן דעם חטא, דערוועקט ביי אים דעם רגש התשובה, וכנ״ל, אז דיבור איז מעורר דעם רגש הלב<sup data-n=\"33\">33</sup>.\nא דריטער ענין אין וידוי איז, אז דער וידוי גופא איז א „מעשה” של תשובה<sup data-n=\"34\">34</sup>: זאגנדיק בדיבור „אנא השם חטאתי עויתי פשעתי לפניך ועשיתי כך וכך והרי נחמתי ובושתי במעשי ולעולם איני חוזר לדבר הזה”<sup data-n=\"35\">35</sup> (וכיו״ב), אפילו אז דעמאלט איז נאך „לא גמר בלבו לעזוב”, איז עס אבער דאך פועל בשעת מעשה אין מענטשן, ער דערפילט א רגש פון בושה על העבר, (אויך אויף דעם וואס זיין דיבור איז ניט בהתאם מיט זיין רגש שבלב). דעריבער ווערט דער וידוי פאררעכנט ווי א מעשה פון טבילה<sup data-n=\"36\">36</sup> (וואס איז — בכלל — מטהר פון טומאה).\nיא. ע״פ כל הנ״ל איז פארשטאנדיק אויך וואס לויט רש״י איז דער „והתודו” ניט קיין ענין פון תשובה (און די כפרה אויף עונות איז „ביסוריהם”) — און ווי דער כלי יקר זאגט (כנ״ל) אז דער וידוי איז „כטובל ושרץ בידו” — אעפ״כ, האט עס אין זיך א תועלת, וואס דערפאר ברענגט דאס צום „והבאתי גו׳”, „זו מדה טובה לישראל כו׳ ומחזירן לתחת כנפי”.",[["30","30","להעיר על השינויים ברמב״ם: בריש הל׳ תשובה „חייב להתודות . . זה וידוי דברים . . וכן בעלי חטאות כו׳ עד שיעשו תשובה ויתודו וידוי דברים . . מחוייבי מיתות . . עד שיעשו תשובה ויתודו. וכן החובל כו׳ עד שיתודה וישוב כו׳”. רפ״ב ה״ב: „וצריך להתודות בשפתיו כו׳”, בה״ג „כל המתודה בדברים”, וברפ״ז „ולהתודות בפיו מחטאיו כו׳”. וראה מנ״ח ריש מצוה שסד. ואכ״מ."],["31","31","מצוה שסד. וראה חובת הלבבות שער הבחינה פ״ה."],["32","32","להעיר מחידושי בית יעקב על הרמב״ם (מהר״י בי רב, נדפס ברמב״ם הוצאת פרדס) הל׳ תשובה פ״ב ה״א. ספר יד הקטנה הל׳ תשובה פ״א ה״ב סק״ד. מהר״ם שיק על תרי״ג מצות מצוה שסה."],["33","33","ע״ד מחז״ל קול מעורר הכוונה (ראה טושו״ע (ואדה״ז) או״ח סס״א ס״ד (ס״ה). ב״י לטאו״ח סק״א. ט״ז שם סק״א־ג. שו״ע אדה״ז שם ס״ג. ר״ח שער הקדושה ספט״ו — הובא בשל״ה שער האותיות (פב, ב). וראה אוה״ת וארא ע׳ קעו ואילך. סה״מ תרנ״ט ע׳ ו). *) ומתרץ עפ״ז ל׳ הרמב״ם „טובל ושרץ בידו”, שנחשב כטבילה (כדלקמן בפנים). ומאריכות דבריו משמע שקאי גם במי שאין בלבו שום חרטה כו׳ (ע״ש), ע״ד אופן הג׳ שבפנים."],["34","34","להעיר מדרך מצותיך מצות וידוי תשובה פ״א: ע״י החרטה שהיא עקירת הרצון מן החטא בזה מוציא הנפש מן הקליפה כו׳ אך כדי למחות גופה הוא ע״י וידוי דברים דעקימת שפתיו הוי מעשה ובזה הוא ממחה גופה והי׳ כלא הי׳."],["35","35","לשון הרמב״ם בריש הל׳ תשובה „כיצד מתודין אומר” ומסיים „וזהו עיקרו של וידוי”."],["36","36","עפ״ז יומתק לשון המאירי (חבור התשובה מ״א פ״ט (ע׳ 191)) שלאחרי שמביא דברי הרמב״ם הנ״ל כתב: ומה מאוד נאות המשל לפי הנמשל כי הטבילה במים הוא דמיון על התשובה, ותפיסת השרץ הוא דמיון על היות מחשבתו לשוב לחטאו, וכשם שהטובל ושרץ בידו לא תועיל לו הטבילה גם בעת היותו במים כן התשובה בלתי גמר המחשבה בעזיבת החטא לא תועיל גם בעת התשובה כו׳."]]],[1300271228,"ווייל דער עצם ענין הוידוי, אפילו אן א רגש של תשובה בלב, איז בדוגמת ענין הטבילה. און דעריבער<sup data-n=\"37\">37</sup>, אלס תוצאה דערפון, פירט זיך דער אוי־בערשטער מיט אידן אין אן אופן פון מדת טובה, איז „מחזירן לתחת כנפי”.\nיב. ע״פ המבואר לעיל — אז אין וידוי זיינען דא כמה דרגות און אז דער עיקר חיוב פון וידוי איז דער ערשטער ענין שבו, „להתודות בשפתיו ולומר עניינות אלו שגמר בלבו” (און ניט (אזוי) די אנדערע ענינים אין וידוי וואס קומען ניט צוזאמען מיט תשובה בלב) — קען מען אויך מסביר זיין אן ענין תמוה אין ספר המצות להרמב״ם:\nאין מצות וידוי ברענגט דער רמב״ם<sup data-n=\"38\">38</sup> פון מכילתא<sup data-n=\"39\">39</sup>: יכול בזמן שהם מביאים (קרבן) הם מתודין ובזמן שאין מביאין אין מתודין, תלמוד לומר39*) דבר אל בני ישראל והתודו, ועדיין אין משמע וידוי אלא בארץ מנין אף בגלות, תלמוד לומר והתודו את עונם ואת עון אבותם.\nאיז ניט מובן: בשלמא דאס וואס עס איז פאראן א קס״ד אז וידוי איז נאר ווען מען ברענגט א קרבן איז מובן, ווי דער רמב״ם איז דארט מבאר לפנ״ז: „ובעבור שבא זה הציווי שהוא והתודו עם חיוב הקרבן הי׳ עולה במחשבה שאין הוידוי לבדו מצוה בפני עצמו אבל הוא\nמדברים הנגררים אחר הקרבן, הוצרכו שבארו זו במכילתא”<sup data-n=\"40\">40</sup>.\nאבער ס׳איז ניט פארשטאנדיק: ווי אזוי וועט זיין א קס״ד אז וידוי איז נאר אין א״י ביז אז מ׳דארף האבן א לימוד מיוחד אז עס איז דא וידוי אויך אין גלות?\nדער חינוך<sup data-n=\"41\">41</sup> איז דאס מבאר: ועדיין הייתי אומר שאין הוידוי אלא בארץ, כלומר אע״פ שמתודין בלא קרבן מ״מ לא יהי׳ חייב וידוי אלא בארץ, כי שם עיקר הכפרה ושם הקרבנות ועיקר הכל בה.\nאבער דער ביאור פאדערט הסברה: מצות תשובה און מצות וידוי זיינען דאך א חובת הגוף בכל הזמנים — וואס איז דא די נפק״מ וואס אין א״י איז „עיקר הכפרה ושם הקרבנות”?\nוע״פ הנ״ל קען מען דאס מסביר זיין: וויבאלד אז דער גדר פון חיוב וידוי איז דער ביטוי וגילוי דערפון וואס „גמר בלבו”, וואלט געווען א קס״ד, אז אין גלות, וואו עס קען זיין אז דער וידוי איז ניט אינגאנצן מצד התשובה שבלב האדם, נאר אין דעם איז אריינגעמישט דער צער פון יסורי הגלות, ד.ה. אז וואס איז גורם זיין וידוי — דער גלות, יסורי הגלות, קומט במילא אויס אז דאס איז ניט דער ענין פון וידוי אלס ביטוי פון דער תשובה שבלב, נאר ע״ד אופן הב׳ והג׳ הנ״ל, קען מען דעריבער מיינען אז אזא אופן פון וידוי איז ניט קיין חיוב.",[["37","37","וי״ל שהנהגה זו ד„והתודו” בלי רגש ותנועה של תשובה ה״ז הנהגה ד„אשר הלכו עמי בקרי”, ולכן „אף אני אלך עמם בקרי והבאתי אותם בארץ אויביהם”, שמעוררים ע״י „ביד חזקה”, ולא ע״י גילוי וקירוב."],["38","38","סהמ״צ מ״ע עג."],["39","39","כ״ה ברמב״ם, והוא מספרי זוטא נשא ה, ז. 39*) נשא שם, ו־ז."],["40","40","כ״ה בסהמ״צ שלפנינו. ובהוצאת העליר וקאפח בשינויים קצת."],["41","41","מצוה שסד."]]],[1300271229,"לערנט מען פון פסוק „והתודו את עונם ואת עון אבותם” אז אויך דער וידוי פון גלות (אע״פ וואס דערביי איז ניטא דער „גמר בלבו” מיט דער שלימות, וויבאלד אז די תשובה קומט בעיקר מצד די יסורי הגלות), אעפ״כ איז אויך אויף אזא וידוי דא א חיוב (צוזא־מען מיט תשובה).\nיג. עפ״ז — אז כללות ענין התשובה אין גלות (וואס קומט מצד די יסורי הגלות) איז ניט דער ענין פון תשובה בשלימותו — וועט מען אויך האבן א הסברה וואס דארף אנקומען צו „וזכרתי גו׳” אויך לויט די מפרשים אז „והתודו גו׳ או יכנע לבבם הערל” איז יע אן ענין פון תשובה:\nוויבאלד אז די תשובה הויבט זיך אן, נאר מצד יסורי הגלות, איז דאס ניט קיין אמת׳ער שינוי אין דער מציאות פון אידן. דארף מען דעריבער אנקומען צו זכות אבות אויף זוכה זיין צו דעם מעמד ומצב פון גאולה.\nועפ״ז יומתק דער חידוש פון דער גאולה העתידה לבא — ווי דער רמב״ם פסק׳נט<sup data-n=\"42\">42</sup> להלכה אז אין ישראל נגאלין אלא בתשובה און דערנאך ממשיך „הבטיחה תורה שסוף ישראל לעשות תשובה בסוף גלותן ומיד הן נגאלין” — שיש לומר כוונת הרמב״ם בזה, אז תורה איז מבטיח אז אידן וועלן דערגרייכן צו תשובה מצד זייער מציאות. ד.ה. אע״פ אז פריער וועט זיין (ווי עס שטייט אין פסוק<sup data-n=\"43\">43</sup> וועלכן דער רמב״ם ברענגט דארט43*)) „יבואו עליך כל הדברים גו׳”,\nוועט אבער דערנאך זיין „ושבת עד ה״א”<sup data-n=\"44\">44</sup>: די תשובה וועט זיך מתייחס זיין צו די אידן.\n[ויש לומר, אז דער רמב״ם איז דאס מדגיש דערמיט דעם ענין וועגן דער תשובה בסוף הגלות אין פרק שביעי פון הלכות תשובה, נאך דעם ווי ער איז מאריך אין צוויי פרקים<sup data-n=\"45\">45</sup> וועגן דעם ענין פון בחירה חפשית, אז יעדער איד האט בחירה חפשית, און זאגט דערנאך אין אנהויב פון פרק שביעי: „הואיל ורשות כל אדם נתונה לו כו׳ ישתדל אדם לעשות תשובה ולהתודות כו׳” — וואס יש לומר כוונת הרמב״ם בזה45*):\nדי אמיתית ענין תשובה איז בשעת זי קומט בבחירתו החפשית, ובמילא דארף דער מענטש זיך משתדל זיין צו טאן תשובה מצד בחירתו החפשית און ניט<sup data-n=\"46\">46</sup> ווארטן ביז מען וועט אים מכריח זיין צו טאן תשובה מלמעלה: און בהמשך לענין זה זאגט דער רמב״ם „הבטיחה תורה שסוף ישראל לעשות תשובה בסוף גלותן”<sup data-n=\"47\">47</sup> — אז אידן וועלן טאן אט די תשובה — א תשובה וואס קומט מצד בחירה חפשית של האדם].",[["42","42","הל׳ תשובה פ״ז ה״ה."],["43","43","נצבים ל, א. 43*) וי״ל שזה שהרמב״ם מביא תחילת הכתוב „והי׳ כי יבואו עליך כל הדברים גו׳”, הוא רק להביא ראי׳ שהכתוב מדבר בזמן ד„סוף גלותן”."],["44","44","שם, ב."],["45","45","פ״ה ופ״ו. 45*) וראה בארוכה לקו״ש חלק ל׳ ע׳ 199 ואילך."],["46","46","ו„לא מיראה ולא מכשלון כח” (ראה רמב״ם שם רפ״ב)."],["47","47","וי״ל שזהו גם מה שמתחיל הרמב״ם בהלכה ה „כל הנביאים כולן צוו על התשובה ואין ישראל נגאלין אלא בתשובה”, דאין ישראל נגאלין אלא בתשובה זו — „צוו על התשובה”, שעשיית התשובה היא רק מצד הציווי ועושה זה מצד בחירתו, בדוגמת כללות ענין המצות והעבירות שהאדם עושה מצד בחירתו, כמו שביאר בפ״ה. עיי״ש."]]],[1300271230,"און דאס איז דער חילוק צווישן דעם ענין ווי ער שטייט אין אונזער סדרה לגבי ווי ער שטייט אין דעם פסוק „ושבת גו׳” הנ״ל: בפרשתנו איז דער לשון הפסוק „או אז יכנע לבבם הערל” — דא איז ניט מודגש די פעולה פון אידן (מילת ערלת הלב), נאר אז דער לב איז א נפעל, וועט נכנע ווערן מצד די יסורי הגלות.\nמשא״כ אין דער גאולה האמיתית והשלימה ע״י משיח צדקנו וועט זיין „ושבת עד ה״א”, די תשובה פון אידן\nבכח עצמם. די יסורי הגלות וועלן בלויז זיין ווי א מעורר, אבער דערנאך קומט די תשובה מצד די אידן גופא<sup data-n=\"48\">48</sup>.\n(משיחות ש״פ בהו״ב תשכ״ח, ויק״פ תשל״ה)",[["48","48","וי״ל (ע״ד הרמז עכ״פ) שזהו דיוק הלשון „ומיד הן נגאלין”, שאין צריך עוד דבר אפילו לא זכירת ברית אבות (כבפרשתנו) כדי שיהיו נגאלין, אלא „מיד” — רק מצד התשובה."]]],[1300271231,"<h3>בחוקותי ג *</h3>\nא. ביים סיום פון הלכות ערכין וחרמים1 אין ספר „היד\" שרייבט דער רמב\"ם: לעולם לא יקדיש אדם ולא יחרים כל נכסיו, והעושה כן עובר על דעת הכתוב, שהרי הוא אומר2 מכל אשר לו, ולא כל אשר לו, כמו שבארו חכמים3. ואין זו חסידות אלא שטות4, שהרי הוא מאבד כל ממונו ויצטרך לבריות. ואין מרחמין עליו. ובזה וכיוצא בו אמרו חכמים5 חסיד שוטה מכלל מבלי עולם. אלא כל המפזר ממונו במצות אל יפזר יותר מחומש6. ויהי' כמו שצוו7 נביאים8 מכלכל דבריו במשפט, בין בדברי תורה בין בדברי עולם. אפילו בקרבנות שאדם חייב בהן הרי חסה תורה על הממון ואמרה9 שיביא כפי מסת ידו, קל וחומר לדברים שלא נתחייב בהן אלא מחמת נדרו שלא ינדור אלא כראוי לו, שנאמר10 איש כמתנת ידו כברכת ה' אלקיך אשר נתן לך.\nפון כללות דברי הרמב\"ם „אלא כל המפזר ממונו במצות אל יפזר יותר מחומש\" איז לכאורה משמע, אז אויך אין עניני צדקה (מצות הצדקה) דארף א איד געבן ניט מער ווי א חומש פון זיינע נכסים, און אודאי ניט כל נכסיו.\nגעפינען מיר אבער, אז דער אלטער רבי איז מאריך אינעם ענין פון געבן צדקה מער פון חומש מנכסיו און אפילו אוועקגעבן אויף צדקה אלץ וואס ער האט — ווי דער אלטער רבי שרייבט אין אגרת התשובה11 בנוגע פודה זיין א תענית מיט געבן געלט אויף צדקה „ואף שיעלה לסך מסויים12 אין לחוש משום אל יבזבז יותר מחומש, דלא מקרי בזבוז בכה\"ג מאחר שעושה לפדות נפשו מתעניות וסיגופים, ולא גרעא מרפואת הגוף ושאר צרכיו\".\nאון אזוי איז דער אלטער רבי מבאר אויך אין אגה\"ק13, אז א איד דארף „מפזר\" זיין געלט אויף צדקה אן א גבול בכדי דערמיט צו מתקן זיין (דעם קלקול ופגם דורך) די עבירות וואס ער האט געטאן; און דער אלטער רבי בא־וארנט: ומ\"ש המבזבז אל יבזבז יותר מחומש, היינו דוקא במי שלא חטא או שתקן חטאיו . . אבל מי שצריך לתקן נפשו עדיין, פשיטא דלא גרעה רפואת הנפש מרפואת הגוף, שאין כסף נחשב14,",[["","","*) וסיום ספר הפלאה ברמב\"ם."],["1","1","פ\"ח הי\"ג."],["2","2","פרשתנו כז, כח."],["3","3","ערכין כח, א."],["4","4","ראה לקמן סעיף ו והערה 47."],["5","5","סוטה כ, א. ולשיטתי' בפירוש המשניות שם (שאינו כבש\"ס (בבלי שם כא, ב. ובירושלמי — הובא בתוס' שם)). ולהעיר משינוי הפירוש במבלי עולם — ושיטת הרמב\"ם — קו\"א לאדה\"ז הל' ת\"ת פ\"ב ס\"א."],["6","6","כתובות נ, רע\"א. שם סז, סע\"ב. ערכין שם. וראה ירושלמי פאה פ\"א ה\"א."],["7","7","תהלים קיב, ה (ושם: יכלכל) — ובא בהמשך למ\"ש לפנ\"ז „טוב איש חונן ומלוה\"."],["8","8","וצע\"ק שקורא ל(תהלים —) כתובים נביאים. וראה (מגילה יד, א — בפרש\"י ד\"ה נבואה. סוטה מח, ריש ע\"ב) דדוד נביא הי' (וראה לקו\"ש חי\"ח ע' 275 הערה 31. וש\"נ)."],["9","9","ע\"פ הכתוב — ראה טז, יו\"ד."],["10","10","סוף פרשת ראה."],["11","11","פ\"ג (צג, א. ומציין (שם ריש ע\"ב) לאגה\"ק דלקמן)."],["12","12","ע\"ד הל' דבר מסויים (ירוש' שקלים פ\"א ה\"ד. ועוד)."],["13","13","סוס\"י (קטו, סע\"ב ואילך)."],["14","14","ע\"פ לשון הכתוב — דה\"ב ט, כ. ועד\"ז במ\"א י, כא."]]],[1300271232,"וכל אשר לאיש יתן בעד נפשו כתיב15.\nאון דאס שרייבט דער אלטער רבי אלס אן ענין וואס איז נוגע הלכה למעשה — און ער פירט אויס (דארט אין אגה\"ת) „נהגו עכשיו כל החרדים לדבר ה' להרבות מאד מאד בצדקה\"; און אזוי איז ער אויך מסיים (אין אגה\"ק) אז ער קען מפזר זיין אויף צדקה „בלי גבול16 לתקן עוונותיו כו' צריכין אנו להתנהג כו' בלי גבול\".\nב. וועט עס זיין מובן בהקדם א סתירה אין די רייד פון רמב\"ם גופא:\nאין זיין פירוש אויף דער משנה17 „אלו דברים שאין להם שיעור . . גמילות חסדים\" זאגט דער רמב\"ם18: „מה שאמר בכאן גמ\"ח אין לה שיעור, רוצה לומר לעזור אדם בגופו19, אך שיעזור אותו בממונו — יש לו שיעור, והוא חמישית ממונו, ולא יתחייב לתת יותר מחמישית ממונו, לבד אם עשה כן במדת חסידות\". זאגט דאך דער רמב\"ם אז מצד מדת חסידות האט אן ארט צו געבן צדקה וגמ\"ח מער ווי א חומש פון זיין ממון — און אין דער הלכה הנ\"ל אין ספר „היד\" שרייבט ער, אז דאס מפזר זיין מער פון א חומש „אין זו חסידות אלא שטות\"!\nאויך דארף מען פארשטיין:\nאין דער משנה אין ערכין שטייט20: מחרים אדם מצאנו ומבקרו כו' ואם החרים את כולם אינם מוחרמים, דברי ר\"א. א\"ר אלעזר בן עזרי' מה אם לגבוה אין אדם רשאי להחרים כל נכסיו, עאכו\"כ שיהא אדם חס על נכסיו.\nפרעגט דארט די גמרא אויף דער משנה: „א\"ר אלעזר בן עזרי' . . היינו ת\"ק\" און די גמרא ענטפערט: „איכא בינייהו דרבי אילא דאמר רבי אילא באושא התקינו המבזבז אל יבזבז יותר מחומש\". איז דארט רש\"י מסביר בפי־רושו21: ר' אלעזר בן עזרי' אית לי' דרבי אילא, דהא אתא לאשמועינן שיהא אדם חס על נכסיו, ר\"א לית לי' דרבי אילא, דאי בזבז טובא לא איכפת לן, אלא ששייר לעצמו קצת, דומיא דחרם.\nד.ה. אז דער ת\"ק האלט ניט ווי ר' אילא אז ס'איז פאראן א שיעור פון חומש, און אז אדם קען מחרים זיין מער פון א חומש בנכסיו; און שיטת ר\"א בן עזרי' איז אזוי ווי ר' אילא, אז ער זאל ניט מחרים זיין מער פון א חומש.\nולפי זה, וויבאלד אז אין פירוש המשניות נעמט אן דער רמב\"ם דעת ר' אילא, אז ס'איז דא דער שיעור פון „חמישית ממונו\" — פארוואס זאגט ער אז מצד מידת חסידות קען ער געבן „יותר מחומש\", בעת מיר געפינען דעתו במ\"א (בהל' ערכין וחרמין) אז דער שיעור „אל יבזבז יותר מחומש\" איז שולל דעם „יותר\" אפילו מצד מידת חסידות?\nג. מפרשים22 זיינען מבאר, אז אין די צוויי מקומות הנ\"ל (אין הל' ערכין וחרמין און אין פיהמ\"ש) רעדט דער רמב\"ם וועגן צוויי אופנים אין צדקה:",[["15","15","איוב ב, ד."],["16","16","ראה גיטין נב, א (רמב\"ם סוף הל' נחלות), שצדקה אין לה קצבה (ובפרש\"י שם: בכל שעתא קיימי עניים נמצא נכסיהם כלים)."],["17","17","פאה רפ\"א."],["18","18","מירושלמי פאה שם."],["19","19","כ\"ה גם ברמב\"ם הל' אבל רפי\"ד."],["20","20","כח, א."],["21","21","וכ\"ה בפי' רגמ\"ה שם."],["22","22","ברכי יוסף יו\"ד סרמ\"ט סק\"א ד\"ה ואפשר. וראה גם שו\"ת בית דינו של שלמה יו\"ד סי' א (מח, ג ואילך). ועוד."]]],[1300271233,"אין פירוש המשניות רעדט דער רמב\"ם וועגן א פאל ווען דער אדם ווערט מחוייב בנתינת צדקה דערפאר וואס ער האט פאר זיך די עניים אדער אנדערע אומללים און זיי זוכן און בעטן הילף, ובלשונו „כשהאדם יראה שבוים שהוא חייב לפדותם כו' או רעבים או ערומים שהוא חייב להשביעם ולכסות מערומיהם כמו שאמר23 די מחסורו אשר יחסר לו\" — דעמאלט איז „פחות מחמישית ממונו או כפי חמישיתו\" דארף ער געבן מצד החיוב, און מצד מידת חסידות קען ער געבן מער ווי א חומש.\nבהל' ערכין וחרמין אבער רעדט דער רמב\"ם ווען ער קומט מחלק זיין ממונו לעניים מאליו ומעצמו „דומיא דמקדיש ומחרים\"24, און אויף דעם איז חל דער שיעור קבוע פון „חומש\" און מער פון דעם טאר ער ניט געבן אפילו מצד מידת חסידות25.\nד. ויש להוסיף בזה, אז דער חילוק צווישן ב' מקומות הנ\"ל ברמב\"ם בא־שטייט ניט (בלויז) אין די צוויי באזונ־דערע אופנים אין דער מצוה פון צדקה (צי עס זיינען דא עניים נצרכים לפניו אדער ער טיילט צדקה מעצמו) — נאר (אויך) אין דעם אונטערשייד צווישן דעם גדר המצוה פון ערכין וחרמין און דעם גדר פון מצות צדקה26:\nדער גדר פון מצות ערכין וחרמין איז, ווי דער רמב\"ם איז מסביר דארט אין דער פריערדיקער הלכה27: ההקדשות וחרמין והערכין מצות וראוי לו לאדם להנהיג עצמו בדברים אלו כדי לכוף יצרו ולא יהי' כילי — והיינו אז אין דער נתינה פון ערכין וחרמין איז מודגש די תועלת פאר דעם נותן28 און ניט דאס וואס דער מקבל (הקדש כו') נויטיקט זיך אין דעם.\nמשא\"כ אין פיהמ\"ש, ביי עניני צדקה וגמ\"ח, באשטייט דער גדר המצוה דערין וואס די נתינה איז לצורך המקבל, צו ממלא זיין „די מחסורו\" פון דעם עני, ובלשון הרמב\"ם29 „מצות עשה ליתן צדקה לעניים כפי מה שראוי לעני\"30.\nאון דעריבער, אין הלכות ערכין וחרמין שרייבט דער רמב\"ם בלשון סתמי: אל יפזר יותר מחומש (אן קיינע חילוקים ויוצא מן הכלל), אז ער זאל ניט געבן יותר מחומש אפילו מצד מדת חסידות (ווייל אין דעם פאל איז עס, ווי דער רמב\"ם איז מדגיש, איבערהויפט ניט קיין מדת חסידות)31; משא\"כ אין",[["23","23","ראה טו, ח."],["24","24","לשון הברכ\"י שם."],["25","25","וראה בס' שנסמנו בהערה 22, שזהו החילוק בין מאמר הירושלמי (פאה שם) ודהבבלי (בב' מקומות בכתובות שם)."],["26","26","גם כשאין עניים לפניו — ראה לקמן הערה 36."],["27","27","הלכה יב."],["28","28","ראה גם שו\"ע אדה\"ז או\"ח סקנ\"ו ס\"ג."],["29","29","הל' מתנות עניים רפ\"ז."],["30","30","וראה שאילת יעבץ (ח\"א סוס\"ג) דמפשטות ל' הרמב\"ם מובן דבידו משגת אין בזה כלל הגבלות דמעשר וחומש וצריך ליתן להעני כדי צרכו גם אם הוא יותר מחומש (אלא שמפיהמ\"ש פאה שם לא משמע כן). ע\"ש בארוכה. וראה גם מכתב כ\"ק אדמו\"ר מהורש\"ב נ\"ע (סה\"מ תש\"ט ע' 21. אגרות קודש שלו ח\"א ע' קלח. ועוד) כל מצוה יש לה גבול ומדה כו' ומצות הצדקה אין לה שיעור וכמש\"כ בשו\"ע יו\"ד רסרמ\"ט שיעור נתינה כפי צורך העניים, בל\"ג (וראה שם ע' 17. אגרות קודש שם ע' פה)."],["31","31","בשו\"ע אדה\"ז או\"ח שם שבכדי „שתקבע בנפשו מדת ורב חסד כו'\" (ולא יהי' כילי) „יפזר ויתן ממון הרבה לעניים כו'\" — והיינו גם יותר מחומש (אלא ש„לאחר שתקבע בנפשו מדה זו לא יפזר יותר מדאי שזו אינה דרך טובה ותקנת חכמים שלא יבזבז יותר מחומש\"). וי\"ל דהרמב\"ם בהל' ערכין וחרמין מדבר לא בתחילת עבודתו בכדי לקבוע בנפשו כו' (כבשו\"ע אדה\"ז שם) כ\"א בסדר והנהגה הקבוע, „וראוי לו לאדם להנהיג עצמו\"."]]],[1300271234,"פירוש המשניות, וואו עס רעדט זיך וועגן דער מצוה פון צדקה, וואס גדרה איז צורך העני, איז דארט דער רמב\"ם מוסיף אז ער קען געבן אויך מער ווי א חומש (כאטש ער איז ניט מחוייב) — מצד מדת חסידות32.\nה. דערמיט קען מען אויך מבאר זיין דעם שינוי בדברי הרמב\"ם אין נאך צוויי ערטער:\nא) אין הלכות מתנות עניים33 שרייבט דער רמב\"ם: „בא העני ושאל די מחסורו ואין יד הנותן משגת נותן לו כפי השגת ידו וכמה עד חמישית נכסיו מצוה מן המובחר\": דאס וואס דער רמב\"ם איז מדייק צו זאגן דעם צד החיובי אז ער זאל געבן ביז „חמישית נכסיו\" — און ניט דעם צד שלילי, אז מער פון א חומש זאל ער ניט געבן — איז ווייל מצד דעם גדר פון „הלכות מתנות עניים\", צורך העני — קען ער מוסיף זיין און געבן מער פון חמישית נכסיו (מצד מדת חסי־דות<sup data-n=\"34\">34</sup>.\n[ועפ\"ז יומתק וואס אין סוף הל' ערכין וחרמין דערמאנט דער רמב\"ם כלל ניט דעם גאנצן ענין פון צדקה לעניים, ווארום בא צדקה לעניים35 איז (לדעת הרמב\"ם) בכלל ניטא דער איסור פון אל יבזבז יותר מחומש36].\nב) דברי הרמב\"ם — אין הלכות דעות37, וואו ער פסק'נט „ואסור לו לאדם להפקיר או להקדיש כל נכסיו ויטריח על הבריות\", אז דער איסור איז דוקא ביי „כל נכסיו\" — אנדערש ווי ער זאגט אין הלכות ערכין וחרמין, אז ער זאל ניט אוועקגעבן „יותר מחומש\":\nאין הלכות דעות רעדט דער רמב\"ם ווי אדם דארף זיך פירן כראוי בעניני דעותיו והנהגותיו כו', דעריבער קען ער דא ניט פסק'נען ווי א כלל, אז ער טאר ניט מפזר זיין מער ווי א חומש — ווייל אין הנהגת האדם זיינען דא פאלן ווען ער מעג (און דארף) געבן מער ווי א חומש, ולדוגמא38 — ביי צדקה לעניים (ובפרט ווען דער עני איז עומד לפניו און בעט צדקה לצרכיו כו'):\nמשא\"כ אין הלכות ערכין וחרמין, וואס מצד דער מצוה פון ערכין כו' האט בכל אופן ניט קיין ארט צו מפזר זיין מער פון א חומש, אויך ניט מצד מדת חסידות, כנ\"ל.\nו. ע\"פ הנ\"ל (אז דער ענין פון „אל יפזר יותר מחומש\" ווענדט זיך מצד וועלכן גדר מצוה מען רעדט) — קען מען אויך מבאר זיין לפענ\"ד וואס דער אלטער רבי זאגט אז מ'זאל געבן צדקה ניט בלויז „יותר מחומש\" נאר נאכמער, אוועקגעבן „כל אשר לאיש\" — וואס דאס איז א דריטער אופן, דהיינו ניט",[["32","32","להעיר מצפע\"נ הל' מת\"ע (פ\"ט הי\"ט). שו\"ת שלמת יוסף (סט\"ז אות ג) במש\"כ בדעת השאילתות."],["33","33","פ\"ז ה\"ה."],["34","34","וכמ\"ש בפיהמ\"ש פאה שם."],["35","35","ומש\"כ שם „כל המפזר ממונו במצות\", הכוונה בפשטות לערכין כו' שלפנ\"ז, וכמ\"ש בהלכה (יב) שלפנ\"ז „ההקדשות וחרמין והערכין מצות\", או — גם שאר מצות (חוץ מצדקה). — וראה גם סיום לשונו בפיהמ\"ש פאה שם „ויתנהו בצרכי מצות\"."],["36","36","גם כשאין עניים לפניו. — ול' „אל יבזבז כו'\" שבש\"ס בבלי (כתובות ג, א. ערכין כח, א) י\"ל דלהרמב\"ם אינו מדבר בצדקה לעניים (כבפרש\"י שם) אלא בבזבוז להקדש (וכיו\"ב) כמ\"ש ברש\"י מהדורא קמא (הובא בשטמ\"ק שם). וגם בכתובות (סז, סע\"ב) „אייתי לי חושבנאי דצדקה\", אין הכוונה לצדקה לעניים (כלפנ\"ז שם „הוה עניא כו'\") כ\"א לשם כללי לכל עניני צדקה שלו (כולל הקדשות כו'). ועצ\"ע."],["37","37","פ\"ה הי\"ב."],["38","38","להעיר גם משו\"ע אדה\"ז שבהערה 31."]]],[1300271235,"נאר (א) ביז א חומש39, (ב) אדער „יותר מחומש\" אבער מיט דער הגבלה אז ניט „כל נכסיו\" (ווי דער ראגאטשאווער40 איז מבאר: ומשמע שם מדברי רבינו (אין פירוש המשניות) דרק כל ממונו אין זה מדת חסידות אבל יותר מחומש שפיר41 מותר<sup data-n=\"42\">42</sup> — נאר (ג) „כל אשר לאיש\":\nדאס וואס מצד מדת חסידות קען א איד געבן „יותר מחומש\" אבער ניט כל נכסיו (אופן הב') איז נאך אלץ פאר־בונדן מיט דעם גדר מצוה פון צדקה, וואס ענינה איז צו העלפן דעם עני, אבער דאס וואס דער אלטער רבי אין אגה\"ת און אגה\"ק רעדט, איז וועגן אזא נתינה לצדקה וואס עיקר ענינה איז ניט (נאר) מצד דעם חיוב צו העלפן דעם עני, נאר צוליבן חיוב „לתקן נפשו\" און „לפדות נפשו מתעניות וסיגופים\" —\nאון וויבאלד דאס איז אן ענין שלו בעצמו, איז פארשטאנדיק, אז ער איז „קודם לממונו\" ובפרט ווען דאס איז ענין של נפשו (ע\"ד פקו\"נ), איז דער־פאר אין דעם ניטא קיין שיעור און הגבלה, אויך ניט די הגבלה פון „כל נכסיו\", ווייל „כל אשר לאיש יתן בעד נפשו\"43.\nז. ויש לומר, אז די דריי אופנים אין נתינת ממונו איז דא דוגמתם, זיי שפיגלען זיך אפ בפנימיות הענינים, אין די דריי כללות'דיקע דרגות אין עבודת ה'44:\nדער גדר הנתינה פון מצות ערכין וחרמין ווייזט אויף א דרגא אין עבודה, ווען דער מענטש שטייט (נאך) אין מדידות והגבלות פון זיין מציאות, וכנ\"ל בדברי 'הרמב\"ם „ראוי לו לאדם להנהיג עצמו בדברים אלו כדי לכוף יצרו ולא יהי' כילי כו'\": ער איז דערמיט אויסן ניט (אזוי) צורך הקדש, נאר תועלת עצמו, וואס אע\"פ אז דאס איז א צורך ותועלת פון קדושה, צו כופה זיין דעם יצר און זיינע מדות („לא יהי' כילי\"), אעפ\"כ איז דאס פארט צוליב זיך ע\"ד לשון הש\"ס45 אדעתא דנפשי'; און ווייל ער שטייט (נאך) אין דער מדידה והגבלה פון זיין מציאות, דערפאר איז בהתאם לזה זיין חיוב המצוה — וואס ווייזט אויף דעם אופן הצוותא וחיבור שלו מיטן אויבערשטן (און די המשכה וואס ער איז ממשיך מלמעלה) — אויך במדידה והגבלה.",[["39","39","להעיר שממ\"ש אדה\"ז שבנדו\"ד „אין לחוש משום אל יבזבז יותר מחומש\", משמע, דס\"ל שהדין דאל יבזבז הוא גם בצדקה (כדעת הרמ\"א — יו\"ד סרמ\"ט ס\"א. וכ\"כ אדה\"ז בקו\"א להל' מכירה שלו ס\"ד), דלא כהרמב\"ם בפיהמ\"ש כו' דס\"ל שמצד מדת חסידות יש לתת יותר מחומש. ולפענ\"ד שגם אדה\"ז אפ\"ל דס\"ל כהרמב\"ם כאשר בא העני ושואל די מחסורו כו' — שהרי באגה\"ת ובאגה\"ק (הנ\"ל) מדובר (לא שהעני בא וכו', כ\"א) שהנותן משתדל להרבות בצדקה, שאז חוששין לאל יבזבז יותר מחומש (לולי הצורך לתיקון נפשו). ועפ\"ז יומתק שבאגה\"ק סט\"ז כ' רק ש„היא רפואת הגוף ונפש ממש, אשר עור בעד עור וכל אשר לאיש יתן בעד נפשו\", ולא כתב שאין לחוש משום אל יבזבז כו' — כי שם מדבר אודות החיוב דמצות הצדקה, „ליתן ביד מלאה ועין יפה לכל הצטרכות ההכרחיים לדי מחסורי האביונים נקיים אשר עיניהם נשואות אלינו כו'\", היינו כאשר העני בא ושואל די מחסורו."],["40","40","צפע\"נ על הרמב\"ם סוף הל' ערכין."],["41","41","וראה בצפע\"נ שם (ובהל' מת\"ע פ\"י הט\"ז) עוד אופנים."],["42","42","וראה גם ס' אגרות קודש אדמו\"ר הזקן ע' קלד־ה."],["43","43","וכן משמע בשו\"ע אדה\"ז או\"ח שם: יפזר ויתן . . מדת ורב חסד שנשתבח בה הקב\"ה."],["44","44","להעיר מאגה\"ק סי\"ג (בתחלתו). מאמרי אדה\"ז־פרשיות ח\"א ע' שעח ואילך."],["45","45","פסחים סה, סע\"ב."]]],[1300271236,"[ועפ\"ז יש לבאר (בדרך רמז עכ\"פ) דעם דיוק לשון הרמב\"ם „והעושה כן עובר על דעת הכתוב שהרי הוא אומר מכל כו'\" (א לשון (ואריכות) בלתי רגילה, דלכאורה האט דער רמב\"ם גע־דארפט זאגן „עובר על מה שנאמר\" וכיו\"ב):\nהיות אז דער איד געפינט זיך נאך בגדר מציאותו, איז דאן זיין עבודה ע\"פ טעם ודעת דקדושה — במעמדו ומצבו איז ניטא קיין ארט אויף דער עבודה שלמעלה מטעם ודעת. דעריבער איז דער רמב\"ם מסיים, אז ביי א אידן וואס האלט נאך ניט ביי אט דער מדריגה איז „אין זו חסידות (שטות דקדושה, א הנהגה לפנים משורת הדין)46 אלא שטות\" (שלמטה מטעם ודעת)47].\nבשעת א איד בעבודתו גייט ארויס פון הגבלת מציאותו און ער זוכט ניט (דוקא) זיין אייגענעם תועלת (אפילו פון קדושה), נאר ער טראכט וועגן דעם צווייטן איד'נס צרכים, איז דאס אן עבודה למעלה ממדידה והגבלה — און דאס דריקט זיך אויס אין מצות צדקה, וואס גדרה וענינה איז, אז דער נותן גיט ניט לתועלת עצמו, נאר (בעיקר) לצרכו וטובתו של העני48; און דעריבער איז אויך די מצוה (אויך דער צוותא וחיבור און די המשכה מלמעלה שעי\"ז) ניט מדוד ומוגבל אין דעם שיעור פון חומש דוקא.\nאע\"פ אז דאס וואס א איד פארבויגט אויף זיך און טראכט וועגן א צווייטן אידן איז א תנועה פון ארויסגיין פון הגבלות מציאותו — איז דאס אבער נאך אלץ ניט קיין דרגא וואס איז לגמרי העכער פון מדידה והגבלה; ווארום ביי אים איז א חשבון ומדידה (עכ\"פ) ביחס צום צווייטן — „כפי מה שראוי לעני\".\nלמעלה מזה איז דער סוג עבודה „לתקן נפשו\": וויבאלד דאס איז פאר־בונדן מיטן עצם מציאות וחיי האדם ממש ע\"ד פקוח נפש, איז אין דעם לגמרי ניט שייך חשבון ומדידה, ובעבו־דתו — די עבודה פון בכל מאדך, וואס קומט מצד יחידה שבנפש (יחידה לייחדך, וואס איז אין איין זאך מיט דעם אויבערשטן אליין) — דעריבער איז מצד בחי' זו די עבודה פון בלי גבול ממש49, ס'איז ניט שייך קיין חשבון ומדידה, „כל אשר לאיש יתן בעד נפשו\".\nח. והנה וויבאלד אז מצד דעם גדר פון מצות צדקה דארף א איד געבן במדת חסידות אויך „יותר מחומש\" (ובפרט ווען דער עני קומט און בעט זיינע הצטרכות'ן) — איז מובן, אז כשם ווי דאס איז במדת והנהגת האדם, אזוי איז עס אויך (ועאכו\"כ) בנוגע דער צדקה פון דעם אויבערשטן — „לך50 ה' הצדקה\": היות אז אידן זיינען מתפלל, זיי קומען און בעטן אז דער אויבער־שטער זאל זיי געבן „די מחסורם\" („צדקה\"), דארף דער אויבערשטער כביכול, ממלא זיין בקשתם און זיי געבן „יותר מחומש\", און דאס מיינט מער ווי א חומש כביכול פון זיינע, פון דעם אויבערשטנ'ס, נכסים!",[["46","46","ראה רמב\"ם הל' דעות פ\"א ה\"ה דחסיד הוא כשיתרחק מדעה הבינונית. וראה שו\"ע אדה\"ז או\"ח שם."],["47","47","להעיר ממרז\"ל (כתובות יג, א) „אהני' לי' שטותי' לסבא\", שטות דקדושה המהפכת שטות דלעו\"ז. וראה ד\"ה באתי לגני השי\"ת פ\"ה (ודשנת תשט\"ו — בסה\"מ באתי לגני ח\"א)."],["48","48","וראה גם קו\"א בשו\"ע אדה\"ז הל' מכירה שם."],["49","49","בכל הנ\"ל להעיר מאגה\"ק סיו\"ד שם. ואכ\"מ."],["50","50","דניאל ט, ז."]]],[1300271237,"און על אחת כמה וכמה ווען דאס האט צו טאן מיטן העכסטן און עיקר־דיקן אופן פון צדקה וחסד — פדיון שבוים51, אויסלייזן די אידן פון גלות דורך דער גאולה שלימה.\nאון נאכמער דערפון (— און אן ערך), וויבאלד אז דאס איז כביכול נוגע צו דעם אויבערשטן אליין: ווארום נוסף אויף דעם, וואס יעדער איד איז א „חלק אלקה ממעל ממש\"52 (און דערפאר, ווען דער איד („חלק\") איז אין גלות, רירט עס אז כביכול דעם אויבערשטן), איז דאך ידוע אז „שכינתא בגלותא\"53, אז דער אויבערשטער געפינט זיך כביכול אין גלות; וכמש\"כ54: „ושב ה\"א את שבותך\", „והשיב לא נאמר אלא ושב\"55 — איז דאך אוודאי און אוודאי אז אין דעם איז כלל וכלל ניטא קיינע הגבלות, ווייל „כל אשר לאיש — אין איש אלא הקב\"ה, שנאמר56 ה' איש מלחמה57 — יתן בעד נפשו\".\nאון דאס מיינט (בפשטות) אז עס זאל באלד מקויים ווערן דער יעוד פון גאולה „כימי צאתך מארץ מצרים\", אז „לא עיכבן המקום כהרף עין\"58,\nבשעתא חדא וברגעא חדא59 גייען אידן ארויס פון גלות „ואתם תלוקטו לאחד אחד בני ישראל\"60, „בנערינו ובזקנינו בבנינו ובבנותינו\"61 ו„כספם וזהבם אתם\"62 — „ושב ה' אלקיך (שכינתא בגלותא) את שבותך\", און מען קומט אין ארצנו הקדושה „ארץ אשר גו' תמיד עיני ה\"א בה מרשית השנה ועד אחרית שנה\"63, און מען איז זוכה לקיום היעודים „אפס64 כי לא יהי' בך אביון גו'\" „לא65 יהי' שם לא רעב כו' המעד־נים מצויין כעפר כו'\", בגאולה האמי־תית והשלימה, על ידי משיח צדקנו, במהרה בימינו ממש.\n(משיחת ש\"פ ראה תשד\"מ)",[["51","51","להעיר מצפע\"נ שם: „פדיון שבוים דהיא מצוה מחוייבת שאני, וגם הוי בגדר לאו דלא תעמוד כו'\"."],["52","52","איוב לא, ב. ובתניא רפ\"ב מוסיף תיבת „ממש\"."],["53","53","זח\"ג ד, ב. סו, סע\"א. ועוד."],["54","54","נצבים ל, ג."],["55","55","מגילה כט, א (הובא בפרש\"י עה\"פ שם) — רשב\"י אומר בוא וראה כמה חביבין ישראל כו' — בעל השמחה דיום ג' שבוע זה (בחוקותי תשמ\"ו)."],["56","56","בשלח טו, ג."],["57","57","סוטה מב, ב. וש\"נ."],["58","58","מכילתא ופרש\"י עה\"פ בא יב, מא."],["59","59","כפס\"ד הרמב\"ם „מיד הן נגאלין\" (הל' תשובה פ\"ז ה\"ה. ושם בה\"ז) „צועק ונענה מיד שנאמר (ישעי' סה, כד) והי' טרם יקראו ואני אענה\"."],["60","60","ישעי' כז, יב."],["61","61","בא י, ט."],["62","62","ישעי' ס, ט."],["63","63","עקב יא, יב."],["64","64","ראה טו, ד."],["65","65","רמב\"ם סוף הל' מלכים (וספר היד כולו)."]]],[1300271238,""],[1300271239,"ל * שש 4 1 4 1 ט ן . ןן וי 1"],[1300271240,""],[1300271241,"4 ש%ע4ע 164 פש נ*ב 52 ב 611 ן"],[1300271242,"מפתת\nשיחות :\nשו \"%פ ( תז וו עד וי וו נו %לטן\" קונ %ד\"מ ......... ..............\n229\nושוזעף ' פ חח %כףעז . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n237 \" \" ' \"\n\" ונח ) ן\nער ' פ וי ) וזל ופ ' עה) לים ,כשה \" ר ) ) וד ' %וזעתם \" ר 249 . . . . . . . . . . . . . . . .\n\"\nעף ' פ צו ופ' פרה 71עתא \" ו . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n\" %פ עעציני ועהיפ ונזריע ונשז\" מ 267 . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n, 261 \"\nל\"ג בעומר ונ קז \" עץ נב עת הפאראד \" )277.......... ..............\n\"\nעף' פב רעג זח זיו נעת ץ\"ו 297.-......... ..........,... ..............\n'"],[1300271243,"א. בקשר מיט דעם יום הולדת פון דעם רמב״ם בערב פסח¹ — איז מען מציע:\nע״ד ווי דער ענין וואס מ׳האט מחלק געווען ש״ס² (תלמוד בבלי, ועד״ז — תלמוד ירושלמי), אז בכל יום ויום זאל מען לערנען א שיעור, אזוי אז מ׳זאל מסיים זיין גאנץ ש״ס במשך זמן מסויים —\nוואלט געווען א דבר נכון ביותר אז מ׳זאל אזוי טאן בנוגע לספר הרמב״ם — ספר ״משנה תורה״³, אדער ״יד החזקה״, (אדער ספר הרמב״ם (סתם)), וועלכער איז ספרו העיקרי⁴ — ספר הלכות שלו, און דער איינציקער פון זיינע ספרים וועלכן ער האט געשריבן בלשון הקודש:\nמ׳זאל מחלק זיין דעם ספר לשיעורים, ובכל יום זאל מען לערנען על הסדר דעם שיעור יומי ברמב״ם⁵, אזוי אז אלע משתתפים זאלן מסיים זיין דעם גאנצן ספר ״יד החזקה״ במשך זמן מסויים ביום אחד.\nומה טוב, כמנהג ישראל בכיו״ב — מאכן דעמולט א סיום ברבים, א סעודה, אדער עכ״פ א התוועדות, לגמרה של (משנה) תורה⁶, ו״ברב⁷ עם הדרת מלך״⁸.\nב. פון די טעמים ומעלות בזה [נוסף אויף דעם וואס א הוספה בלימוד התורה איז א דבר טוב ונכון, ובפרט לימוד תורה דרבים]:",[["1","1","״נולד ערב פסח יום השבת שעה ושליש אחר חצי היום״ (סדה״ד ד״א תתקכ״ז. מספר יוחסין מאמר ד (דורות האחרונים)). וי״ל הדיוק בזמן הולדתו (דבר שלא מצינו בשאר גדולי ישראל), שזהו בהתאם לתכלית הדיוק דהרמב״ם (בספרו יד החזקה) יותר משאר הפוסקים לפניו ולאחריו. — ולהעיר משבת (ל, סע״א) ״כמלא נימא״, ב״ב (טז, ב) מקדים רגע כו׳."],["2","2","ראה חגיגה (י, א) ״מש״ס לש״ס״."],["3","3","כפי שנקרא ע״י הרמב״ם בהקדמתו לספרו."],["4","4","וי״ל: כשם ש״אנא נפשי כתבית יהבית״ (שבת קה, א — כגירסת הע״י), שהקב״ה ״הכניס״ את עצמותו (כביכול) בתורה (ראה לקו״ת שלח מד, סע״ד. אוה״ת יתרו ע׳ תתקא ואילך), ולכן, ע״י לימוד התורה ״אותי אתם לוקחים״ (ויק״ר פ״ח, יב. וראה זח״ב קכז, א. שם קמ, ב) — הרי כן הוא בצדיקים ש״דומין לבוראן״ (ב״ר פס״ז, ח. ובכ״מ), שהרמב״ם ״הכניס״ את עצמותו (נפשו) בספרו. ונמצא שע״י לימוד ספרו — מתאחדים עם עצמות הרמב״ם (לא רק עם שכלו — כדלקמן ס״ב)."],["5","5","כמובן, בהוספה על השיעורי תורה דכל חד וחד לפום שיעורא דילי׳. וראה לקמן בפנים (ס״ב) בנוגע להלכות הצריכות."],["6","6","מדחז״ל עה״פ (מ״א ג, טו) ״ויעמוד (שלמה) לפני ארון ברית ה׳ גו׳ ויעש משתה גו׳״ (שהש״ר פ״א (א), ט. קהר״ר רפ״א. יל״ש מלכים רמז קעה). וראה להלכה — רמ״א יו״ד סו״ס רמו (משבת קית, סע״א ואילך), ועד״ז ברמ״א או״ח סתקנ״א ס״י — לענין סיום מסכת. טור ורמ״א או״ח סתרס״ט — לענין סיום תושב״כ בשמח״ת. ועד״ז י״ל בסיום ״משנה תורה״ (ראה ל׳ הרמב״ם בהקדמתו להספר בהטעם לקריאת שם הספר). — ובערב פסח בפרט — סיום מסכת לבכורים."],["7","7","ל׳ הכתוב — משלי יד, כח. וראה אנציקלופדי׳ תלמודית ערך ״ברב עם״. וש״נ."],["8","8","להעיר שכו״כ ממפרשי ספר הרמב״ם הכניסו בשם פירושם תיבת ״מלך״ (משנה למלך; שער המלך; יד המלך; ועוד)."]]],[1300271244,"א) דורך דעם וואס אידן לערנען צוזאמען דעם זעלבן ענין אין תורת השם, תורה אחת — פאראיינציקן זיי זיך. און — ביז אין א ״יחוד נפלא שאין יחוד כמוהו כו׳ נמצא כלל כו׳״⁹ — כמבואר בתניא¹⁰ אז בשעת איינער לערנט א דבר שכל ווערט ער נתאחד מיט אים ב״יחוד נפלא כו׳״. וואס דערפון איז פארשטאנדיק, אז בשעת עטלעכע לערנען דעם זעלבן ענין בשכל והבנה שלהם, ווערן זיי אלע נתאחד מיטן זעלבן שכל, במילא ווערן זיי דורך דעם נתאחד ב״יחוד נפלא כו׳״ אויך זב״ז.\nאון היות אז דאס איז א ״יחוד״ וואס ווערט אויפגעטאן (ניט דורך א דבר שכל סתם, נאר) דורך תורה, וואס זי איז ״נצחית״¹¹ — איז עס א יחוד נצחי.\nוואס דאס איז נוסף על הפשוט, אז דורך דעם וואס עטלעכע אידן לערנען דעם זעלבן ענין, קענען זיי זיך צוזאמענרעדן און מפלפל זיין אין דעם, און דורך דעם קומט צו בא יעדערן הבנה אין דעם ענין. און כאטש אז אין דיעותיהן שוות¹², איז אבער ״ואת והב בסופה״¹³, ווערט צווישן זיי אחדות ושלום דורך דעם זעלבן ענין אין תורה אחת.\nב¹⁴) אין ספר ״משנה תורה״ להרמב״ם איז דא א מעלה עיקרית בנוגע למצות לימוד וידיעת התורה כולה. ובהקדים:\nבמצות לימוד התורה זיינען פאראן כמה דרגות: (א) ״לימוד המביא לידי מעשה שהן הלכות הצריכות לכל אדם לידע אותן לקיים המצוות כהלכתן״¹⁵. (ב) ״לידע כל התורה שבכתב ושבע״פ כולה״, וואס אין דעם איז נכלל ״כל התלמוד בבלי וירושלמי ומכילתא וספרא וספרי ותוספות וכל המדרשים . . ומדרשי רשב״י כו׳ לקיים מצות שמור תשמרון את כל המצוה וגו׳״¹⁶, כולל לימוד כל ההלכות, האגדה וסודות התורה כו׳¹⁷. (ג) וויבאלד אז ס׳איז דא א מעלה מיוחדת בלימוד הלכות התורה¹⁸ — יש ללמוד¹⁹ אלע הלכות שבתורה, אויך די וואס אינן נוהגות וצריכות²⁰ (ווייל אין דעם איז ניטא קיין חילוק צווישן הלכות הצריכות און הלכות שאינן צריכות). (ד) לימוד מיוחד כדי לחקוק דברי תורה במוח הזכרון²¹.\nאון אין לימוד הלכות (דרגא השלישית) — איז דא א מעלה מיוחדת אין ספר הרמב״ם:\nדער ספר ״משנה תורה״ להרמב״ם איז א ספר וועלכער נעמט ארום אלע הלכות שבתורה — ובלשון הרמב״ם בהקדמתו לספרו זה: ״חיבור זה מקבץ לתורה שבעל פה כולה כו׳, אדם קורא",[["9","9","תניא פ״ה (ט, ב)."],["10","10","שם."],["11","11","תניא רפי״ז. ובכ״מ. וראה יד הל׳ יסוה״ת רפ״ט. הל׳ מלכים פי״א סה״ג."],["12","12","ראה ברכות נח, רע״א. סנהדרין לח, א. ועוד."],["13","13","חוקת כא, יד. קידושין ל, ב."],["14","14","ונוסף על הנ״ל — ששייך בכל עניני התורה."],["15","15","הל׳ ת״ת לאדה״ז פ״ב ס״ט. וש״נ."],["16","16","שם פ״א ס״ד. רפ״ב. פ״ב ס״י. וש״נ."],["17","17","שם פ״א ס״ד. פ״ב ס״ב. וש״נ."],["18","18","ראה מגילה כח, ב — ש״הלכות״ (דוקא) נקראות ״תגא וכתרה של תורה״, ובהמשך לזה — ״תנא דבי אליהו כל השונה הלכות בכל יום כו׳״. וראה אגה״ק סכ״ט."],["19","19","כמובן — זהו דרגא שבין שתי הדרגות שלפני׳."],["20","20","ראה ספר אור צדיקים שבהערה 23."],["21","21","ראה לקו״ת קדושים ל, ד. ושם, שבענין זה — מעלה מיוחדת בסדר קדשים."]]],[1300271245,"בתורה שבכתב תחלה ואח״כ קורא בזה ויודע ממנו תורה שבעל פה כולה״²².\nקומט דערפון אויס, אז יעדערער וואס וועט לערנען דעם ספר הרמב״ם²³ — איז מקיים דעם ענין צו לערנען אלע הלכות שבתורה²⁴.\nומפני טעמים אלו (ועוד טעמים) איז א דבר הכי נכון, כנ״ל, צו מחלק זיין דעם ספר הרמב״ם לשיעורים, און בכל יום זאל יעדערער לערנען דעם שיעור קבוע ליום זה, ביז מסיים זיין דעם רמב״ם בזמן מסויים, אלא אין דעם זעלבן טאג.\nג. ואע״פ אז אין יעדן לערנען תושבע״פ בשיעור קבוע מראש, איז אויך דא לכאורה א חסרון — ווייל מצד ההתחייבות אז ער מוז אפלערנען יעדן טאג א חלק קבוע און מוז פארענדיקן לערנען דעם ענין לזמן מסויים, איז מעגלעך אז דער לימוד וועט זיין לפעמים באופן שטחי —\nדארף מען דאס לכל לראש אליין באווארענען, דורך דעם וואס מ׳איז זיך מתבונן, אז מ׳לערנט תורת הוי׳, ובמילא ״פאסט ניט״ אז מ׳זאל עס לערנען באופן שטחי.\nועוד ועיקר: מ׳האט בכיו״ב א הוראה פון כ״ק מו״ח אדמו״ר נשיא דורנו: ער האט אליין צעטיילט ספר התניא אויף חלקים קבועים (און עס געהייסן מפרסם זיין), אזוי אז במשך השנה זאל מען מסיים זיין דעם גאנצן ספר²⁵.\nהאט מען דערפון א פתיחת הדרך אז כאטש ס׳איז דא די אפשריות אז א לימוד פון א שיעור קבוע מראש זאל ברענגען צו לימוד באופן שטחי, איז כדאי דאס טאן מצד מעלות הדבר, ובפרט אז מ׳קען באווארענען דעם חסרון, כנ״ל.\nד. בהמשך להנ״ל — איז מען מציע, אז דער אופן חלוקת פ״ג ההלכות²⁶",[["22","22","משא״כ בריי״ף ושו״ע וכו׳ לא הובאו כו״כ מצוות שאינן נוהגות בזמן הזה וכיו״ב."],["23","23","ראה ס׳ אור צדיקים (להר״מ פאפירש) סכ״ב אות יט: צריך אדם להשלים תרי״ג מצות, במעשה, בדיבור, ומחשבה, ולכן יש ללמוד יד הגדולה להרמב״ם כו׳ שיש בו ביאור התרי״ג. וראה הל׳ ת״ת שם פ״ב סי״א:"],["24","24","ואף שפסק אדה״ז שיש ללמוד הלכות עם הטעמים — הרי בלימוד ספרו של הרמב״ם עסקינן, דס״ל שיכולים להורות גם בלא לימוד טעמי ההלכות, שלכן חיבר ספרו בלי נתינת טעמים להלכות כלל (ראה אדה״ז קו״א להל׳ ת״ת רפ״ב). וראה בארוכה לקו״ש חלק ל״ד ע׳ 16 ואילך."],["25","25","אין ראי׳ מלימוד שיעור חומש היומי — כי בתושב״כ אפילו לא ידע מאי קאמר עולה לתורה ומברך ברכה לפני׳ ולאחרי׳ (הל׳ ת״ת לאדה״ז פ״ב סי״ב)."],["26","26","כמ״ש הרמב״ם בסוף הקדמת ספר היד. *) ועד״ז מנה את מספר ה״הלכות״ (הכלליות) שבכל ספר (מי״ד הספרים) במנין המצוות ובריש כל ספר, ומנין המצוות שבכל ״הלכות״, ובכמה מקומות בספרו נקט מנינא סימן לזכירה (יד מלאכי כללי הרמב״ם אות לד. וראה גם אגרת תחה״מ שלו — ע׳ עד בהוצאת קאפח). וצ״ע למה לא מנה (בכו״כ מקומות) את מספר הפרקים ומספר ה״הלכות קטנות״ (כלשונו בסוף ההקדמה) שבכל ספר מי״ד הספרים ושבכל ספר היד. (ובפרט שחלוקת ההלכות (הקטנות) היא בדיוק ולומדים ממנה להלכה כו׳ — ראה לדוגמא הל׳ ת״ת לאדה״ז פ״א קו״א סק״א (ג, א (תתרז, א)). — וברמב״ם הוצאת פרנקל (ירושלים תשל״ה) תוקן פיסוק הל׳ ברמב״ם בכ״מ — ראה הקדמת המו״ל לס׳ זמנים 12, ב). ומספר הפרקים שבכל ״הלכות״ ושבכל ספר שנדפס בסוף כל ספר — צ״ע אם הוא מהרמב״ם, שהרי בכ״י מהכת״י אינו, ואינו בסוף כל ספר (לדוגמא — ספר המדע). ומה שנמצא דף כת״י שבשוליו חתם עליו הרמב״ם שהגיהו מספרו (צילומו נדפס ברמב״ם הוצאת פרדס בסופה) ושם כתב המעתיק גם מספר הפרקים, הרי לתרץ שינוים הנ״ל — נלפענ״ד שהאישור דהגהה זו הוא רק על תוכן הלכות שלו ולא לכל"]]],[1300271246,"שבספר הרמב״ם זאל זיין²⁷ באחד מהאופנים דלהלן²⁸ ובכולם — כמובן, בלי נדר:\nא) די התחלה וועט זיין, כבכל עניני תומ״צ, באופן פון זריזין מקדימין²⁹ — ביום א׳ הסמוך פ׳ אמור, ז״ך ניסן.\nמובן ופשוט אז דער לימוד דארף זיין מתאים ככל האפשרי לרצון (המחבר) הרמב״ם, כולל — לויט דעם סדר שקבע, און דעריבער זאל יעדערער לערנען: די ערשטע פיר טעג — הקדמת הרמב״ם (כולל מנין המצוות וכו׳), און בימים שלאח״ז — זאל מען לערנען בכל יום דריי פרקים.\nאון וויבאלד אז אין רמב״ם זיינען פאראן (ארום) טויזנט פרקים, וועט דעמולט אויסקומען אז מ׳וועט מסיים זיין דעם רמב״ם ביום זכאי בנדו״ד (אדער בסמיכות ממש לו) — יום הולדת הרמב״ם (ערב פסח) בשנה הבאה עלינו ועל כל ישראל לטובה, און מ׳וועט דעמולט קענען מאכן א חג הסיום ברבים.\n— היות אז יום הולדת הרמב״ם איז בערב פסח, קען מען עס דעמולט ניט מאכן³⁰, ובפרט באופן המתאים, ווייל מ׳איז דעמולט פארנומען מיט טרדות והכנות לפסח — זאל מען מאכן דעם סיום ברבים — ״ברב עם״ — בסמיכות לזמן זה, ביום המתאים לפי תנאי המקום וכו׳³¹.",[["27","27","אבל לכאורה אין לחלק את ספר היד בין כמה אנשים (ע״ד חלוקות הש״ס בין כמה אנשים, שנחשב כאילו כאו״א מסיים כל הש״ס (ראה שו״ת נחלה לישראל ס״י אות טז. ועוד. שד״ח כללים מערכת מ כלל קצח בסופו. וראה לקו״ש ח״י ע׳ 267 ובהערות שם. ועוד)) — כי [נוסף לזה שבזה חסר הענין דאחדות ישראל ע״י לימוד כולם אותו ענין בתורה, וגם — אין קיום החיוב ללמוד כל הלכות שבתורה]: ידוע כלל הרמב״ם בספרו יד החזקה (יד מלאכי כללי הרמב״ם אות ו׳. כללי הרמב״ם שנדפסו בריש ס׳ היד. וש״נ), שסומך בהלכותיו המאוחרות על מ״ש בהלכות הקודמות בספרו. ונפק״מ להלכה, שלפעמים לא פרט או כתב באופן מסויים כי סמך על מ״ש לפנ״ז בספרי׳. ואם יחלקו הרמב״ם וכל א׳ ילמוד רק חלק מהרמב״ם ולא על הסדר, אפ״ל טעות בהבנת ההלכה כי לא למד הלכה שלפנ״ז, היפך הכוונה שכולם ילמדו ההלכות בלא טעות (ולהעיר אשר ע״י טעות האחד — חסר בלימוד כל המשתתפים בלימודו). משא״כ בש״ס הרי ״בתרי מסכתות אין סדר למשנה״ (בנוגע להלכה) אף שבכלל יש סדר למסכתות שסידר רבינו הקדוש (כמבואר גם בהקדמת הרמב״ם לפיה״מ ד״ה וחלק הששי) — ב״ק קב, א. תוס׳ ריש מס׳ ב״מ. ועוד. פרט בדקדוק (שאינו נוגע להלכה), ל׳ זכר ונקבה, מ״ם סופית וכיו״ב, ועד״ז בנוגע מספר הפרקים. בכלל אפשריות וסיבת השינויים בין מספרי הפרקים שבסוף הספרים (לדוגמא בסיום הספר — חתקפ״ב פרקים, ובכמה כת״י — תתקפ״א או מספר אחר, וכל אלה אין מתאימים למספר הפרקים שלפנינו — אלף) — י״ל, ע״פ הידוע שהרמב״ם כתב ספרו בכמה מהדורות, ושינה וכו׳ מזל״ז — ראה בצילומים מכת״י הרמב״ם (שנדפסו בהוצאת שולזינגער בסופה, ועוד) שהרמב״ם העביר (בכמה מקומות) קו על כת״י שלו ובפרט — ״שמיני״ וכתב למעלה ״אחד עשר״ ובפרק שלאח״ז לא שינה מספר הפרק, וכיו״ב. *) ועפ״ז גם מובן שאין מקום להתחיל את לימוד הרמב״ם מפ״ה דהל׳ יסוה״ת וכיו״ב, או לדלג בהפרקים הראשונים — וה״ז היפך מכלל הרמב״ם שלימוד ספרו צ״ל ע״פ הסדר, וסמך על מ״ש בהלכות לפנ״ז."],["28","28","וכמפורט בה״מורה שיעור״ (לב׳ האופני חלוקה אלו, ודלקמן ס״ו) — שי״ל בחוברות בפ״ע."],["29","29","פסחים ד, א. וראה אגה״ק סכ״א."],["30","30","יש מתענין בערב פסח, ועכ״פ ממעטין באכילה — ראה שו״ע אדה״ז או״ח סת״ע (וש״נ) ור״ס תעא (וש״נ). — ושם אופנים שמותר ע״פ דין, אבל אין זה מבטל טרדות ההכנות לחג."],["31","31","וראה ש״ך יו״ד סרמ״ו סקכ״ז (מתשובת מהר״ם מינץ סקי״ז) ״כשבאין לסוף מסכתא ישייר מעט בסוף עד שעת הכושר יומא דראוי לתקן בו"]]],[1300271247,"ב) די וואס מפני איזה סיבות איז זיי ניט מעגלעך צו אפלערנען יעדן טאג דריי פרקים, איז דא א צווייטער סדר:\nלערנען בכל יום איין פרק (אנהויבנדיק פארדעם — לערנען די הקדמה בז״ך ניסן, כנ״ל).\nדאן וועט אויסקומען, אז מען וועט מסיים זיין דעם רמב״ם בערך אין דריי יאר ארום — בחודש שבט תשמ״ז [שנת תשמ״ו — איז א שנה מעוברת], ומה טוב אז מ׳זאל עס מסיים זיין ברבים ביומא דפגרא בסמיכות לזה.\n[ולהעיר פון די צוויי מנהגים בהשלמת התורה, תושב״כ — אחת לשנה, אדער אחת לשלש שנים³². ועד״ז — מזה סמוכין — בנוגע צום רמב״ם — ״משנה תורה״.\n— אזוי ווי נתפשט המנהג אז מ׳זאל מסיים זיין תושב״כ אחת לשנה³³, איז כדאי אז מען זאל זיך משתדל זיין לערנען באופן הא׳, לסיים הרמב״ם בשנה אחת: אבער אויב ניט — איז דא דער צווייטער סדר, כנ״ל].\nג) ויש להוסיף:\nדורך דעם וואס אלע לערנען ג׳ פרקים ביום איז דא די מעלה פון אחדות ישראל און לימוד כל הלכות שבתורה, אבער דערביי קען פעלן אין דעם חיוב פון לימוד התורה לעיונא, און בחיוב פון ״לאפשא לה״³⁴, לחדש כו׳³⁵:\nבשעת מ׳לערנט דריי פרקים א טאג איז שווער צו לערנען אלע הלכות בעיון ופלפול, וכיו״ב. ביז אז עס קען אויסקומען אז דער לימוד זאל זיין באופן שטחי (כנ״ל ס״ג).\nדעריבער איז כדאי — אז די וואס זיינען שייך לזה — זאלן לערנען (אין צוגאב צו די דריי פרקים בכל יום) איין הלכה³⁶, עכ״פ אין פרט, פון דעם שיעור יומי (די דריי פרקים) בעיון ופלפול, וכו׳.\nה. וויבאלד אז אין דעם איז נוגע און עס איז דא אן ענין עיקרי — אחדות ישראל (כנ״ל ס״ב) — אחדות כל ישראל — איז מובן, אז אין דעם לימוד הרמב״ם דארפן — עס איז כדאי עס זאלן — זיך משתתף זיין אלע אידן — ״נצבים . . כולכם לפני השם גו׳״³⁷ — אויך נשים³⁸ וטף, אויך טף בידיעות,\nבלשון הכתוב³⁹ — ״בנערינו ובזקנינו גו׳ בבנינו ובבנותינו״,\n[ובפרט אז ס׳איז דא א מעלה מיוחדת בשעת קינדער שטייען באחדות (נוסף על ענין האחדות דכל ישראל, כולכם — שכולל טפכם³⁷), ווייל ״והשיב לב אבות על בנים — ע״י בנים״⁴⁰ — זיי האבן א השפעה אויף די עלטערן, ווי מ׳זעט",[["","","סעודה כו׳, ולכך מנהג להודיעם (הבעלי בתים) כשבא הרב לסיים המסכתא כדי שיבואו הב״ב גם כן לסיומא כו׳״. ובס׳ תורת חיים (או״ח סתקנ״א סקכ״ז) מפרש דברי מהר״ם מינץ — ״דהוא משום כבוד התורה שאז יהי׳ נעשה ביותר הידור ברוב עם ולכן שפיר יוכל לאחר (זמן הסיום) כו׳״."],["32","32","רמב״ם הל׳ תפלה רפי״ג. מגילה כט, ב."],["33","33","רמב״ם שם."],["34","34","זהר שבהערה הבאה."],["35","35","הל׳ ת״ת לאדה״ז פ״ב ס״ב. וראה זח״א יב, ב. אגה״ק סכ״ו (קמה, א)."],["36","36","להעיר מהמדה שהתורה נדרשת בה: שדבר שהי׳ בכלל ויצא מן הכלל ללמד — מלמד על הכלל כולו."],["37","37","נצבים כט, ט־י. וראה לקו״ת ר״פ נצבים."],["38","38","ראה לקמן ס״ז."],["39","39","בא י, ט."],["40","40","מלאכי ג, כד ובפרש״י."]]],[1300271248,"בפועל אז עלטערן גיבן נאך וואס קינדער ווילן, ובשעת עס ווערט אחדות בא די קינדער דורך לערנען די זעלבע ענינים, וועט עס אויך צוגעבן אין אחדות בא די עלטערן].\nו. ווי קען מען אריינציען אויך די אידן וואס זיינען ניט שייך צו לערנען ספר ״יד החזקה״ — קינדער וועלכע זיינען אינגער פון בן חמש עשרה לגמרא⁴¹, ובן עשר שנים למשנה⁴¹, אדער קטנים וקטנות בידיעות וכיו״ב — אזוי אז אלע אידן זאלן נתאחד ווערן צוזאמען דורך לערנען דעם זעלבן ענין בתורה?\nי״ל אז דאס האט דער רמב״ם — דער ״מורה הנבוכים״ וספיקות בדורו ובהדורות שלאחריו — באווארנט בעצמו:\nבהקדמתו לספר המצוות שלו, שרייבט ער אז ספר המצוות שלו איז ווי א ״הקדמה״ צום ספר היד, ווייל אין ספר המצוות זיינען אויסגערעכנט און געבראכט בביאור קצר אלע תרי״ג מצוות וועלכע ווערן נתבאר בפרטיות און בארוכה בספר היד.\nדעם ספר המצוות האט דער רמב״ם געשריבן ניט בלשון הקודש, נאר בלשון המורגל בפי העם (כולל נשים וטף) דזמן ההוא, וואס דאס באווייזט אז דאס איז שייך אויך צו אידן וואס פארשטייען נאך ניט קיין לשון הקודש, כולל אויך די וואס קענען נאך ניט לערנען ספר ״יד החזקה״ (וועלכן ער האט געשריבן בלשון הקודש).\nהאט מען עפ״ז אן עצה אז אלע, כולכם — זאלן זיך קענען משתתף זיין אין דעם לימוד דספר הרמב״ם:\nדי וואס זיינען נאך ניט שייך צו לימוד יד החזקה — זאלן לערנען בכל יום אין ספר המצוות להרמב״ם [וואס איז אויך איבערגעזעצט געווארן בלשון הקודש, ע״י ר׳ משה בן ר׳ שמואל אבן תיבון⁴²] — די מצוות וואס זיינען מקביל (פארא־לעל) צו די הלכות (ומצוות) וואס דער סוג הראשון לערנט (דריי פרקים א טאג) בספר יד החזקה, וועט עס זיין מעין קיצור פון דער אריכות והרחבה שבספר היד.\nובד׳ ימים הראשונים (אנהויבנדיק פון ז״ך ניסן) ווען מ׳לערנט די הקדמה כו׳ לספר היד, זאל מען לערנען: ביום א׳ — א חלק פון דער הקדמה לסהמ״צ, און ביום ב״ד — א חלק פון די י״ד שרשים, כל או״א לפום שיעורא דילי׳.\nובהימים ווען אין דעם שיעור אין ספר היד זיינען פאראן ווייניק מצוות — זאל מען איבער׳חזר׳ן (חלקים פון) דעם שיעור בספר המצוות המקביל לס׳ היד⁴³; און נוסף ע״ז משלים זיין (במשך כמה ימים) דעם לימוד אין די י״ד שרשים.\nומובן, אז דער לימוד בסהמ״צ איז שייך צו אלעמען, אויך צו קטנים בידיעות, און קטנים בשנים, נאר די מורים ומדריכים דארפן זיך משתדל זיין דאס צו מסביר זיין לפי ערכם וכו׳.\nאון דורך דעם וועט מען האבן די אחדות פון כל ישראל, כולכם — ״בנערינו ובזקנינו גו׳ בבנינו ובבנותינו״ אין לימוד פון דעם זעלבן ענין בתורה",[["41","41","אבות ספ״ה."],["42","42","ראה תשובת הרמב״ם לאביו דר׳ משה — ר׳ שמואל אבן תיבון (מתרגם ה״מורה נבוכים״) — חלקה נדפס בהקדמת קאפח להוצאתו דמו״נ."],["43","43","ועי״ז ההשתתפות בסדר לימוד הי״ד — כנ״ל בפנים."]]],[1300271249,"(בכללות הענין ובמקורו בתושב״כ — תורת משה) בכל יום.\nז. בהאמור לעיל וועגן השתתפות הנשים בלימוד הנ״ל — יש להעיר, אז אויך בא זיי זיינען שייך די צוויי טעמים דלעיל:\nא) די מעלה פון אחדות ישראל: נשים זיינען מחוייב במצות ״ואהבת לרעך כמוך״⁴⁴ — כאנשים.\nב) ידוע הפס״ד⁴⁵ אז אויך נשים זיינען מחוייב בלימוד התורה ב״הלכות הצריכות להן וכל מ״ע שאין הזמן גרמא וכל מצות לא תעשה כו׳״. און, וויבאלד אז ״אחכה לו בכל יום שיבוא״ — יש לומר, אז דאס איז אויך כולל א חלק פון די הלכות קרבנות וקדשים (אין רמב״ם), הלכות קרבנות וואס נשים וועלן זיין מחוייב צו ברענגען, אויך קרבן פסח וכיו״ב.\nאון אויך אויב זיי לערנען שאר ההלכות וועלכע זיי האבן ניט קיין חיוב לערנען, באקומען זיי דערפאר שכר⁴⁶,\nועפ״י הפס״ד⁴⁷ אז נשים מקיימות ומברכות על מ״ע שפטורות מהן, און אזוי פירן זיך אלע נשים במצוות מסויימות (שופר וכו׳) — קענען זיי מאכן ברכת התורה על לימוד הלכות שאינן צריכות להן⁴⁸, במכ״ש וק״ו מברכת המצוות האלו, ווייל: (א) תלמוד תורה כנגד כולן⁴⁹, (ב) במתן תורה איז אמירת משה לנשים געווען פאר דיבורו עם האנשים⁵⁰.\nועוד להעיר:\nלכאורה צ״ע ממחז״ל אז המלמדה תורה שבעל פה כאילו מלמדה כו׳⁵¹ — אבער מבואר הוא על אתר ע״פ הטעם ״מפני שעי״ז נכנס בה ערמומיות״, און בלימוד הלכות פסוקות בלי טעמיהן — וואס דאס איז סגנון ס׳ היד וסהמ״צ (כהדגשת הרמב״ם) — איז דאס כלל ניט שייך, והוי בנדו״ד — כדין תושב״כ.\nובדורות האחרונים — פס״ד כל גדולי ישראל אז עת לעשות להוי׳ כו׳, און מ׳האט געטאן א מעשה בפועל און מ׳האט מייסד געווען בתי־ספר פאר בנות ללמדן תושב״כ והלכות הצריכות (כולל — ידיעת השם ואהבתו ויראתו כו׳, דעות ישרות, תשובה — תוכן ספר המדע שביד).\nויתרה מזו — מעשה רב בהסכמת גדולי ישראל אז נשים מלמדות בבתי״ס לבנים קטנים כולל הל׳ ציצית⁵² וכיו״ב.\nח. לויט די אויבנגעזאגטע טעמים אויף דעם ענין — אחדות ישראל, און חיוב דכאו״א צו לערנען כל הלכות שבתורה — איז מובן ופשוט אז מ׳דארף זיך משתדל זיין אז וואס מערער אידן",[["44","44","קדושים יט, יח. יד ל׳ דעות פ״ו ה״ג. סהמ״צ מ״ע רו."],["45","45","הל׳ ת״ת לאדה״ז ספ״א. וש״נ."],["46","46","הל׳ ת״ת שם. הל׳ ת״ת להרמב״ם ספ״א."],["47","47","שו״ע אדה״ז חאו״ח סי״ז ס״ג. וש״נ."],["48","48","ראה שו״ע אדה״ז (חאו״ח סו״ס מז): ״נשים מברכות ברכת התורה שהרי חייבות ללמוד מצוות שלהן״ — שאז חייבות הן בברכת התורה (מפני שחייבות ללמוד מצוות שלהן). ואין זה תלוי ברצונן, משא״כ בשאר הלכות התורה — הרי לימוד זה תלוי ברצונן, וכשלומדות — מברכות ברכת התורה (כבפנים)."],["49","49","פאה פ״א מ״א."],["50","50","מכילתא — הובא בפרש״י — עה״פ יתרו יט, ג. וראה שיחת כ״ק מו״ח אדמו״ר לנשי ובנות ישראל בעת ביקורו בריגא י״ב־כ׳ אדר תרצ״ד (נדפסה בלקו״ד כרך ג בסופו — תקעא, ב ואילך)."],["51","51","הל׳ ת״ת לאדה״ז ספ״א (מסוטה כ, א — במשנה. הל׳ ת״ת להרמב״ם ספ״א)."],["52","52","ראה שו״ע אדה״ז או״ח סי״ז ס״ג בסופו."]]],[1300271250,"— אנשים נשים וטף — זאלן זיך משתתף זיין אין לערנען דעם רמב״ם בא׳ מהאופנים הנ״ל, ובמיוחד — מצד אחדות ישראל.\nובפרט בימים אלה, די לעצטע טעג פון גלות — ווען ס׳איז במיוחד נוגע אהבת ואחדות ישראל, בכדי לגמרי מבטל זיין סיבת הגלות — דעם היפך פון אהבת ישראל⁵³.\nולהעיר ולהציע — אז די וועלכע וועלן וועגן דעם אלעם הערן שפעטער (נאך דעם וואס מ׳וועט שוין אנהויבן לערנען די שיעורים) — זאלן זיי דעמולט אנהויבן לערנען דעם שיעור פון יענעם טאג ואילך על הסדר דכל הלומדים, בכדי מאחד זיין כל הלומדים⁵⁴, און בזמן המתאים משלים זיין די פריערדיקע שיעורים.\nט. ויהי״ר אז די הצעה זאל נתקבל ווערן בא יעדן אידן און ביי אלע אידן.\nאון דער לימוד בספר הרמב״ם, ביז סיומו — און נאכמער: שוין די החלטה טובה בזה⁵⁵, זאל נאכמער ממהר זיין קיום היעוד מיט וועלכן דער רמב״ם איז מסיים וחותם⁵⁶ הל׳ מלכים ומלחמותיהם⁵⁷ און כל ספרו ״יד החזקה״: ״ולא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד, ולפיכך יהיו ישראל חכמים גדולים ויודעים דברים הסתומים וישיגו דעת בוראם כפי כח האדם, שנאמר⁵⁸ כי מלאה הארץ דעה את ה׳ כמים לים מכסים״.",[["53","53","יומא ט, ב."],["54","54","הדין דחובה, קודם לתשלומין (שו״ע או״ח ר״ס קח) — לכאורה אין שייך בנדו״ד, כיון שבלימוד ספר הי״ד נוגע הקדימה והאיחור, כנ״ל הערה 27."],["55","55","ע״ד הפס״ד בשו״ע או״ח סתקע״א ס״ג."],["56","56","ואמחז״ל הכל הולך אחר החיתום (ברכות יב, א)."],["57","57","השם המלא דהלכות אלו — כבהקדמת הרמב״ם (ב״מנין המצות על סדר הלכות הרמב״ם״) ובהכותרת בספר שופטים והל׳ מלכים. ולהעיר דבהכותרת לפרקים יא ויב דהל׳ מלכים בדפוס ויניציאה רפד, שי — ״הלכות מלכים ומלחמות ומלך המשיח״."],["58","58","ישעי׳ יא, ט. — ולהעיר: ע״פ מו״נ (ח״ג ספי״א) כתוב זה הוא טעם דהתחלת הלכה זו שבאותו הזמן לא יהי׳ מלחמה וכו׳, כפשוטו של מקרא: לא ירעו גו׳ כי מלאה הארץ דעה גו׳. — אבל ראה הל׳ תשובה פ״ט ה״ב. ואכ״מ."]]],[1300271251,"הדרן על ספר משנה תורה להרמב״ם משיחות י״א ניסן* ואחש״פ תשמ״ה\nא. בהלכה האחרונה של ספר היד כותב הרמב״ם, וז״ל: „ובאותו הזמן לא יהי׳ שם לא רעב ולא מלחמה ולא קנאה ותחרות שהטובה תהי׳ מושפעת הרבה וכל המעדנים מצויין כעפר, ולא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״.\nוהנה ידוע שלשון הרמב״ם מדויק הוא בתכלית¹. ובלשון ודברי הרמב״ם עצמו² (בהקדמתו לספר היד) שחיבורו זה נכתב „בלשון ברורה ודרך קצרה״. ומזה מובן, שאריכות לשון הרמב״ם — „שהטובה תהי׳ מושפעת הרבה וכל המעדנים מצויין כעפר״ — היא לא כפל לשון³ (ליופי המליצה וכיו״ב), כ״א מלמדנו שני ענינים שיהיו באותו הזמן.\nויש לומר הביאור בזה⁴ ובהקדם:\nממ״ש הרמב״ם „שהטובה תהי׳ כו׳״ (לא — „והטובה כו׳״) מוכח שכוונתו נתינת טעם על הקודמו, דהסיבה לזה ש„לא יהי׳ שם לא רעב כו׳״ הוא מפני „שהטובה תהי׳ מושפעת כו׳״.\nויש לומר, שב׳ הענינים בהטעם —\n(א) שהטובה תהי׳ מושפעת הרבה, (ב) וכל המעדנים מצויין כעפר — הם כנגד ב׳ הענינים שמונה לפנ״ז (א) לא יהי׳ שם לא רעב ולא מלחמה (ב) ולא קנאה ותחרות:\nזה „שהטובה תהי׳ מושפעת הרבה״ שולל מציאות של רעב ומלחמה — כי אז הרי יש לכל אדם טובה הרבה ואין צורך במלחמה לשלול שלל וכו׳ להוסיף ברכושו ונכסיו:\nאמנם עדיין אין זה שולל הרגש של „קנאה ותחרות״ — כי ידמה במחשבתו שאפשר יש לחברו „טובה״ שאין יודע אודותה וכיו״ב, שזה לא יביאו לידי „מלחמה״ (כיון שאינו יודע מה לשלול לעצמו) אבל מרגיש הוא „קנאה ותחרות״.\nולכן מוסיף הרמב״ם „וכל המעדנים מצויין כעפר״, שחשיבות של כל המעדנים תהי׳ „כעפר״, דהיינו (כמ״ש הרמב״ם בנוגע להשבתת חמץ⁵) „כדבר שאין בו צורך כלל״.\nומכיון שכל המעדנים הם אצלו „כדבר שאין בו צורך כלל״, שוב לא שייך שום רגש של „קנאה ותחרות״ (בקשר למעדנים⁶ — ענינים גשמיים)⁷.",[["","","*) בחגיגת סיום מחזור הראשון של לימוד ס׳ משנה תורה להרמב״ם כפי שנחלק ללמוד ג׳ פרקים ליום."],["1","1","יד מלאכי כללי הרמב״ם אות ג. ועוד."],["2","2","וראה הל׳ דעות פ״ב ה״ד: בד״ת . . יהיו דברי האדם מעטים ועניניהם מרובים . . אם היו הדברים מרובין והענין מועט ה״ז סכלות."],["3","3","וכפל הלשון „קנאה ותחרות״ — כי „קנאה״ היא הרגש שבלב, המביא לידי „תחרות״ (בפועל)."],["4","4","ראה ג״כ (ובכמה ענינים דלקמן) ה„הדרן״ על ס׳ משנה תורה (קה״ת, ברוקלין, י״א ניסן תשמ״ה) — וכמה פרטים נתבארו שם באו״א."],["5","5","הל׳ חמץ ומצה פ״ב ה״ב."],["6","6","משא״כ ה„טובה״ (סתם) אינה „כעפר״ (שאין בו צורך כלל) — כי גם בימות המשיח יהי׳ צורך בדברים גשמיים כדי שיהי׳ הגוף בריא ושלם שמדרכי (עבודת) השם הוא (רמב״ם הל׳ דעות רפ״ד. וכדלקמן בפנים סעיף ד)."],["7","7","ועפ״ז מובן בפשטות זה שהרמב״ם לא הביא שני ענינים אלו („לא קנאה ותחרות״, „וכל המעדנים"]]],[1300271252,"ב. אמנם, עדיין צריך להבין האריכות בהמשך לשון הרמב״ם „ולא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״:\nיתור לשון זה — „לא . . אלא״ (ולא כתב בקיצור: עסק כל העולם יהי׳ לדעת את ה׳ בלבד) — מורה, כידוע, על שלילה נוספת (גם לעיכובא⁸). ולכאורה:\nלאחרי כתבו שבאותו הזמן (לא רק „שהטובה תהי׳ מושפעת הרבה״, כ״א עוד זאת) „וכל המעדנים מצויין (חשובין) כעפר״, „כדבר שאין בו צורך כלל״ — שלכן אין שייך שום רגש של „קנאה ותחרות״, הרי ישנה רק האפשריות דעסק בענינים שאינם בסוג של „כל המעדנים״ — ומהי השלילה הנוספת שמרמזה הרמב״ם ביתור לשונו „לא יהי׳ עסק כל העולם אלא לדעת כו׳״?\nויתירה מזו: לא הסתפק הרמב״ם באריכות לשונו זו, אלא מוסיף „(אלא לדעת את ה׳) בלבד״. שמזה משמע, דגם לאחרי שידעינן ש„לא יהי׳ עסק כל העולם אלא לדעת את ה׳״, עדיין לא נשלל הכל, ולזה מוסיף הרמב״ם עוד מיעוט „בלבד״.\nג. וממשיך הרמב״ם בסיום וחותם ההלכה (וספר היד): ולפיכך יהיו ישראל חכמים גדולים ויודעים דברים הסתומים וישיגו דעת בוראם כפי כח האדם שנאמר⁹ כי מלאה הארץ דעה את ה׳ כמים לים מכסים.\nוגם בזה כמה דיוקים, ומהם:\nא) „דברים הסתומים״ — מה הם ה„דברים הסתומים״, ולמה לא פירש הרמב״ם לאיזה „דברים״ הכוונה?\nב) „כפי כח האדם״ — מאי קמ״ל? פשיטא שהאדם יכול להשיג רק כפי כחו ולא יותר, ובפרט כשהמדובר אודות „דעת בוראם״?\nג) מדוע מעתיק הרמב״ם גם סיום הפסוק „כמים לים מכסים״. ובפרט שבהלכות תשובה, שגם שם¹⁰ מתאר הרמב״ם איך ש„באותן הימים תרבה הדעה והחכמה כו׳״ ומביא אותו הפסוק „כי מלאה הארץ גו׳״, לא הביא סיום הכתוב „כמים לים מכסים״.\nד. וי״ל נקודת הביאור בכל זה:\nבלשונו „לא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״ שולל הרמב״ם (לא רק „עסק״ שאינו „עבודה למקום ב״ה״¹¹, כ״א) גם עסק כזה שבזמן הזה (לפני „אותו הזמן״) מחוייבים בו ע״פ תורה והוא ענין של „עבודה למקום ב״ה״ — אבל מחמת השינוי שיהי׳ בעולם „באותו הזמן״, שוב לא יהי׳ צורך בעבודה זו, ובמילא „לא יהי׳ עסק כל העולם (אפילו לא בעבודת ה׳ אחרת) אלא לדעת את ה׳ בלבד״.\nוהביאור:\nהלכה זו באה בהמשך למ״ש הרמב״ם בהלכה שלפנ״ז שבימות המשיח יהיו",[["","","מצויין כעפר״) בהל׳ תשובה פ״ט ה״א — כי בהל׳ תשובה מדובר בהזמן שלפני ימות המשיח, שמציאות העולם עדיין אינה בשלימות, ואין העולם במצב כזה ש„כל המעדנים מצויין (חשובין) כעפר״, ובמילא שייך „קנאה ותחרות״."],["8","8","ראה תוד״ה מתני׳ — מנחות פג, סע״ב."],["9","9","ישעי׳ יא, ט."],["10","10","פ״ט ה״ב."],["11","11","לשון הרמב״ם הל׳ דעות ספ״ג, כדלקמן בפנים."]]],[1300271253,"ישראל „פנויין בתורה וחכמתה״, ובלשון ההלכה¹² — „תורתם אומנתם״.\nוהנה בזמן הזה, גם מי שתורתו אומנתו, פסק הרמב״ם¹³ ד„כל המשים על לבו שיעסוק בתורה ולא יעשה מלאכה ויתפרנס מן הצדקה ה״ז חלל את השם כו׳״, וצריך לעשות „מלאכה בכל יום מעט כדי חייו״¹⁴. וכמו ש„צוו¹⁵ חכמים הוי ממעט בעסק״, שמזה מובן שמיעוט עסק — כן צריך להיות.\nאלא שכיון שהמדובר במי שתורתו אומנתו, הרי עסקו במשא ומתן הוא רק (כמ״ש הרמב״ם¹⁶) בשביל „שיהא גופו שלם וחזק כדי שתהי׳ נפשו ישרה לדעת את ה׳״, שלכן המשא ומתן גופא נעשה „עבודה למקום ב״ה״, הוא „עובד את ה׳ תמיד אפילו בשעה שנושא ונותן . . כל מעשיך יהיו לשם שמים . . בכל דרכיך דעהו״.\nאמנם כל זה הוא בזמן הזה. אבל „באותו הזמן״, שאז „הטובה תהי׳ מושפעת הרבה״, הרי לא יהי׳ צורך אפילו במיעוט עסק¹⁷ (גם לא באופן שהמשא ומתן עצמו הוא „עבודה למקום ב״ה״), ולכן — „לא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״¹⁸.\nה. עפ״ז יש לבאר ג״כ הוספת הרמב״ם תיבת „בלבד״ — אלא לדעת את ה׳ בלבד — שהיא שלילה נוספת, ב„לדעת את ה׳״ גופא. כלומר: לא זו בלבד שלא יהי׳ שום עסק אחר (גם כשהוא „עבודה למקום ב״ה״) מלבד העסק „לדעת את ה׳״, אלא עוד זאת, שהעסק ב„לדעת את ה׳״ עצמו יהי׳ באופן ד„לדעת את ה׳ בלבד״. היינו: לא לדעת בשביל מטרה אחרת — גם מטרה קדושה (כמו: לידע את המעשה אשר יעשון ואלה אשר לא תיעשנה) — כ״א אך ורק לשם ידיעת והשגת התורה בלבד, לימוד התורה לשמה — לשם התורה עצמה¹⁹.\n[ע״ד ביאור הרמב״ם²⁰ בעבודת ה׳ לשמה (מאהבה²¹) — שזהו רק כ„שעושה האמת מפני שהוא אמת״, ולא בשביל איזו תכלית אחרת, גם לא דקדושה כמו „שאזכה לחיי העולם הבא״, אף שע״פ ביאור הרמב״ם עצמו²² הרי עולם הבא הוא „סוף מתן שכרן של מצות״, וזה שאנו עוסקים בתורה ובמצות בעולם הזה הוא „כדי²³ שנזכה לחיי העולם הבא״].",[["12","12","שבת יא, א. רמב״ם הל׳ תפלה פ״ו ה״ח."],["13","13","הל׳ ת״ת פ״ג ה״י. וידועה השקו״ט בזה (ראה כס״מ שם. ועוד). ואכ״מ."],["14","14","רמב״ם שם ה״ט. ולהעיר מרדב״ז סוף הל׳ שמיטה ויובל."],["15","15","ל׳ הרמב״ם שם סה״ח."],["16","16","הל׳ דעות ספ״ג."],["17","17","ראה פיה״מ להרמב״ם סנהדרין בהקדמתו לפ׳ חלק (ד״ה ועתה אחל) „באותם הימים יהי׳ נקל מאד על בני האדם למצוא מחייתם עד שבעמל מעט כו׳״."],["18","18","ועפ״ז מובן השינוי: בהל׳ תשובה שם ה״א הלשון „וישפיע לנו כל הטובות כו׳ כדי שלא נעסוק כל ימינו בדברים שהגוף צריך להן כו׳״ — דשולל רק „כל ימינו״, כי צ״ל מיעוט עסק (כנ״ל בפנים): משא״כ לעת״ל „לא יהי׳ עסק כו׳ אלא לדעת את ה׳ בלבד״ (וזה שתהי׳ אכו״ש ו„עמל מעט״ למצוא מחייתם — לא יהי׳ באופן של „עסק״, ביגיעה והשתדלות)."],["19","19","ראה בארוכה בזה לקו״ש חי״ז ע׳ 402 ואילך (וראה הנסמן שם הערה 9)."],["20","20","הל׳ תשובה פ״י ה״ב. וראה ג״כ פיה״מ להרמב״ם סנה׳ שם ד״ה וכת חמישית (ושם: ולא תהי׳ אצלו תכלית למוד החכמה אלא לדעת אותה בלבד. אלא שאח״כ ממשיך „וכן אין תכלית האמת כו׳ ותכלית ידיעתה לעשותה״. ואכ״מ)."],["21","21","ראה שם ה״ה."],["22","22","שם פ״ט בארוכה."],["23","23","ל׳ הרמב״ם שם. וכ״ה בהל׳ מלכים כאן (פי״ב סה״ד). וראה פיה״מ סנה׳ שם (ד״ה „ועתה אחל״"]]],[1300271254,"כי מאחר שבני ישראל יהיו „פנויין בתורה וחכמתה״ — תורתם אומנתם — יקיימו אז מצות ת״ת בשלימותה; ושלימות הענין דת״ת היא כאשר הלימוד הוא לא בשביל איזו תכלית אחרת כ״א רק בשביל ידיעת והשגת התורה עצמה,\n[וזה גופא (זה שלומד תורה רק בשביל ידיעת והשגת התורה) מביאו לידי זה שאינו עוסק בשום ענין אחר חוץ מלימוד התורה, כי דוקא עי״ז מתקשר ומתאחד עם התורה (בסגנון הרמב״ם²⁴: אין . . נקשרת בלבו של אדם עד שישגה בה תמיד), וכדלקמן סעיף ט ואילך].\n— ואף שגם אז יהי׳ קיום המצות (כי מצות בטילות רק לתחיית המתים²⁵) ובמילא צריכים ללמוד כדי לידע את המעשה אשר יעשון כו׳ — הנה לזה מספיק שילמוד פעם אחת כל התורה כולה, היינו כל ההלכות של תורה שבע״פ²⁶ (וכמ״ש אדה״ז בהל׳ ת״ת²⁷ ש„אפשר ללמוד כל התורה שבע״פ כולה . . כי באמת ההלכות הנגלות לנו ולבנינו יש להן קץ ותכלית ומספר״), ושוב לא יצטרכו לעסוק בלימוד זה²⁸ (כי בימות המשיח, כאשר „רוח הטומאה אעביר מן הארץ״²⁹, אין שכחה³⁰),\nובמילא — „לא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״, היינו העיון ב„עומק טעמי ההלכות והפלפול בטעמיהן כו׳״³¹, עד — הלימוד באופן ד„יגדיל תורה ויאדיר״³², „דרוש וקבל שכר״³³.\n[ובזה יומתק דיוק לשון הרמב״ם „עסק כל העולם . . לדעת כו׳״ — כי הלשון „עסק״ (בשייכות לתורה) מורה על הטורח והיגיעה³⁴ בתורה, ב„משא ומתן של פלפול״³⁵. ובפרט באופן שמחדש בתורה, עד שפועל „ההגדלה״ (והוספה) בתורה — „יגדיל תורה ויאדיר״ — וכמחז״ל³⁶ שענינו של עסק הוא כאשר מרויח, כי „זבון וזבין תגרא איקרי (בתמי׳)״].\nו. עפ״ז יובנו גם דיוקי לשונות הרמב״ם בסיום ההלכה, ועל הסדר:\nא) „ולפיכך יהיו ישראל חכמים גדולים״ — לא סתם חכמים, כ״א גדלות בחכמה, לימוד באופן ד„יגדיל תורה ויאדיר״.\nב) „יודעים דברים הסתומים״ — „דברים הסתומים״ שבתורה (שה״ז המשך (כנ״ל) לדבריו בהלכה הקודמת „פנויין בתורה וחכמתה״), שהם „עומק טעמי ההלכות והפלפול בטעמיהן כו׳״",[["","","קרוב לסופו): ואם היותו (עוה״ב) הוא התכלית המבוקש אינו ראוי . . שיהי׳ עובד להשיג העוה״ב כו׳. ע״ש. — וראה ה„הדרן״ על מס׳ אבות (נדפס בסו״ס „ביאורים לפרקי אבות״) הערה 80. לקו״ש שלח תשמ״ז ס״ד ואילך."],["24","24","הל׳ תשובה ספ״י (ושם ה״ג) — לענין אהבה. וראה רמב״ם סוף הל׳ איסורי ביאה."],["25","25","אגה״ק סכ״ו (קמה, סע״א ואילך)."],["26","26","ראה הרמב״ם בהקדמתו לס׳ היד שבספרו זה „מקבץ לתורה שבעל פה כולה״. וראה הל׳ ת״ת לאדה״ז פ״א ס״ה. שם רפ״ג (אלא שלשיטת אדה״ז צ״ל גם עם הטעמים „בדרך קצרה״ (הל׳ ת״ת פ״ב ס״א. פ״ג שם), משא״כ לשיטת הרמב״ם — ראה אדה״ז קו״א לרפ״ב שם). וראה לעיל ע׳ 230 ואילך."],["27","27","פ״א שם."],["28","28","וראה לקו״ש חכ״ה ע׳ 263 (ס״ז)."],["29","29","זכרי׳ יג, ב."],["30","30","ראה הל׳ ת״ת לאדה״ז פ״ב סוס״י."],["31","31","ל׳ אדה״ז — הל׳ ת״ת פ״א שם."],["32","32","ישעי׳ מב, כא. חולין סו, ב."],["33","33","סוטה מד, א. וש״נ."],["34","34","ב״ח לטואר״ח סמ״ז ד״ה ונוסחא. ט״ז או״ח שם סק״א."],["35","35","ל׳ הט״ז שם."],["36","36","ב״מ מ, ב."]]],[1300271255,"(שאין לזה קץ ותכלית²⁷), והם „דברים הסתומים״ („הנסתרות לה׳ אלקינו״³⁷) בערך להלכות עצמן שהם (כנ״ל מאדה״ז) „הנגלות לנו ולבנינו״.\nג) אח״כ מפרט הרמב״ם סוג נעלה יותר ב„דברים הסתומים״ שבתורה — „וישיגו דעת בוראם״, ההשגה בעניני מעשה מרכבה³⁸ עד להשגת „דעת בוראם״, שהיא סתום מהנברא, כמו שהאריך הרמב״ם בהלכות יסודי התורה³⁹ שאי אפשר לאדם להשיג אמתת המצאו של הבורא. וכן בנוגע לדעתו⁴⁰.\nד) כפי כח האדם — יש לומר, שכוונת הרמב״ם היא [לא (רק) להגביל השגת האדם בזמן ההוא שהיא רק „כפי כח האדם״ (כי, כנ״ל, מאי קמ״ל) — אלא להיפך]: דמכיון ש„לא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״, לכן תהי׳ ההשגה בשלימותה, „כפי כח האדם״ — כלומר: כדבעי⁴¹ — ככל יכלתו של האדם.\nולכל זה מביא הרמב״ם ראי׳ מתורה שבכתב — „שנאמר כי מלאה הארץ דעה את ה׳ כמים לים מכסים״: מכיון שהארץ תהי׳ מלאה ב„דעה את ה׳״, הרי שוב אין מקום לאיזה עסק וענין אחר (דאל״כ לא שייך לומר ע״ז „מלאה״), ומזה — ד„לא יהי׳ עסק כל העולם (הארץ⁴²) אלא לדעת את ה׳ בלבד״.\nז. עפ״ז מובנת ג״כ הוספת הרמב״ם כאן „כמים לים מכסים״:\nמאחר שאין שום עסק אחר כ״א „לדעת את ה׳ בלבד״, והיינו ש„דעה את ה׳״ תהי׳ באופן של עסק⁴³, ועסק היחידי, לכן, נוסף על שהאדם מלא מ„דעה את ה׳״\n— שזה אפשרי גם כשהם שני דברים: האדם וענין שני — „דעה את ה׳״ — וכידועה הדוגמא: דגים ומי הים, שהמים הם חיות הדגים ובכ״ז הם שני דברים (ועד שלדעת חכמים⁴⁴ — דגים חוצצין) —\nכ״א שה„דעה״ נעשית כל מציאותו, בפועל ובגלוי,\nוזה „כמים לים מכסים״, דנוסף על שהארץ תהי׳ מלאה מ„דעה את ה׳״ עוד זאת שיהי׳ באופן ד„כמים לים מכסים״. דכמו שאין רואים קרקעית הים ולא כל הברואים שבים, כ״א רק המים המכסים על הכל — כמו כן לא יהי׳ נראה שום מציאות אחרת בארץ, כ״א רק הענין ד„דעה את ה׳״.\nויומתק בפרט ע״פ דעת רשב״ג⁴⁵ דכל שהוא מבריית המים אינו חוצץ, והיינו דמכיון שברואי הים נבראו מן המים⁴⁶,",[["37","37","ל׳ הכתוב — נצבים כט, כח."],["38","38","ראה בארוכה בזה לקו״ש חכ״ו ע׳ 117 ואילך."],["39","39","פ״א ה״ט ואילך. ועוד."],["40","40","ראה רמב״ם הל׳ יסוה״ת ספ״ב. הל׳ תשובה ספ״ה — הובאו בשער היחוה״א פ״ז (אלא ששם עיקר הכוונה לידיעת דברים ולא לשכל והבנה — משא״כ בשער היחוה״א פ״ח)."],["41","41","ראה כתובות סז, רע״א."],["42","42","ראה לקמן סעיף יג־יד."],["43","43","ראה לקו״ש שבהערה 19. וש״נ."],["44","44","ת״ק במשנה מקואות וידים שבהערה הבאה (ראה מפרשים שם)."],["45","45","מקואות פ״ו מ״ז. ידים פ״ב מ״ב. — אלא שאין הלכה כמותו (נת׳ בד״ה וראיתי אני, תרס״ב) — אבל הרי פסקינן כוותי׳ בהא דזבחים (כב, א). וכבר שקו״ט בזה בתוי״ט מקואות שם. והאריך בזה בס׳ גולות עליות שם. חיבור לטהרה הל׳ מקואות כלל ב׳ בסופו (לפענ״ד בשנויא דחיקא). ועוד, ואכ״מ."],["46","46","ראה חולין כז, ב."]]],[1300271256,"הרי אמיתית מציאותם היא המים, ולכן אינם חוצצים בפני המים.\nועפ״ז נמצא, דזה שמי הים מכסים על הברואים שבתוכו, הרי באמיתית הענין, אין זה כיסוי של הסתר, כ״א אדרבא „גילוי״ ה„סתום״ — כי המים הרי הם אמיתית המציאות של ברואי הים (המכוסים בהמים).\nוככה הוא בנמשל, דמכיון ש„לא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״, הרי ה„לדעת את ה׳״ נעשית מציאותו האמיתית של „כל העולם״⁴⁷. ולכן, זה שלעתיד „יראה״ רק הענין ד„דעה את ה׳״ הוא לא ביטול מציאותו של „כל העולם״, כ״א אדרבה — זהו מה שתתגלה אז מציאותו האמיתית ד„כל העולם״ — „דעה את ה׳״⁴⁸.\n* * *\nח. שלימות זו בעסק „התורה וחכמתה״ שתהי׳ בימות המשיח (בכל פרטי׳ המבוארים בלשונות הרמב״ם, כנ״ל בארוכה) — תובן יותר, ע״פ ביאור הרמב״ם בהל׳ תלמוד תורה שלו, אודות קיום מצות ת״ת בשלימות, ובלשון הרמב״ם שם⁴⁹ — „מי שנשאו לבו לקיים מצוה זו כראוי ולהיות מוכתר בכתר תורה כו׳״ (היינו, שקיום מצוה זו כראוי הוא כשהאדם מוכתר בכתר תורה). שמזה מובן, ששלימות זו שתהי׳ בימות המשיח, ענינה שבני ישראל יהיו מוכתרין בכתר תורה.\nועפ״ז יש לומר, שפרטי לשונות הרמב״ם שבסיום וחותם הספר אודות אופן העסק ב„לדעת את ה׳״, הם בהתאם להפרטים המבוארים בהרמב״ם (הל׳ ת״ת) בביאור אופן קיום „מצוה זו כראוי ולהיות מוכתר בכתר תורה״.\nוז״ל הרמב״ם בהלכות ת״ת רפ״ג:\nבשלשה כתרים נכתרו ישראל כתר תורה וכתר כהונה וכתר מלכות. כתר כהונה זכה בו אהרן . . כתר מלכות זכה בו דוד . . כתר תורה הרי מונח ועומד ומוכן לכל ישראל . . כל מי שירצה יבא ויטול. שמא תאמר שאותם הכתרים גדולים מכתר תורה הרי הוא אומר . . הא למדת שכתר תורה גדול משניהם.\nוהנה בכסף משנה מציין המקור למס׳ יומא⁵⁰, אבל שם לא נאמר הלשון „שלשה כתרים . . כתר תורה וכתר כהונה וכתר מלכות״, כ״א „שלשה זירים הן, של מזבח ושל ארון ושל שלחן, של מזבח זכה אהרן ונטלו, של שלחן זכה דוד ונטלו, של ארון עדיין מונח הוא כל הרוצה ליקח יבוא ויקח שמא תאמר פחות הוא ת״ל כו׳״.\nוכן — עוד כמה שינויים ברמב״ם לגבי ל׳ הש״ס.\nולכן נראה לפענ״ד כדעת המפרשים (כמשנ״ת במק״א⁵¹ בארוכה) שמקור הרמב״ם הוא מספרי⁵², שכללות הלשון שם קרוב יותר⁵³ ללשון הרמב״ם.",[["47","47","ראה לקמן סעיף יד."],["48","48","וזה גופא הטעם למ״ש הרמב״ם בתחילת ההלכה ש„באותו הזמן לא יהי׳ . . קנאה ותחרות . . (מפני ש)וכל המעדנים מצויין (חשובין) כעפר״ (כנ״ל סעיף א) — כי מכיון שתתגלה אז שמציאותה האמיתית של הארץ היא „דעה את ה׳״, הרי מובן שאין שום חשיבות למעדנים."],["49","49","הל׳ ת״ת פ״ג ה״ו."],["50","50","עב, ב."],["51","51","לקו״ש חכ״ח ע׳ 105 ואילך."],["52","52","קרח יח, יט־כ. — ועד״ז באבות פ״ד מי״ג. וראה אדר״נ רפמ״א (צויין בהגהמ״י על אתר)."],["53","53","אף שגם בזה שינויים (ראה בארוכה לקו״ש שם)."]]],[1300271257,"אלא שצ״ע: מדוע בחר הרמב״ם ב(לשון) הספרי ולא בהש״ס הנ״ל?\nויש לומר נקודת הביאור⁵⁴: ספר משנה תורה הוא ספר „הלכות הלכות״⁵⁵. שמזה מובן, שכוונת הרמב״ם בהביאו מחז״ל ד„שלשה כתרים כו׳״ היא לא רק כדי להדגיש המעלה והגדלות שבתורה (ואפילו גם לגבי כהונה ומלכות), כ״א משום שזהו נוגע להלכה.\nועפ״ז יש לבאר מה שהרמב״ם בוחר ב(לשון) הספרי „שלשה כתרים״, ולא ב(לשון הש״ס) „שלשה זירים״ — כי הנפק״מ להלכה מהענין ד„כתר תורה״ מודגשת יותר בהלשון „כתרים״, „כתר תורה״ (כדלקמן סעיף יא).\nט. ה„הלכה״ בקשר להענין ד„כתר תורה״ מבוארת היא ברמב״ם בהמשך הפרק, שבו מזכיר שלשה תנאים הנצרכים כדי „להיות מוכתר בכתר תורה״:\n(א) „לא יסיח דעתו לדברים אחרים ולא ישים על לבו שיקנה תורה עם העושר והכבוד כאחת״⁵⁶. (ב) שמא תאמר עד שאקבץ ממון אחזור ואקרא עד שאקנה מה שאני צריך ואפנה מעסקי אחזור ואקרא, אם תעלה מחשבה זו על לבך אין אתה זוכה לכתרה של תורה לעולם⁵⁷. (ג) מי שרצה לזכות בכתר התורה יזהר בכל לילותיו ולא יאבד אפילו אחד מהן בשינה ואכילה כו׳ אלא בתלמוד תורה ודברי חכמה⁵⁸.\nוצריך ביאור: בפרק זה מונה הרמב״ם עוד כו״כ תנאים הנצרכים כדי שדברי תורה יהיו „מצויים וקיימים״ אצל האדם — כמו: לא בגסי הרוח היא מצוי׳ כו׳⁵⁹; האדם צריך להסיר „התאוות ותענוגי הזמן מלבו״⁶⁰; אין ד״ת מתקיימין במי שמרפה עצמו עליהן⁶¹; כל המשמיע קולו כו׳⁶¹ — ובכל אלו לא הזכיר הרמב״ם שהוא „מוכתר בכתר תורה״, משא״כ בג׳ תנאים הנ״ל.\nויש לומר הטעם בזה: העילוי ד„מוכתר בכתר תורה״ הוא בזה — שהאדם שקוע כל כך בתלמוד תורה עד שזה נעשה כל מציאותו. כלומר: לא זו בלבד שלומד תורה, ועוד זאת ש„תלמודו מתקיים בידו״ — אבל עדיין אפשר להפריד בין מציאות האדם הלומד והדברי תורה שלמד, הוא מציאות בפני עצמו שיש לו „רכוש״, „קנה״ דברי תורה (עד ש„תורה דילי׳ היא״⁶²) — כ״א שהוא מוכתר (ומסובב) בדברי תורה באופן שזה נעשה מציאותו ועצמותו⁶³.",[["54","54","בכל הבא לקמן — ראה גם לקו״ש שם."],["55","55","ל׳ הרמב״ם בסוף הקדמתו לס׳ היד."],["56","56","שם ה״ו."],["57","57","שם ה״ז."],["58","58","שם הי״ג."],["59","59","שם ה״ח־ט."],["60","60","שם ה״ט."],["61","61","שם הי״ב."],["62","62","קידושין לב, רע״ב. — ומזה שלא הזכיר הרמב״ם (הל׳ ת״ת פ״ה הי״א) גבי הדין דהרב שמחל על כבודו כבודו מחול הפרט ד„כתר תורה״ מוכח, שענין זה (ד„תורה דילי׳ היא״) עדיין אינו המעלה דכתר תורה."],["63","63","ראה בארוכה לקו״ש שם סעיף ז ואילך בנוגע לכתר כהונה וכתר מלכות. — וראה שם, שמטעם זה מביא הרמב״ם הפסוקים (בנוגע לכתר כהונה וכתר מלכות) — „והיתה לו ולזרעו אחריו ברית כהונת עולם״ (פינחס כה, יג), „זרעו לעולם יהי׳ וכסאו כשמש נגדי״ (תהלים פט, לז) — כי בזה מודגש שענין הכהונה והמלכות נעשה מהותם ועצמותם, שלכן בא אצלם בירושה ובמילא נעשה נצחי, ירושה אין לה הפסק, לו ולזרעו אחריו."]]],[1300271258,"וכדי להגיע למעלה זו מוכרחים לשלשה תנאים הנ״ל, שכל אחד מהם מורה ומוכיח שלא זו בלבד שהוא לומד תורה, אלא שתורה נעשית כל מציאותו ואי אפשר להפריד בינו ובין התורה. כדלקמן.\nיו״ד. התנאי הראשון הוא — „לא יסיח דעתו לדברים אחרים״. והיינו: לא רק שבפועל אינו עוסק בדברים אחרים, אלא שגם דעתו ומחשבתו מושקעת כל כולה בתורה, עד שאינו מסיח דעתו מתורה.\nאח״כ מוסיף הרמב״ם עוד תנאי: „שמא תאמר עד שאקבץ ממון אחזור ואקרא כו׳״ — והחידוש בזה לגבי „לא יסיח דעתו לדברים אחרים״ [דלכאורה: מאחר שידעינן שאין לו להסיח דעתו לדברים אחרים — כש״כ שאם יתעסק בפועל בקיבוץ ממון (גם לפי שעה) אא״פ לו לזכות בכתר תורה]:\nהאמירה (המחשבה) לקבץ ממון כדי שיוכל לחזור ולקרות, אינה היסח הדעת „לדברים אחרים״, שהרי אדרבא כל כוונתו ומטרתו בעסק זה היא רק כדי שיוכל ללמוד (אח״כ) תורה במנוחה (וע״ד ביאור הרמב״ם בנוגע למשא ומתן שהיא עבודה למקום ב״ה, כנ״ל סעיף ד). אבל בכל זה, כדי להיות מוכתר בכתר תורה אי אפשר שיעבור יום שמלאכתו קבע (גם אם מטרתו בשביל שיוכל ללמוד אח״כ במנוחה), כי זה מורה שאפשר להפריד בינו ובין התורה (עכ״פ לשעה קלה), כ״א צ״ל (כהמשך דברי הרמב״ם בהלכה זו) „תורתך קבע ומלאכתך (רק) עראי״.\nויתירה מזו: מפשטות לשון הרמב״ם משמע שעצם אמירה ומחשבה זו כבר פוסלת אותו מלזכות בכתר תורה — כי\nמחשבה זו מורה שאין דעתו שקועה לגמרי בת״ת.\n[ועפ״ז הנ״ל במעלת „כתר תורה״ יובן עוד דיוק בלשון הרמב״ם כאן — „שמא תאמר עד שאקבץ ממון אחזור ואקרא, עד שאקנה כו׳ אחזור ואקרא״ — שמלשון זה משמע, שהמדובר במי שכבר קרא ולמד, ומחשבתו היא רק לדחות חזרתו עוד הפעם (אחזור ואקרא) „עד שאקבץ ממון כו׳״.\nולכאורה: לשון המשנה⁶⁴ (שמביא הרמב״ם בסיום ההלכה) הוא „לכשאפנה אשנה״⁶⁵ (סתם), והרמב״ם משנה בתחילת ההלכה וכותב שהמדובר בזה האומר „אחזור ואקרא״?\nועפ״ז הנ״ל יש לומר, שהרמב״ם מדגיש כאן במי שרוצה לזכות בכתר תורה. כלומר: אין המדובר במי שרוצה ללמוד תורה לצאת י״ח שמחוייב ללמוד תורה שבע״פ כולה (כמבואר בהל׳ ת״ת⁶⁶) — שבזה פשיטא שמקודם צריך לקיים מצות ת״ת, ואין לדחותה עד שאקבץ כו׳ — כי אם בזה שכבר (יצא י״ח ו)למד תורה שבע״פ כולה; ולאחרי זה רוצה לזכות בכתר תורה ע״י שישים כל מעינו בתורה ב„עיון עומק טעמי ההלכות כו׳״, „אחזור ואקרא״].\nוהתנאי השלישי — „יזהר בכל לילותיו ולא יאבד אפילו אחד מהן״, כי הבחינה שהתורה חדרה לעצם מציאותו היא בזה שאינו אובד אפילו לילה אחד; כמובן, החסרון בזה שאובד לילה אחד",[["64","64","אבות פ״ב מ״ד."],["65","65","שדוחק הכי גדול הוא לפרש „אשנה״ — לא אלמוד משנה (בניגוד למקרא), אלא מלשון „שני״."],["66","66","ראה הל׳ ת״ת לאדה״ז פ״א ס״ד־ה. רפ״ב ושם סי״א. רפ״ג."]]],[1300271259,"אינו בזה שביטל זמן שהי׳ צריך להקדיש ללימוד התורה (כי אפשר שישלים הזמן שהחסיר — ביום). אלא, מכיון שהלילה הוא הזמן המיוחד ללימוד התורה (דאין אדם למד רוב חכמתו אלא בלילה . . אין רנה של תורה אלא בלילה⁶⁷), הרי מי שתורה נעשית כל מציאותו, אי אפשר לו שיאבד אפילו לילה אחד. כי שום דבר בעולם אינו יכול לדחות ענין ששייך ונוגע לעצם מציאותו*⁶⁷.\nיא. עפ״ז מובן הטעם שבחר הרמב״ם בלשון הספרי ולא בלשון הש״ס:\nהלשון „כתר תורה״ (וכן — כתר כהונה וכתר מלכות) אפשר לפרש בשני אופנים:\nא) הכתר של התורה:<sup data-n=\"1\">1</sup> כתר מכסף וכיו״ב שמשימין על התורה⁶⁸,<sup data-n=\"2\">2</sup> חלק מיוחד בתורה. וכמו שמצינו⁶⁹ ש(דוקא) הלכות התורה נקראות „כתרה של תורה״.\nב) התורה נעשית כתר על האדם הלומדה. אין המדובר בחלק (או ענין) מיוחד שבתורה, כ״א שהתורה (בכללותה⁷⁰) מכתירה את האדם.\nוהנה ברמב״ם מדייק „בשלשה כתרים נכתרו ישראל״⁷¹, היינו שמעלת „כתר תורה״*⁷¹ כאן היא (כאופן הב׳) בזה\nשהתורה מכתירה את לומד התורה, ובזה היא ה„הלכה״ שברמב״ם כאן, ותלוי באופן ותנאי הלימוד, כנ״ל בארוכה.\nולכן לא הביא הרמב״ם לשון הש״ס „שלשה זירים הן כו׳״ — כי פשטות הלשון „שלשה זירים הן, של מזבח (כהונה) ושל ארון (תורה) ושל שלחן (מלכות)״ ענינו, שהמדובר במעלה מיוחדת אשר בגוף (וחפצא) אשר בכהונה תורה ומלכות. וכמו „הזירים״, שהיו חלק (העליון) של המזבח הארון והשולחן עצמם. וכן בנמשל, שהיא מעלה הכי עליונה בגוף הכהונה ומלכות (כהונה גדולה⁷², מלכות דוד), וכן בתורה.\nולכן בחר בלשון „שלשה כתרים״, שבפשטות „כתר״ הוא — הלבוש ותכשיט על ראש האדם, „בשלשה כתרים נכתרו ישראל״.\nיב. וע״פ כל הנ״ל יובן בתוספת ביאור תיאור הרמב״ם בסיום ספרו אודות „עסק העולם״ בימות המשיח:\nכוונת הרמב״ם היא להדגיש אשר בימות המשיח יזכו כל ישראל להיות מוכתרין בכתר תורה. דאף שגם בזמן הזה הוא „מונח ועומד ומוכן לכל ישראל״, הרי אין כל אדם זוכה לזה שיוכל לקיים התנאים הנ״ל הדרושים לזה.\nאמנם באותו הזמן, שנהי׳ „פנויין בתורה וחכמתה״, ו„הטובה תהי׳ מושפעת הרבה כו׳״ — הרי „לא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״. כי לא יהי׳ צורך להסיח דעתו „לדברים",[["67","67","רמב״ם שם. *67) בביאור הלכה זו — ראה גם לקו״ש חל״ד ע׳ 43 ואילך."],["68","68","זח״ג רנו, ב."],["69","69","מגילה כח, ב. ועיין אגה״ק סכ״ט. וראה לקו״ש שם סעיף ה והערה 45 שם."],["70","70","כי קוראים למין הפרטי בשם המין הכולל אותו (הקדמת פיהמ״ש בשם טהרות — וכן בשם כוכב ועוד)."],["71","71","אף שלשון זה (נכתרו ישראל) ליתא בספרי (ובכמה מהמקומות שהובא ענין זה). וראה לקו״ש שם הערה 82. וש״נ. *71) וכן כתר כהונה וכתר מלכות, כנ״ל הערה 63."],["72","72","אבל ראה ר״ח יומא שם: זכה אהרן ונטלה כלומר לקח הכהונה (ולא כתר כהונה, כה״ג)."]]],[1300271260,"אחרים״, ולא זו בלבד שאין חשש למחשבה „עד שאקבץ ממון אחזור ואקרא״, אלא עוד זאת, שלא יהי׳ צורך אפילו ב„מלאכה בכל יום מעט״;\nומאחר שאז יהיו ישראל מוכתרין בכתר תורה, הרי אין הלימוד בשביל לידע את המעשה אשר יעשון כו׳, או כדי לצאת י״ח מצות ידיעת תורה שבע״פ כולה, כ״א רק „לדעת את ה׳ בלבד״, בשביל ידיעת והשגת התורה.\nובמילא יקויים מש״נ „כי מלאה הארץ דעה את ה׳ כמים לים מכסים״ — שבנ״י יהיו מוכתרין בכתר תורה, ולכן לא רק שיהיו מלאים מדברי תורה, כ״א שתהי׳ התאחדות גמורה עם התורה, עד שלא תראה מציאותה של הארץ כ״א רק הענין ד„דעה את ה׳״ (כנ״ל סעיף ז), „כמים לים מכסים״.\n* * *\nיג. עוד דיוק בלשון הרמב״ם בסיום וחותם ספרו: „ולא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״. שבפשטות נכללו בזה גם אומות העולם (וכמ״ש הרמב״ם בפרק שלפנ״ז⁷³ שמלך המשיח „יתקן את העולם כולו לעבוד את ה׳ . . אהפוך אל עמים גו׳״), ובפרט שתיכף לאח״ז משנה הרמב״ם וכותב „ולפיכך יהיו ישראל חכמים גדולים כו׳״, שמזה מוכח, דמ״ש לפנ״ז „כל העולם״ כוונתו לכלול בזה גם בני נח.\nוע״פ הנ״ל בפירוש „לדעת את ה׳ בלבד״, שהכוונה בזה — עסק התורה (לא בשביל לידע את המעשה אשר יעשון כו׳, כ״א) בשביל ידיעת והשגת התורה עצמה, כדי להיות מוכתר בכתר\nתורה — נמצא, שאפילו מעלה זו ג״כ שייכת לבני נח.\nויש לומר, שמקורו דהרמב״ם הוא מספרי הנ״ל (סעיף ח), ששם הלשון: „כתר תורה מונח כדי שלא יתן פתחון פה לבאי העולם כו׳ כתר תורה מונח לכל באי העולם״ — שלשון זה („כל באי העולם״) כולל⁷⁴ גם אוה״ע⁷⁵. ונמצא שגם ב״נ שייכים לכתר תורה⁷⁶.\n[אלא שבהל׳ ת״ת לא העתיק הרמב״ם פרט זה (וכתב „כתר תורה הרי מונח כו׳ ומוכן לכל ישראל״ שנאמר⁷⁷ תורה צוה לנו משה מורשה קהלת יעקב״) — כי זה שיש כתר תורה גם אצל „כל באי העולם״ (בשבע מצות דידהו, כדלקמן) לסלק ה„פתחון פה״ אינו נוגע להלכות של ישראל⁷⁸; והרמב״ם רק מרמזו בתיאור מצב העולם באותו הזמן].\nואף שנכרי שלמד תורה חייב מיתה⁷⁹ — ה״ז רק בלימוד תורת מצות דישראל,",[["73","73","ספי״א."],["74","74","ראה ר״ה פ״א מ״ב, וברמב״ם הל׳ תשובה פ״ג ה״ג „מבאי העולם״. ועד״ז ברמב״ם שם פ״ו ה״ג. סוף הל׳ שמיטה ויובל. הל׳ מלכים פ״ח ה״י. וברמב״ם סוף הל׳ ס״ת, הל׳ סנהדרין פי״ב ה״ג: כל באי עולם. וראה לקו״ש חי״ג ע׳ 230. וש״נ. ואכ״מ."],["75","75","וכן מפורש במדרש לקח טוב ר״פ חוקת: כדי שלא ליתן פתחון פה לאומות העולם."],["76","76","אבל מובן ד„כתר תורה״ השייך בב״נ אינו כמעלת „כתר תורה״ דבנ״י — שהרי גבי בנ״י כתר תורה הוא למעלה מכתר כהונה (כהמשך דברי הספרי שם, וכן ברמב״ם בהלכה זו, וכמו שממשיך בהלכה שלאח״ז דממזר ת״ח קודם לכה״ג ע״ה), משא״כ נכרי שעוסק בתורה שהוא רק „ככהן גדול״ ולא למעלה ממנו (תוס׳ ע״ז ג, א). וראה לקו״ש ח״ה ע׳ 12 הערה 49. ועוד."],["77","77","ברכה לג, ד. — ומזה למדין (סנהדרין נט, רע״א) דנכרי שעסק בתורה חייב מיתה."],["78","78","כי טענתם היא לנותן הכתרים, הקב״ה (ולא לבנ״י)."],["79","79","סנהדרין שם. רמב״ם הל׳ מלכים פ״י ה״ט."]]],[1300271261,"אבל בלימוד שבע מצות דידהו, הרי אדרבה — אמרו חז״ל⁸⁰ „שאפילו נכרי ועוסק בתורה שהוא ככהן גדול״, שמעלה זו („שהוא ככהן גדול״) שייכת למעלת התורה עצמה, כדאיתא בתוס׳⁸¹ „דנקט כהן גדול משום דדרשינן⁸² . . יקרה היא מפנינים⁸³ מכהן גדול הנכנס לפני ולפנים״. שמזה מוכח, דזה שנכרי ישנו בלימוד שבע מצות דידהו, הוא לא רק הכשר לקיום מצות דילהו, כ״א יש בזה מעלה וחשיבות של תורה⁸⁴.\n[ויתירה מזו: מזה שכתב בספרי שב״נ שייכים לכתר תורה, משמע, שב״נ ישנם — לשיטת הספרי — במצות ת״ת (תורת שבע מצות דידהו), היינו שיש בהם חיוב לעסוק בהלכות שבע מצות דידהו (לא רק בשביל לידע את המעשה כו׳ כ״א) חיוב של ת״ת בפ״ע⁸⁵ (והא שלא נמנה בין המצות שלהן, כי בז׳ מצות מונים רק מצות ל״ת ולא קום ועשה⁸⁶)].\nוי״ל שזהו ג״כ מה שהרמב״ם מביא הכתוב „כי מלאה הארץ דעה את ה׳״ — לא רק בני ישראל, כ״א „הארץ״ — „לא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״*⁸⁶.\nיד. עפ״ז יש לבאר הקשר והשייכות דסיום ספר היד להתחלתו:\nבחותם ספרו מדגיש הרמב״ם ד„לא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״ באופן ד„כמים לים מכסים״, היינו שזה נעשה כל מציאותו (לא רק דבנ״י, כ״א) ד„כל העולם״.\nולכאורה: בשלמא בני ישראל, עם קרובו שניתן להם נשמה קדושה, חלק אלקה ממעל ממש⁸⁷, מובן שכל מציאותם היא — „דעה את ה׳״. אבל איך",[["80","80","סנהדרין שם. וש״נ."],["81","81","ב״ק לח, א. וכן בע״ז ג, א."],["82","82","סוטה ד, ב. הוריות יג, א."],["83","83","משלי ג, טו."],["84","84","ראה בארוכה בזה לקו״ש חי״ד ע׳ 38 ואילך. וראה מאירי סנהדרין שם: „כל שהוא עוסק בעקרי שבע מצות ובפרטיהם ובמה שיוצא מהם אע״פ שרוב גופי תורה נכללין בהם מכבדין אותו אפילו ככהן גדול כו׳״. ומהמשך דבריו שם מוכח שמותר לנכרי ללמוד „לא לכוונת קיום עקרי מצוות אלא שלבו חפץ לירד לידיעת תורת ז׳ המצות (עד ש„רוב גופי תורה נכללין בהם״)* — וע״ז נאמר ד„מכבדין אותו אפילו ככה״ג״. וראה עד״ז בשו״ת מחנה חיים (ח״א סי׳ ז). ושם, דזהו דיוק לשון חז״ל „נכרי ועוסק בתורה״, שמורה על הלימוד ופלפול בתורה (כמ״ש הט״ז — צויין לעיל הערה 35), שדוקא אז נחשב ככה״ג. ולהעיר מתשובת הרמב״ם (פאר הדור ס״נ. פריימאן סשס״ד), דמשמע שם שטעם האיסור ללמד תורה לנכרי הוא משום שיש בזה מכשול לישראל (ע״ש) — והרי זוהי שיטת המאירי שם, שמתיר לנכרי ללמוד ז׳ מצוות גם באופן ש„רוב גופי תורה נכללין בהם״, כי באופן זה „אין כאן חשש לטעות אחריו כו׳״. *) ודלא כמ״ש בחדא״ג מהרש״א חגיגה (יג, א ד״ה אין מוסרין) ד„אפי׳ בז׳ מצות שלהם אין מוסרין להם סודן וטעמן״. אבל להעיר שכתב זה בדברי ר׳ אמי (חגיגה שם), שלא הובאו בפוסקים (כידועה השקו״ט בזה). ואכ״מ."],["85","85","ראה תוד״ה אין חגיגה (יג, א) דמהא דאפילו נכרי ועוסק בתורה ה״ה ככה״ג נפקא לן דמצוה ללמדם (ז׳ מצות שלהם) — והרי הענין ד„ה״ה ככה״ג״ מורה על חשיבות דתורה בפ״ע, כנ״ל בפנים (והערה הקודמת)."],["86","86","סנהדרין נח, סע״ב. *86) ומה שהרמב״ם ממשיך „ולפיכך יהיו ישראל חכמים גדולים כו׳״ — כי עיקר כוונת הרמב״ם כאן היא לבאר הטעם (אמ״ש בהלכה שלפנ״ז) ש„נתאוו החכמים כו׳ לימות המשיח כו׳ כדי שיהיו פנויין בתורה ובחכמתה״, שזהו מצד מצב העולם „באותו הזמן״, „לא יהי׳ שם כו׳ ולא יהי׳ עסק כל העולם כו׳ — ולפיכך יהיו ישראל כו׳״."],["87","87","תניא רפ״ב. וראה איוב לא, ב."]]],[1300271262,"יתכן לומר כן בנוגע ל„כל העולם״, שכל מציאותו יהי׳ „לדעת את ה׳״?\nהנה לזה „מתכיפין התחלה להשלמה״⁸⁸ ולומדים תיכף בתחילת ספר היד: יסוד היסודות ועמוד החכמות לידע שיש שם מצוי ראשון והוא ממציא כל נמצא וכל הנמצאים משמים וארץ ומה שביניהם לא נמצאו אלא מאמיתת המצאו,\nדהלשון „ממציא כל נמצא״ (לא „המציא״, ל׳ עבר) פירושו⁸⁹ — ש„ממציא״ גם בהווה (בכל רגע ורגע) כל נמצא. שלכן, אמיתית המציאות של כל נברא הוא (כביאור אדמו״ר הזקן בארוכה⁹⁰) רק „כח הפועל . . שבנפעל המהווה אותו תמיד״.\nוזהו מה שיתגלה לעתיד לבא — „כי מלאה הארץ דעה את ה׳ כמים לים מכסים״, שאז תתגלה אמיתית מציאותו של כל הארץ, ש„כל הנמצאים משמים וארץ כו׳ לא נמצאו אלא מאמיתת המצאו״, ובמילא לא תהי׳ נראית גשמיות הארץ (כולל כל באי העולם) כדבר בפני עצמו, כ״א רק — „דעה את ה׳״, „אמיתת המצאו״.",[["88","88","ל׳ ה„רשות לחתן בראשית״."],["89","89","ראה ה„פירוש״ להל׳ יסוה״ת פ״א ה״ג. וראה שעהיוה״א פ״א."],["90","90","שם פ״ג."]]],[1300271263,"הדרן על הרמב״ם משיחת ש״פ ויקהל, פ׳ שקלים, מבה״ח אדר שני ה׳תשמ״ו\nא. בסיום ספר „משנה תורה״, מבאר הרמב״ם באריכות גדולה את מצב העולם בימות המשיח, ומקדיש לזה¹ פרק שלם.\nוצריך להבין: הרי כל הענינים שבספר „משנה תורה״² הם הלכות (כמ״ש הרמב״ם בהקדמתו), שענינם הוא פס״ד בנוגע למעשה. וא״מ, היאך שייך לומר על ענין הנ״ל (תיאור המצב שיהי׳ בימות המשיח) שזהו הלכה, מהי הנפקותא בנוגע לפועל מביאור מצב זה?\nויש לומר, שהחיוב להאמין בביאת המשיח ולחכות לביאתו כולל גם כל המעלות שיהיו אז. ועפי״ז מובן, שתיאור המצב דימות המשיח הוא (לא רק סיפור דברים, אלא) הלכה, פסק דין הנוגע למעשה בפועל — שיש חיוב להאמין ולחכות (לא רק לכללות ביאתו של משיח אלא גם) למצב זה בכל הפרטים המנויים ברמב״ם.\nאמנם הא גופא טעמא בעי — מדוע אינו מספיק להאמין ולחכות לביאתו של משיח (בכלל), ומחוייבים גם להאמין ולחכות לכל הפרטים?\nב. והנה הגדר דביאת המשיח הוא — שקיום המצוות יהי׳ אז בתכלית השלימות. וכלשון הרמב״ם בפרק שלפנ״ז³ „וחוזרין כל המשפטים בימיו כשהיו מקודם, מקריבין קרבנות, ועושין שמיטין ויובלות ככל מצותה האמורה בתורה כו׳״.\n[נוסף על מה שאפילו בנוגע המצוות שנהוגות גם בזמן הזה הרי דוקא בימות המשיח תהי׳ האפשרות לעסוק בתומ״צ כהוגן⁴].\nומובן בפשטות, שהשלימות שתהי׳ בימות המשיח היא שלימות נעלית יותר גם מאותה שלימות שהיתה בזמן שביהמ״ק הי׳ קיים, כולל גם אותם הזמנים שלא היו מלכיות שהצירו לישראל ושלא הניחו לישראל לעסוק בתומ״צ כהוגן (כמו בימי שלמה) — מכיון שדוקא בימות המשיח יהי׳ „והסירותי⁵ את לב האבן מבשרכם״⁶.\n[וענין זה — שבימות המשיח יהי׳ קיום המצוות בתכלית השלימות — מודגש בעיקר בהמצוה ראשונה (ראשונה גם במעלה, מכיון שהיא ה„יסוד״ וה„עמוד״ דכל המצוות) —",[["1","1","בנוגע מצב העולם שיהי׳ בימות המשיח. משא״כ הפרק שלפנ״ז (פי״א) הוא בנוגע משיח עצמו."],["2","2","אפילו ענין שבא רק במילים ספורות. ועאכו״כ בנידון דידן — שהתיאור דימות המשיח הוא פרק שלם."],["3","3","רפי״א. וראה בארוכה לקו״ש חי״ח ע׳ 277 ואילך."],["4","4","הל׳ תשובה פ״ט ה״ב. וראה גם הל׳ מלכים פי״ב ה״ד."],["5","5","יחזקאל לו, כו. ועד״ז שם יא, יט."],["6","6","הל׳ תשובה שם."]]],[1300271264,"מצות ידיעת השם, דמכיון שאז דוקא „תרבה הדעה כו׳ והחכמה שנאמר⁷ כי מלאה הארץ דעה את ה׳״⁶ — הרי כל זמן שהדיעה אינה בריבוי אי אפשר שיהי׳ ידיעת השם בשלימות (משא״כ בשאר המצוות, שהעדר השלימות בהם הוא רק מצד דברים המונעים)].\nועפ״ז הי׳ אפשר לבאר מה שבחיוב האמונה בביאת המשיח נכלל גם התיאור דמצב העולם שיהי׳ אז — כי תיאור זה הוא ביאור וטעם על השלימות דקיום התומ״צ שיהי׳ אז [כולל השלימות דמצות ידיעת השם — „וישיגו דעת בוראם״⁸], שענין זה הוא הגדר דביאת המשיח.\nאמנם, ביאור זה — אינו מספיק, דלפי הנ״ל, הגדר דביאת המשיח הוא — שלימוד התורה וקיום המצוות דישראל יהי׳ אז בתכלית השלימות [וכמ״ש הרמב״ם⁹: „לא נתאוו החכמים והנביאים ימות המשיח כו׳ אלא כדי שיהיו פנויין בתורה וחכמתה״, היינו, שהעילוי דימות המשיח (שלזה צריכים לחכות ולצפות¹⁰) הוא השלימות דתומ״צ], משא״כ מצב העולם שיהי׳ ב„אותו הזמן״, מה שלא יהי׳ בו „לא רעב ולא מלחמה וכו׳״, הוא רק ענין צדדי שמאפשר לישראל לעסוק בתומ״צ בשלימות, — וא״כ, מדוע התיאור דמצב העולם שיהי׳ אז (שהוא לכאורה רק ענין צדדי) הוא פרט וגדר בחיוב האמונה בביאת המשיח?\nג. והנה בענין העילוי דישראל שיהי׳ אז כתב הרמב״ם בסיום וחותם ספרו, וז״ל: „יהיו ישראל חכמים גדולים ויודעים דברים הסתומים וישיגו דעת בוראם כפי כח האדם שנאמר⁷ כי מלאה הארץ דעה את ה׳ כמים לים מכסים״.\nוהנה מלשון הרמב״ם — „יודעים דברים הסתומים״, „וישיגו דעת בוראם״ — „יודעים״ בלשון הוה, „וישיגו״ בלשון עתיד — משמע שמדובר כאן על ב׳ ענינים:\nא) „יודעים דברים הסתומים״ הוא פרט בהעילוי דישראל גופא, ובא בהמשך ל„חכמים גדולים״, היינו שהוא מתאר את העילוי דישראל עצמם; ב) משא״כ „וישיגו דעת בוראם כו׳״ הכוונה היא לאופן קיום המצוה דידיעת השם שיהי׳ אז. שקיום מצוה זו תהי׳ בתכלית השלימות — שישיגו דעת בוראם כל מה שיש בכח האדם להבין ולהשיג.\nוצריך להבין:\nא) מה הם שני הענינים בהעילוי דישראל עצמם: (1) „חכמים גדולים״; (2) „יודעים דברים הסתומים״.\nב) „כפי כח האדם״ — מאי קמ״ל? פשיטא שהאדם יכול להשיג רק כפי כחו ולא יותר, ובפרט כשהמדובר אודות „דעת בוראם״?\nג) מדוע מעתיק הרמב״ם גם סיום הפסוק „כמים לים מכסים״. ובפרט שבהלכות תשובה⁶, שגם שם מתאר הרמב״ם איך ש„באותן הימים תרבה הדעה והחכמה כו׳״ ומביא אותו הפסוק „כי מלאה הארץ גו׳״, לא הביא סיום הכתוב „כמים לים מכסים״.\nד) יתירה מזו: הענין ד„כמים לים מכסים״ הוא לכאורה היפך הענין ד„ישיגו דעת בוראם״, כי — „ישיגו דעת בוראם״ מורה על השגה באופן של",[["7","7","ישעי׳ יא, ט."],["8","8","לשון הרמב״ם הל׳ מלכים שם ה״ה. וראה לקמן סעיף ג."],["9","9","הל׳ מלכים שם ה״ד. וראה גם הל׳ תשובה שם."],["10","10","כמובן ממה שכתב הרמב״ם ענין זה בספר הלכות שלו — כי זהו הלכה ופס״ד, למה צריך לחכות ולהתאוות."]]],[1300271265,"תפיסא, בדוגמת דבר הנמצא בהישג ידו, ואילו „כמים לים מכסים״ מורה על ענין שלמעלה מתפיסת האדם, שלכן, המשל לזה הוא ממים שמכסים את מציאות הים וכל אשר בו, וכן הוא בנמשל — שהענין ד„דעה את ה׳״ נשאר למעלה ממציאותו והשגתו, וא״כ, מדוע מסיים הרמב״ם בענין ד„כמים לים מכסים״ — בהמשך לביאור העילוי דהשגת אלקות לעתיד לבוא, ש„ישיגו דעת בוראם״?\nד. ויובן כל זה בהקדים הידוע שהגדר דמצות ידיעת השם הוא לא לידיעה שהוא ית׳ נמצא — דמכיון שכל הגדר דמצוה זו שייך רק לאחרי הידיעה שיש אלוקה (מצַוה המצוה), הרי על ידיעה זו גופא לא יתכן לומר שהיא מצוה. ובלשון האברבנאל¹¹: „כאשר נניח אמונת מציאות הא־ל מצוה כבר נניח אמונת מציאות הא־ל קודמת לאמונת מציאות הא־ל״.\nומ״ש הרמב״ם שמצוה ראשונה היא „לידע שיש אלוקה״ — מבאר האברבנאל¹² וז״ל: „והמצוה הראשונה היא שנאמין שהאלוקה ב״ה שכבר ידענו שהוא נמצא, מציאותו היא היותר ראשון והיותר שלם אשר בכל המציאות . . כי הוא אינו צריך במציאותו לזולתו וכל מה שזולתו צריך במציאותו אליו כו׳״.\nדזהו מ״ש הרמב״ם שהמצוה „לידע״ היא (לא רק שיש אלוקה בכלל, כי אם) שיש שם מצוי ראשון והוא ממציא כל נמצא, ומוסיף: וכל הנמצאים כו׳ לא נמצאו אלא מאמיתת המצאו, די״ל שכוונתו בהוספה זו היא להדגיש ש„כל מה שזולתו צריך במציאותו אליו״.\nה. והנה יש לומר, שידיעת מציאותו ית׳ שלפני הציווי („שכבר ידענו שהוא נמצא״), מכיון שהיא הסיבה להידיעה שמציאותו היא היותר שלם כו׳ (שהרי הקיום דמצות ידיעה זו הוא מסובב מהאמונה בהאלוקה, מצַוה המצוה) — היא נעלית יותר מהידיעה שמציאותו היא היותר שלם כו׳¹³.\nוהביאור בזה: שלימות זו דמציאותו ית׳ (מה שהוא אינו צריך לזולתו, וכל מה שזולתו צריך במציאותו אליו) — הוא שלימות שע״פ שכל. ומכיון שהקב״ה אינו מוגדר בשום גדר ח״ו, גם לא באותם הגדרים שע״פ שכל הם מחוייבים¹⁴",[["11","11","בספר ראש אמנה פ״ד — הובא בספהמ״צ להצ״צ מצות האמנת אלקות בתחלתה (מד, ב). וראה גם השגות הרמב״ן לספהמ״צ להרמב״ם מ״ע א׳ — הובא בספהמ״צ להצ״צ שם."],["12","12","הובא בספהמ״צ להצ״צ שם (מה, א). ובספהמ״צ שם מבאר באר״א, כדלקמן הערה 17."],["13","13","ואף שמפשטות לשון האברבנאל שם (וכן מלשון הצ״צ שם) משמע להיפך, שהאמונה שעלי׳ באה הציווי היא נעלית יותר מהאמונה שלפני הציווי — יש לומר, שזהו בענין הגילויים. דמכיון שהאמונה שלפני הציווי היא רק ידיעה כללית שיש אלוקה (מבלי להכנס לשום פרטים) — הרי בידיעה זו אין נרגש העילוי וההפלאה דאלקות. אבל אעפ״כ, מכיון שכל הגדר דעילוי והפלאה הוא רק בבחינת הגילויים, משא״כ בעצמותו ית׳ — הרי אדרבה, הידיעה הכללית שיש אלוקה (אלוקה סתם, בלי שום תיאור של עילוי והפלאה), ידיעה זו דוקא היא בעצמותו ית׳. ועיין בתו״א וירא יד, ב."],["14","14","ועפ״ז יש לבאר מ״ש הרמב״ם (הל׳ תשובה ספ״ה) בענין השאלה ד„ידיעה ובחירה״, ש„תשובת שאלה זו ארוכה מארץ מדה כו׳״ וש„אין בנו כח לידע היאך ידע הקב״ה כל הבריאים והמעשים״ (וראה בהשגת הראב״ד שם) — דלכאורה תמוה, הרי מובן בפשטות, שבידיעת איזה דבר — אין הידיעה סיבה להדבר, אלא להיפך, הידיעה מסובבת מהדבר. ואותו הדבר הוא (לכאורה) בענין ידיעת הקב״ה, דמה שיודע גם העתיד להיות, הוא מפני שלגבי ית׳ ישנו כבר הדבר, מכיון ש„לפניו ית׳ אין קדימה ואיחור שאינו בחוק הזמן״. ועפ״ז, ה„קושיא״ (מדוע הידיעה אינה מכרחת את הבחירה) מעיקרא ליכא, דמכיון שמה שהוא ית׳ יודע"]]],[1300271266,"[כי כל גדרי השכל נבראו ממנו ית׳, הרי מזה מובן בפשטות שהוא ית׳ שברא את הגדרים אינו מוגדר בהם ח״ו, וכתשובת הרשב״א¹⁵ הידועה שהוא ית׳ „נמנע הנמנעות״, שלפניו ית׳ אין שייך ח״ו שום דבר נמנע] —\nהרי הידיעה דשלימות זו היא רק כמו שהקב״ה צמצם את עצמו כביכול להיות „שלם״ גם בגדרי השכל, אבל פשוט שאינה מבטאה כלל וכלל אמיתית ענין השלימות שלמעלה מגדרי השכל¹⁶,\nועאכו״כ שאין זו ידיעה כלל בעצמותו ית׳, שאינו מוגדר כלל בהתואר דשלימות (גם לא בשלימות נעלית ביותר¹⁷).\nוזהו מה שהאמונה במציאותו ית׳ שלפני הציווי היא השורש והסיבה להידיעה (שנצטוינו לידע) „שיש שם מצוי ראשון כו׳״ (דסיבה היא למעלה ממסובב) — כי האמונה במציאותו ית׳ (ידיעה כללית שיש אלוקה) היא בעצמותו ית׳.\nו. עפ״ז יובן מ״ש הרמב״ם (שם ה״ד) „הוא שהנביא אומר¹⁸ וה׳ אלקים אמת, הוא לבדו אמת ואין לאחר אמת כאמיתתו, והוא שהתורה אומרת¹⁹ אין עוד מלבדו כו׳״ — דלכאורה אינו מובן: הרי הענין דאמיתתו ית׳ הסביר כבר מקודם (ה״ג) ע״פ שכל, דמכיון „שכל הנמצאים צריכים לו והוא ב״ה אינו צריך להם ולא לאחד מהם, לפיכך אין אמיתתו כאמיתת אחד מהם״ — וא״כ מה כוונתו בזה שמוסיף „הוא שהנביא אומר כו׳ שהתורה אומרת״?!\nוהביאור בזה: מכיון שהוא ית׳ אינו מוגדר בשום גדר ח״ו — הרי ביכלתו",[["","","(מקודם) היאך יבחור האדם הוא מפני שלגבי ית׳ היתה כבר הבחירה — הרי זה ממש כמו הידיעה הבאה אחר הבחירה. וכמבואר כל זה בארוכה במדרש שמואל על מס׳ אבות פ״ג מכ״א בשם הר״ם אלמושנינו (הובא בתויו״ט שם). ולמה כתב הרמב״ם ש„תשובת שאלה זו ארוכה מארץ מדה כו׳ אין בנו כח לידע כו׳״? ולאידך, באם ישנה סברא השוללת את תירוץ הנ״ל (ועכצ״ל שהיא סברא פשוטה, שלכן לא הוזקק הרמב״ם להוסיף „הסבר״ בהקושיא דידיעה ובחירה) — היאך לא עמד הר״ם אלמושנינו על סברא זו? ויש לומר הביאור בזה: כלל הנ״ל שידיעה מסובבת מהדבר שיודע — הוא ע״פ גדרי השכל. ומכיון שהוא ית׳ אינו מוגדר בגדרי השכל — הרי ידיעתו ית׳ היא לא מצד הדבר שיודע, כי אם, שיודע מצד עצמו. ורק לאחרי שצמצם עצמו כביכול בגדרי השכל — הנה ידיעה זו (שלאחרי הצמצום) היא מסובבת מהדבר (אלא שמ״מ גם בבחינה זו הוא יודע את העתיד להיות, כי „לפניו ית׳ אין קדימה ואיחור״, כנ״ל). ועיין בתו״א וירא (טו, א) בענין דעת עליון ודעת תחתון, די״ל שהם ב׳ הבחינות דלעיל. ועפ״ז יש לומר, שהר״ם אלמושנינו מדבר בענין הידיעה שלאחרי הצמצום, משא״כ הרמב״ם (בהל׳ תשובה שם) מדבר בענין הידיעה שלפני הצמצום."],["15","15","סתי״ח — הובאו בס׳ החקירה להצ״צ לד, ב. ובכ״מ. וע״פ מ״ש לקמן בפנים, יש לומר דמ״ש בכמה ספרי חוקרי ישראל (הובאו בספר החקירה שם) דיש לנמנעות טבע קיים בחיק הבורא — כוונתם היא להבורא ית׳ כפי שצמצם עצמו בגדרי השכל."],["16","16","ונוסף לזה: מצד בחינת האלוקות שלמעלה מגדרי השכל — אינו מוכרח גם שיהי׳ שלימות זו (נוסף על מה שאין זה ענין של שלימות לגבי׳) דכל מה שזולתו צריך במציאותו אליו, כי מצד בחינה זו ביכלתו ית׳ להיות דבר שלא יצטרך במציאותו אליו, כדלקמן ס״ו."],["17","17","ולכן, גם לפי מ״ש בספהמ״צ להצ״צ שם, דענין שלימות מציאותו (שעל זה היא מצות האמונה) הוא (לא הענין ד„מחוייב המציאות״ כמ״ש האברבנאל, כי אם) „שהוא ית׳ רם ונשגב למעלה מעלה ממדריגת החכמה״ — האמונה שמצד הציווי היא למטה מהאמונה שלפני הציווי. כי גם הענין ד„רם ונשגב למעלה מעלה ממדריגת החכמה״ הוא תואר של „שלימות״ (והוא בחי׳ סובב כל עלמין, כמ״ש בספהמ״צ שם), משא״כ האמונה שלפני הציווי היא (כנ״ל הערה 13) בעצמותו ית׳."],["18","18","ירמי׳ י, י."],["19","19","ואתחנן ד, לה."]]],[1300271267,"להמציא את הנמצאים באופן כזה שלאחרי שנמצאו לא יהיו צריכים אליו.\nדאף שע״פ שכל מוכרחת להיות התהוות כל הנמצאים באופן שיהיו תמיד צריכים אליו (וכמבואר בתניא²⁰ דענין בריאת יש מאין מחייב שכח הפועל צריך להיות תמיד בהנפעל להוותו מאין ליש) — הרי, מכיון שהוא ית׳ הוא „נמנע הנמנעות״, הרי ההוכחות דשכל אינם שום ראיות כלל באיזה אופן היתה הבריאה;\nולכן מוסיף הרמב״ם הוא שהנביא אומר . . והוא שהתורה אומרת כו׳ — שהקב״ה הודיענו ע״י נביאיו וע״י תורתו שהבריאה היתה באופן כזה ש„כל הנמצאים צריכים לו״.\nז. ויש להוסיף, שמ״ש הרמב״ם „הוא שהנביא אומר כו׳״ — היא לא רק ראי׳ והוכחה על מ״ש לפנ״ז, אלא שזה (גם) הלכה. והוא דענין זה גופא — שבאופן פעולת הקב״ה א״א להכריח שום דבר מצד השכל, ועל כל פרט ופרט צריך להביא ראי׳ מהתורה — הוא פרט דמצות ידיעת השם, היינו, שבמצות ידיעת השם נכללת גם הידיעה שהוא ית׳ הוא למעלה מגדרי השכל.\nויש לומר דהלכה זו מרמז הרמב״ם גם מקודם (בהל׳ ב׳) בהלשון „ואם יעלה על הדעת שהוא אינו מצוי״: בה״א כותב „והוא ממציא כל נמצא״, „ממציא״ לשון הוה, שתמיד (גם לאחר שי״ב) הוא ממציא כל נמצא מאין ליש, ועל זה ממשיך (בה״ב) „יעלה על הדעת שהוא אינו מצוי״ — שצריך להיות עלי׳ בדעת²¹, ידיעה נעלית יותר, שמצדו ית׳ הי׳ אפשר להיות ההתהוות גם באופן שאינו מצוי בהנמצאים²² [ורק שכן עלה ברצונו ית׳ שההתהוות תהי׳ באופן כזה שבהסתלק כח הפועל „אין דבר אחר יכול להמצאות״]²³.\nח. המורם מכל הנ״ל שבאמונת וידיעת השם — ג׳ ענינים:",[["20","20","ח״ב פ״ב. וראה בארוכה ד״ה נ״ח תרמ״ג. ובכ״מ."],["21","21","ראה גם „הדרן״ על הרמב״ם (קה״ת, ברוקלין, י״א ניסן תשמ״ה) ס״ט, דפירוש „יעלה על הדעת״ הוא עלי׳ בדעת, אלא שהביאור שם הוא באופן אחר, כבהערה הבאה."],["22","22","ראה ב„פירוש״ על הרמב״ם כאן ה״ג. ב„הדרן״ הנ״ל שם, דפירוש „יעלה על הדעת שהוא אינו מצוי״ הוא העלי׳ בדעת שהוא ית׳ הוא למעלה מבחי׳ „מצוי״, „אינו (בגדר) מצוי״. ויש לקשר שני הפירושים, כי מה שהי׳ אפשר להיות ההתהוות באופן שאינו מצוי בהנמצאים (כהפירוש שבפנים, וכדמשמע בה„פירוש״) — הוא (בעיקר) מצד הבחינה ד„אינו מצוי״."],["23","23","ע״פ מ״ש בפנים יובן מ״ש בספהמ״צ להצ״צ שם (נעתק לעיל הערה 17) דמצות האמונה היא „שהוא ית׳ רם ונשגב למעלה מבחי׳ מדריגת החכמה״, ומהמשך הענין שם משמע שמפרש כן בדעת הרמב״ם — דלכאורה יוקשה, הרי הרמב״ם כותב שהמצוה היא „לידע שיש שם מצוי ראשון והוא ממציא כל נמצא כו׳״, והיאך אפשר לפרש בדעת הרמב״ם שמצות האמונה היא שהוא „רם ונשגב כו׳״? וע״פ מ״ש בפנים — אתי שפיר, דפרט זה בהמצוה (שהוא „רם ונשגב כו׳״) כתב הרמב״ם בה״ב ובה״ד. ומה שבהתחלת הענין כותב הרמב״ם „לידע שיש שם מצוי ראשון כו׳״ — אף שעיקר מצות האמונה (לפי ביאור הצ״צ) שהוא רם ונשגב כו׳ — יש לומר, כי המצוה היא שגם הענין ד„רם ונשגב״ יהי׳ באופן ד„לידע״, ידיעה שכלית (כדלקמן ס״ח), ולכן מקדים הרמב״ם הענין ד„לידע שיש שם מצוי ראשון כו׳״ — כי דוקא לאחרי ידיעה זו אפשר להגיע לידיעה נעלית יותר** („יעלה על הדעת״) שהוא ית׳ הוא למעלה מגדרי השכל. *) וכ״ה להדיא בספהמ״צ מצות אחדות ה׳ (ס, סע״א ואילך). **) כי ידיעת השלילה באה דוקא לאחרי ידיעת החיוב וכל מה ש„חיוב״ הוא נעלה יותר, ההפלאה דשלילת חיוב זה היא הפלאה (נעלית יותר) — ראה לקו״ת פקודי ג, ד. ושם ו, ג — ממו״נ (להרמב״ם) ח״א פנ״ז ואילך."]]],[1300271268,"א) האמונה (שלפני הציווי), ידיעה כללית שיש אלוקה (מבלי להכנס לשום פרטים).\nב) הידיעה (מצד הציווי) שיש שם מצוי ראשון והוא ממציא כל נמצא וכו׳, הידיעה בשלימותו ית׳ (שע״פ שכל).\nג) ידיעה נעלית יותר (שגם היא בכלל המצוה) שהוא ית׳ אינו מוגדר בגדר השכל; וגם ענין זה באופן של ידיעה שכלית („לידע״) — שהשכל גופא ידע ויבין שהוא נברא מהקב״ה, ושהקב״ה אינו מוגדר בו ח״ו, ובלשון החקירה²⁴: תכלית הידיעה שלא נדע.\nאלא שאעפ״כ, גם ידיעה זו היא שונה מהידיעה הכללית (האמונה) שיש אלוקה, שישנה באדם עוד לפני קיום המצוה.\nכי ידיעה הנ״ל ד„יעלה על הדעת שהוא אינו מצוי״, היא באה מצד ידיעת ושכל האדם (ורק שבשכל האדם גופא היא באופן של ידיעת השלילה): משא״כ האמונה והידיעה הכללית שיש אלוקה, הרי ידיעה זו שבאדם היא לא מצד גדרי ידיעת ושכל האדם (גם לא כמו שהוא באופן של ידיעת השלילה), כי אם, מצד זה שהוא ית׳ נמצא בגילוי בכל מקום²⁵.\nט. והנה כמו שהוא במצות ידיעת השם — מצוה ראשונה, ראשונה גם במעלה (כנ״ל ס״ב) — עד״ז הוא בכללות המצוות, שיש בהם (דוגמת) ג׳ ענינים אלו²⁶:\nהנקודה העיקרית במצוות הוא — שהם רצונו של הקב״ה, רצונו ית׳ שלמעלה גם מחכמתו:\nאלא שאעפ״כ רצה הקב״ה שהרצון דמצוות — יומשך גם בשכל — טעמי המצוות. ויתירה מזו: גם המצוות גופא ניתנו בתורה שהיא חכמתו ית׳, ולא עוד אלא שרובם ככולם של דיני המצוות נתפרשו בתושבע״פ²⁷, ומהן — דברים הנלמדים ע״פ שלש עשרה מדות, שאופן הלימוד הוא ע״פ שקו״ט וכו׳ (ועד ששייך בזה פלוגתא) — חכמה ושכל:\nולאחרי השקו״ט שבכל סוגיא — באה המסקנא, ההלכה והפס״ד איך צריך לקיים את המצוה, שהוא גילוי רצונו ית׳ שלמעלה מחכמתו. [שלכן נקראים הלכות בשם „כתרה של תורה״²⁸, להיותם גילוי רצונו ית׳ שלמעלה מחכמתו, בדוגמת כתר ועטרה שלמעלה מהראש²⁹].\nוכמו שהוא בהמצוות עצמן, עד״ז הוא גם בקיום המצוות של האדם, שגם בזה יש דוגמת ג׳ ענינים הנ״ל:\nהנקודה הראשונה שצ״ל עוד לפני קיום המצוות, היא קבלת עול מלכות שמים וקבלת עול מצוות³⁰ [בדוגמת אמירת „נעשה ונשמע״³¹ שהיתה לפני מ״ת] — בדוגמת האמונה והידיעה",[["24","24","ראה בחינות עולם ח״ז פ״ב. עיקרים מ״ב ספ״ל. שלה״ה קצא, ב."],["25","25","ראה תו״א וירא יד, ב: המאור הוא בהתגלות ולכן אפילו תינוקות יודעים כו׳."],["26","26","ועד״ז הוא בכללות הבריאה: הרצון לברוא את העולם (מצד עצמו) — הוא באופן ד„נתאוה״, תאוה שלמעלה מהטעם (המשך תרס״ו בתחלתו); לאח״ז — נעשה גם טעמים על הרצון, „בגין דישתמודעון לי״ וש„יתגלו שלימות כחותיו״ (כמובא בהמשך הנ״ל שם מזהר וע״ח): אמנם הכוונה בטעמים אלו היא בכדי שעל ידם תושלם (אח״כ) הכוונה ד„דירה בתחתונים״, דירה לעצמותו (ראה לקו״ש ח״י ע׳ 21 הערה 69)."],["27","27","שעיקרה (משא״כ תושב״כ) הוא הבנה והשגה, וכשאינו מבין „אינו נחשב לימוד כלל״ (הל׳ ת״ת לאדה״ז ספ״ב. וש״נ). וראה לקו״ת ויקרא ה, ב."],["28","28","מגילה כח, ב."],["29","29","אגה״ק סכ״ט."],["30","30","ברכות יג, א."],["31","31","משפטים כד, ז. וראה שבת פח, סע״א ואילך."]]],[1300271269,"הכללית שיש אלוקה, שלפני קיום מצות ידיעת השם;\nולאחרי הקדמה זו, הנה בכדי לדעת את המעשה אשר יעשון צ״ל תחלה לימוד התורה בחכמה ושכל — דוגמת הידיעה בשלימותו ית׳ שע״פ שכל:\nולאחרי זה „גדול תלמוד שמביא לידי מעשה״³², קיום רצונו ית׳ — דוגמת ענין „יעלה על הדעת שהוא אינו מצוי״.\nי. והנה ענין המצוות הוא לפעול בכחות ואברי האדם ובהדברים שבעולם (שבהם מקיימים המצוה) שיהיו כפי הוראת התורה³³. והיינו שהמצוות פועלים בהאדם ובעולם שיהיו בציור המתאים בכל פרטיהם כפי שהם צריכים להיות ע״פ הלכות ודיני התורה.\nופעולה זו בתכלית השלימות תהי׳ בימות המשיח, שאז יהי׳ העולם בציור המתאים וכו׳, דלא רק שלא יהי׳ שום מניעות מצד העולם לקיום התומ״צ, אלא אדרבה — שהעולם גופא יהי׳ באופן ד„מלאה הארץ דעה את ה׳״ בכדי שיהי׳ אפשר להאדם לקיים „מצות ידיעת השם״ (היסוד והעמוד דכל המצוות) בשלימות.\nויש לומר, שזהו גם מהטעמים על מה שהאמונה בביאת המשיח הוא עיקר בדת³⁴ — כי בזה מודגש הענין דשלימות התורה ומצוותי׳, שסוף סוף יפעלו התורה ומצוותי׳ בהעולם שיהי׳ במצב כזה שיתאים לקיום התומ״צ בשלימות.\nועפ״ז יובן מה שהרמב״ם מאריך בתיאור מצב העולם שיהי׳ בביאת המשיח — אף שהתיאור דמצב העולם הוא לכאורה רק תנאי (ענין צדדי) שעי״ז יהי׳ אפשר קיום התומ״צ בשלימותן — כי בזה שהעולם יהי׳ במצב כזה — מתבטא (כנ״ל) השלימות דתומ״צ שפועלים גם בעולם, ולכן נכללים גם פרטים אלו בהחיוב דאמונה בביאת המשיח³⁵.\nיא. וזהו גם מה שהסיום וחותם דהלכות משיח הוא בענין ידיעת השם — כי ענין השלימות דתומ״צ שיהי׳ בימי המשיח (שענין זה הוא גדר העיקרי דביאת המשיח) הוא בעיקר במצוה זו, מצוה ראשונה, ראשונה (גם) במעלה.\nומכיון שבמצות „ידיעת השם״ יש שני ענינים: (א) „שיש שם מצוי ראשון והוא ממציא כל נמצא כו׳״ (הידיעה בשלימותו ית׳ שע״פ שכל): (ב) „יעלה על הדעת שהוא אינו מצוי״ (הידיעה שהוא ית׳ נעלה מגדרי השכל, וגם ענין זה צריך להיות באופן ד„לידע״) —\nלכן, גם ב„וישיגו דעת בוראם״ — קיום מצות ידיעת השם בימוה״מ, שאז תהי׳ קיומה בשלימות — כותב הרמב״ם שני ענינים: א) „כפי כח האדם״, היינו שישיגו דעת בוראם כפי שצמצם עצמו לפי „כח האדם״, גדרי השכל. ב) „כמים לים מכסים״, שישיגו גם בחינת האלקות שלמעלה מגדרי השכל — בדוגמת המים המכסים את קרקעית הים, להיות למעלה ממנו.",[["32","32","קידושין מ, ב. וש״נ. רמב״ם הל׳ ת״ת פ״א ה״ג. פ״ג ה״א."],["33","33","ראה בארוכה „הדרן״ הנ״ל ס״ה ואילך."],["34","34","ראה שו״ת חת״ס יו״ד סשנ״ו."],["35","35","אלא שאעפ״כ, מה שנתאוו כו׳ ימות המשיח הוא רק בכדי לעסוק בתומ״צ כהוגן — כי מה שיהודי צריך להתאוות הוא להשלימות דתומ״צ. משא״כ מצב העולם דאז, המאפשר את השלימות דתומ״צ — יש לומר שהוא נכלל (בעיקר) בחיוב האמונה בביאת המשיח, ולא בהחיוב לחכות לביאתו."]]],[1300271270,"אמנם, כמו שהמים אינם מבטלים את מקום הים אלא ממלאים אותם, היינו, שאותו מקום גופא מתמלא מהמים (ופעולת המים בו הוא רק שלא יתראה למציאות בפני עצמו ויהי׳ מכוסה בהמים) — אותו הדבר הוא גם ב„מלאה הארץ דעה את ה׳״, שהשכל גופא יהי׳ חדור וממולא בהידיעה דבחינת האלקות שלמעלה מגדרי השכל (וכנ״ל שגם ענין זה צריך להיות באופן של „לידע״).\nומכיון שמעיקרי הענין דימות המשיח הוא שגם העולם (והאדם) יהי׳ במצב שיאפשר קיום התומ״צ בשלימות — לכן כותב הרמב״ם (לפני „וישיגו דעת בוראם״) „יהיו ישראל חכמים גדולים ויודעים דברים הסתומים״, שגם בהאדם (לפני שמקיים מצות ידיעת השם) יהי׳ ההכנה המתאימה לקיום מצות ידיעת השם: „חכמים גדולים״ — הכנה ל„וישיגו כו׳ כפי כח האדם״; „ויודעים דברים הסתומים״ — ששכל האדם יהי׳ במצב כזה שיודע גם דברים סתומים — הכנה ל„כמים לים מכסים״.\nיב. ויש להוסיף, דכמו שבידיעת השם הנקודה הראשונה והעיקרית שהיא הסיבה והשרש למצות ידיעת השם היא האמונה הכללית שיש אלוקה, שידיעה זו באדם היא (לא מצד ידיעת ושכל האדם, גם לא באופן דידיעת השלילה, כי אם) מצד זה שהוא ית׳ נמצא בגילוי בכל מקום (כנ״ל ס״ח) —\nעד״ז הוא בענין ימוה״מ, דמה ש„באותו הזמן״ יהי׳ העולם במצב המתאים שיוכלו לקיים כל המצוות (כולל גם מצות ידיעת השם בשני הפרטים דלעיל) בתכלית השלימות — הנה כ״ז הוא רק תוצאה ומסובב מעצם הענין דביאת המשיח.\nכלומר, ענינו של משיח הוא (לא בכדי לתקן את העולם, אלא) ענין בפ״ע³⁶ — „מלך מבית דוד״³⁷. וענין ביאת המשיח (בעולם) — שזה יהי׳ לאחרי „בנה מקדש במקומו וקבץ נדחי ישראל״, שאז הוא „משיח בודאי״³⁸ — הוא, שיומשך ויתגלה בעולם מלך המשיח (שהוא למעלה מענין תיקון העולם), אלא",[["36","36","להעיר מהידוע (המשך תער״ב ח״א רפקכ״ג. סה״מ תרצ״ט ע׳ 107. ובכ״מ) שמשיח יזכה לבחינת יחידה, ומכיון שענין יחידה הוא „שמקבלת מיחיד, כי היא רק תשוקתה ליחידו של עולם בלבד״ (לקו״ת ראה כה, א) — לכן, משיח (בחינת יחידה) הו״ע בפני עצמו — דוגמת יחידו של עולם."],["37","37","הל׳ מלכים פי״א ה״ד. ומפשטות לשון הרמב״ם משמע שענין זה („מלך מבית דוד״) הוא (לא רק מצד ההבטחה ש„לא תכרת המלוכה מזרע דוד לעולם״ (רמב״ם שם פ״א ה״ז), אלא) הגדר דמשיח. ויש לבאר זה ע״פ הידוע (המשך תער״ב שם פקכ״ב) שבמלך — שני אופנים: (א) שהמלוכה וההתנשאות שלו באה (בעיקר) „מן העם, שמנשאין אותו עליהם ועושין אותו למלך״, ועל זה אמרו „אין מלך בלא עם״. (ב) ש„אינו צריך להסכמת מזולתו כלל וכלל, להיותו מלך בעצם . . (ובחינה זו דמלכות יכולה להיות) גם בלא עם״. ויש לומר, דמה שדוד זכה בכתר מלכות (רמב״ם שם), ו„עיקר המלכות לדוד״ (שם ה״ח) הוא — שמלכי בית דוד יש (גם) הענין ד„מלך בעצם״*. ועפ״ז יובן מה שהתואר דמשיח הוא „מלך מבית דוד״ — כי משיח הוא ענין בפני עצמו (שלמעלה מענין תיקון העולם), בחינת „מלך בעצם״** שאינו תלוי בהעם."],["38","38","שם פי״א ה״ד. ועפ״מ בפנים יובן מה שבתחילה כתב הרמב״ם „משיח בודאי״, ורק לאח״ז „ויתקן את העולם כולו״. *) ראה עד״ז לקו״ש חכ״ח ע׳ 109 ואילך. ולהעיר מהמבואר בהמשך תער״ב שם שבחינה זו דמלוכה „הו״ע שהכתר הולמתו״ — והרי הענין דכתר הולמתו „עדות הוא לבית דוד״ (ע״ז מד, סע״א). **) ראה גם המשך תער״ב שם רפקכ״ג, דענינו של משיח (מה שיזכה לבחינת יחידה) הוא דוגמת בחינת „מלך בעצם״."]]],[1300271271,"שכתוצאה מזה „יתקן (גם) את העולם כולו״, שגם העולם יהי׳ בשלימות, עד אשר „מלאה הארץ דעה את ה׳ כמים לים מכסים״.\nיג. והנה ע״פ הידוע שכל הענינים דלעיל תלויים במעשינו ועבודתינו דעכשיו³⁹ — יש לומר, שגם הענין דביאת המשיח גופא (שלמעלה מתיקון העולם) שיומשך בעולם [שהרי ענין ביאת המשיח הוא שמשיח יתגלה בעולם, שידעו שהוא „משיח בודאי״], נפעל ע״י מעשינו ועבודתינו עכשיו.\nומכיון שמשיח הוא (לא רק „אמצעי״ בכדי לתקן את העולם, אלא) ענין לעצמו — מובן מזה, שגם העבודה שעל ידה נפעל עצם הענין דביאת המשיח, הוא עסק התורה לשמה, לא בתור „אמצעי״ בשביל איזה ענין אחר, גם לא בכדי לידע את המעשה אשר יעשון⁴⁰, כי אם, לשם התורה עצמה, מצד זה ש„אורייתא וקוב״ה כולא חד״⁴¹.\nיד. ויש לקשר זה עם הספר „משנה תורה״ להרמב״ם, ש„חיבור זה מקבץ לתורה שבע״פ כולה״⁴², וכשאדם לומד כל הספר, הוא „יודע ממנו תורה שבעל פה כולה״⁴² — כל הלכות ודיני התורה, גם אותם ההלכות שאינם נוהגים בזמן הזה:\nבלימוד התורה בכדי לידע את המעשה — נוגע רק לימוד הלכות אלו שנוהגות בזמן הזה; משא״כ לימוד וידיעת ההלכות (רצונו ית׳⁴³) של כל התורה כולה — יש לומר, שבזה מתבטא הענין דלימוד התורה לשמה.\nכלומר, בכדי „לתפוס״ כביכול את הקב״ה ע״י ידיעת התורה (שזהו״ע עסק התורה לשמה כו׳) ובשלימות — הוא דוקא ע״י ידיעת הלכות כל התורה כולה, דמכיון ש„אלוקה זה אחד הוא״⁴⁴ — הרי מובן, שגם רצונו ית׳ (שהוא ורצונו „אחד ממש״⁴⁵) דכל התרי״ג מצוות, הוא רצון אחד. ולכן, כל זמן שחסר הלימוד והידיעה דהלכות מצוה אחת — חסר גם בה„תפיסא״ בהרצון שבשאר המצוות⁴⁶. ורק ע״י לימוד וידיעת כל המצוות — עי״ז דוקא „תופסים״ רצונו ית׳ בשלימות.\nטו. עפ״ז יש לבאר גם מה שהרמב״ם פותח הקדמתו בהפסוק⁴⁷ „אז לא אבוש בהביטי אל כל מצוותיך״, שהשייכות (בפשטות) דפסוק זה להספר משנה תורה (שכולל ההלכות דכל המצוות) הוא — שע״י ההבטה „אל כל מצוותיך״ — אז (דוקא) „לא אבוש״.\nויש לומר, שבהלשון „לא אבוש״ — מרומז העילוי (דלעיל סי״ד) שבידיעת כל המצוות, „בהביטי אל כל מצוותיך״.",[["39","39","תניא רפל״ז."],["40","40","וגדולה מזו מצינו, שאפילו לימוד התורה בכדי לקיים מצות תלמוד תורה, מכיון שלימוד התורה הוא „אמצעי״ בכדי לקיים המצוה, אין זה אמיתית הענין ד„לשמה״ — ראה בארוכה לקו״ש ח״ב ע׳ 304. ובכ״מ."],["41","41","זהר הובא בתניא פ״ד, רפכ״ג. וראה זהר ח״א כד, א. ח״ב ס, א. תקו״ז ת״ו (כא, ב) תכ״ב (סד, א). ועוד."],["42","42","לשון הרמב״ם בהקדמתו."],["43","43","ראה לעיל ס״ט."],["44","44","הל׳ יסוה״ת פ״א ה״ז."],["45","45","שער היחוד והאמונה פ״ח — ע״פ רמב״ם שם פ״ב ה״י."],["46","46","ואף שהעצם „כשאתה תופס במקצת מן העצם אתה תופס בכולו״ (מאמר הבעש״ט — הובא בהמשך תרס״ו ע׳ תקכב, בהמשך תער״ב פ׳ ערב ובכ״מ) — הרי זהו „כמו שהעצם בא בהתעלמות״ (המשך תער״ב שם)."],["47","47","תהלים קיט, ו."]]],[1300271272,"ונקודת הביאור בזה, בהקדים מ״ש הרמב״ם בהל׳ עדות⁴⁸, וז״ל: „וכיצד מאיימין עליהם . . מודיעין אותם כח עדות שקר ובושת המעיד בה בעולם הזה ובעולם הבא״. ולכאורה א״מ: בכל האיסורים שבתורה, כולל גם איסורי ד׳ מיתות בי״ד (שחמורים יותר מהאיסור דעדות שקר, שהוא רק איסור לאו⁴⁹), לא מצינו שיודיעום שיהי׳ להם בושת בעוה״ז ובעוה״ב — ומהו הקשר המיוחד דעדות שקר דוקא עם ענין הבושת (בעולם הבא⁵⁰)?\nויש לומר הביאור בזה:\nמציאותו של יהודי הוא — עדות על הקב״ה, כמ״ש⁵¹ „אתם עדי״. היינו, שע״י הנהגתו הטובה והישרה — הוא מעיד על ה„טוב״ וה„יושר״ של הקב״ה כביכול. [והוא ע״ד דאיתא בגמרא⁵²: „ואהבת את ה׳ אלקיך⁵³ — שיהא שם שמים מתאהב על ידך . . מה הבריות אומרות עליו . . פלוני שלמד תורה ראו כמה נאים דרכיו כמה מתוקנים מעשיו . . עבדי⁵⁴ אתה ישראל אשר בך אתפאר״⁵⁵].\nועפ״ז מובן מה שדוקא בעדי שקר יש ענין ה„בושת . . בעולם הזה ובעולם הבא״ — שאינו בשאר איסורים, אפילו לא באיסורי ד׳ מיתות בי״ד — כי כל האיסורים הם ענינים פרטים, משא״כ כשמעיד עדות שקר, שעי״ז נעשה ההיפך דכללות ענינו (עדות על הקב״ה) — הרי זה ענין של בושת.\nכי הגדר ד„בושת״ הוא — חסרון בענין נפשי⁵⁶. כלומר, אף שבגופו ובממונו לא חסר מאומה (ודלא כנזק צער ריפוי ושבת, שהם חסרון בגופו⁵⁷ או בממונו), אבל לאידך, בנוגע לנפש — הרי אדם בזוי מאבד כל תוכנו.\nוכן הוא בנוגע עדי שקר⁵⁸, דעם היות שבנוגע לחומר האיסור וענשו הוא רק איסור לאו — אעפ״כ, הרי עי״ז דוקא (משא״כ בשאר איסורים) נעשה ההיפך דכללות ענינו ומאבד כל תוכנו.\nועפ״ז יובן גם בנוגע לענינינו שהעילוי ד„בהביטי אל כל מצוותיך״ הוא „לא אבוש״:\nהענין ד„אתם עדי״ (מה שיהודי הוא עדות על הקב״ה) בשלימות, הוא — ע״י ידיעת ההלכות דכל המצוות. דמכיון שהמצוות הם רצונו ית׳, שהוא ורצונו אחד — הרי ע״י שרצונו ית׳ (דכל התרי״ג מצוות, שהוא רצון אחד, כנ״ל) נמצא בגילוי בידיעתו של האדם — הנה עי״ז הוא מעיד בשלימות על הקב״ה.",[["48","48","פי״ז ה״ב."],["49","49","וגם ההכרזה דעדים זוממים היא אפילו על עונש מלקות או ממון — „כותבין ושולחין בכל עיר ועיר פלוני ופלוני העידו בכך וכך והוזמו . . לקו בפנינו או ענשנו אותו כך וכך דיניהן״ (רמב״ם שם פי״ח ה״ז), משא״כ בזקן ממרא, בן סורר ומורה ומסית — הכרזתן כשיש מיתה (רמב״ם הל׳ ממרים פ״ג. ספ״ז)."],["50","50","בנוגע הבושת בעוה״ז — ראה סנה׳ כט, א."],["51","51","ישעי׳ מג, י. שם, יב. ובזהר ח״ג פו, א: „אתם עדי — אלין אינון ישראל״. וראה לקו״ש חי״ט ע׳ 190 ובהנסמן שם."],["52","52","יומא פו, ב. וראה גם רמב״ם הל׳ יסוה״ת ספ״ה."],["53","53","ואתחנן ו, ה."],["54","54","ישעי׳ מט, ג."],["55","55","ענין דקדה״ש — והפכו עדות שקר, ענין דחה״ש, שכפרתו שחמורה מהכל (יומא שם, א. רמב״ם הל׳ תשובה ספ״א) אפילו כשאינו אסור מצד עצמו — וכמו בעדות שקר, ש„אסור לעמוד ולהראות שהוא עד („כדי שיראה הלוה ויפחד כו׳״) אע״פ שאינו מעיד״ (רמב״ם הל׳ עדות פט״ז ה״ו)."],["56","56","ולכן חלוקים בזה — לפי המבייש והמתבייש (רמב״ם הל׳ חובל ומזיק רפ״ג)."],["57","57","או בהרגש גופו (צער) — ולכן שווה בכל."],["58","58","להעיר גם ממה ש„הבזויין פסולין לעדות״ (רמב״ם הל׳ עדות פי״א ה״ה)."]]],[1300271273,"וזהו מה שהעילוי ד„בהביטי אל כל מצוותיך״ הוא „לא אבוש״ דוקא: גם כשיודע רק אותם ההלכות שנוהגים בזמן הזה — לא יחסר מאומה (אין שום נזק כו׳) בקיום התומ״צ שלו, אלא שאעפ״כ, יש לו להתבושש, מצד זה שחסר אצלו בעיקר ענינו, הענין ד„אתם עדי״: ודוקא „אז לא אבוש — בהביטי אל כל מצוותיך״.\nטז. על פי כל הנ״ל יומתק גם שהקשר דסיום ספר משנה תורה עם התחלתו („נעוץ תחלתן בסופן וסופן בתחלתן״⁵⁹) הוא לא רק עם ההלכה הראשונה של הספר [שבשניהם, בהלכה הראשונה ובהלכה האחרונה, מדובר בענין ידיעת השם, כנ״ל], אלא גם עם הפסוק „אז לא אבוש בהביטי אל כל מצוותיך״ שבהתחלת הספר ממש.\nכי ע״י אופן זה בלימוד התורה שענינו הוא (לא שהתורה מלמדת את האדם מה שעליו לעשות, אלא אדרבה) שהאדם נעשה „עד״ על רצון הקב״ה, על רצונו העצמי⁶⁰ שלמעלה משייכות לעולמות — הנה עי״ז נפעל הענין דביאת המשיח⁶¹, עצם הענין דביאת המשיח שלמעלה מתיקון העולם.\nיז. ויש להוסיף, שענין „בהביטי אל כל מצוותיך״ קשור (לא רק עם כללות הלכות משיח שבסיום הספר, אלא) גם עם ההלכה האחרונה דסיום וחותם הספר ממש „ובאותו הזמן לא יהי׳ שם לא רעב ולא מלחמה ולא קנאה ותחרות״.\nנקודת הביאור בזה:\nבהדרגא דלימוד התורה בתור אמצעי לאיזה ענין אחר — כמה אופנים. ומהם:\nא) לידע את המעשה אשר יעשון, שענינו של לימוד זה הוא כעין הסרת דבר בלתי רצוי (בכדי שלא יכשל באיסור, ועד״ז במ״ע, שלא יקיים את המצוה שלא כתיקונה). ונמצא שלימוד זה קשור עם ענין של „מלחמה״. כלומר, שישנו דבר המנגד, וצריך ללחום עמו ולנצחו.\nועד״ז הוא גם משארז״ל „בראתי⁶² יצה״ר בראתי לו תורה תבלין״ — לימוד התורה בכדי לנצח את מלחמת היצר (נצחון בשלימות, שמתבלין את היצה״ר גופא ומהפכים אותו לקדושה⁶³).\nב) בכדי לעשות שלום בעולם (שלילת מחלוקת), „שכל התורה ניתנה לעשות שלום בעולם״⁶⁴.\nג) „שלום״ הוא גם מלשון שלימות. דהעולם כמו שהוא מצ״ע הוא חסר⁶⁵, וע״י התורה נעשה בו שלימות.\nונמצא שלימוד התורה בתור „אמצעי״ קשור עם א׳ משלשה ענינים אלו: אופן הג׳ — עם „רעב״ (חסרון), שע״י התורה נשלם החסרון שבעולם: אופן הא׳ — עם",[["59","59","ספר יצירה פ״א מ״ז."],["60","60","כידוע שכל המצוות מתייחסות אל העצמות (סה״ש תו״ש ס״ע 190 ואילך). ולהעיר גם מסה״מ ה״ש״ת ע׳ 52: וענין העדות הוא על דבר הנעלם לגמרי . . בחי׳ פנימי׳ ועצמי׳ א״ס, שלמעלה גם מבחי׳ סובב."],["61","61","וי״ל שזה מרומז גם במה שהענין דימוה״מ הוא הסיום והחותם דכל ספר משנה תורה — שע״י לימוד ספר זה, שבו נקבצו כל הלכות התורה, באים לימוה״מ."],["62","62","קידושין ל, ב."],["63","63","דזהו ענינו של „תבלין״, שאינו מבטל את המאכל, אלא אדרבה, מתבל אותו ונותן בו טעם."],["64","64","רמב״ם סוף הל׳ חנוכה."],["65","65","ראה ב״ר פי״א, ו ובפרש״י."]]],[1300271274,"„מלחמה״: ואופן הב׳ — עם „קנאה ותחרות״ (מחלוקת).\nאמנם לימוד התורה לשמה — הלימוד באופן ד„הביטי אל כל מצוותיך״, ענינו הוא (לא בכדי שהתורה תפעל בעולם ובאדם, אלא אדרבא) שהאדם יהי׳ „עד״ על רצון הקב״ה — הוא דוגמת „אותו הזמן״, ש„לא יהי׳ שם לא רעב ולא מלחמה ולא קנאה ותחרות״, ו„לא יהי׳ עסק כל העולם אלא לדעת את ה׳ בלבד״⁶⁶.",[["66","66","דפירוש „לדעת את ה׳ בלבד״ הוא — שעניינו „לדעת את ה׳״ הוא בטהרתו (בלי ערבוב כוונה נוספת), „בלבד״."]]],[1300271275,"משיחת ש\"פ צו, פ' פרה ה'תשמ\"ו\nא. מ'האט דאך ערשט1 מסיים געווען דעם מחזור שני (כפליים לתושי'<sup data-n=\"2\">2</sup> פון לימוד ספר הרמב\"ם (ג' פרקים ליום) און ווידער אנגעהויבן לערנען דעם ספר הרמב\"ם מתחלתו במחזור השלישי (בתלת זימני הוי חזקה<sup data-n=\"3\">3</sup>.\nוכמנהג ישראל (תורה היא<sup data-n=\"4\">4</sup> אז עושין שמחה לגמרה של תורה5, אפילו ווען מ'איז מסיים א מסכת אחת6, עאכו\"כ ווען מ'איז מסיים דעם ספר הרמב\"ם (וואס איז „מקבץ לתורה שבעל פה כולה\"<sup data-n=\"7\">7</sup> — האט מען (בימים אלו — בסמיכות ליום הסיום) בכו\"כ מקומות געפראוועט סיומים בספר הרמב\"ם, „וברב עם הדרת מלך\"8, ובעוד מקומות וועט מען בעז\"ה מאכן סיומים אין די קומענדיקע טעג.\nוואס דאס (עריכת הסיומים) גיט זיכער צו א חיזוק אין (המשך) לימוד ספר הרמב\"ם, ווי מ'זעט במוחש אז דורך דעם שטורעם ופרסום פון דעם סיום בספר הרמב\"ם, ובפרט די דברי תורה ודברי התעוררות פון די משתת־\nפים (מדברים) בעת הסיום (כמנהג ישראל אז בעת א „סיום\" רעדן רבנים וגדולים דברי תורה וכו') — קומט צו חיזוק ביי אלע אידן וואס זיינען זיך משתתף אין דעם, אדער דערוויסן זיך דערפון, צו ממשיך זיין אדער אנהויבן פון־דאס־ניי לערנען די שיעורים בספר הרמב\"ם על הסדר, צוזאמען מיטן ריבוי אידן וואס זיינען זיך שוין משתתף אין דעם לימוד. ובפרט, אז באם סיום הרמב\"ם רעדט מען דאך זיכער אן עניין והלכה אין ספר הרמב\"ם עצמו, בהתאם לרצון הרמב\"ם וואס ער וויל דאך זיכער אז מ'זאל פארבינדן א סיום פון זיין ספר מיט רעדן אן ענין אין לערנען בספר הלכות שלו (וועלכן מ'איז דערביי מסיים), „לאסוקי שמעתא אליבא דהילכתא\"9 — גיט דאס זיכער צו חיזוק אין (המשך) לימוד ספר הרמב\"ם.\nב. בכדי צוגעבן נאכמער חיזוק בזה, ובכדי ממשיך זיין די השפעה ופעולה ורושם פון די חגיגת הסיומים אויך לאחרי זה (ווי יעדער פעולה פון קדושה וואס דארף דאך זיין א פעולה נמשכת) — איז מען מציע, און מיט א בקשה נפשית, און זיכער וועט מען דאס מפרסם זיין און איבערגעבן בכל מקום ומקום וואו מ'מאכט די סיומים:\nמ'זאל צוזאמענקלייבן די דרשות ודברי תורה, ובפרט דברי תורה בתורת הרמב\"ם, וועלכע זיינען געזאגט געווארן (אדער וועלן געזאגט ווערן) בעת הסיום, און זיי אפדרוקן אין א קובץ",[["1","1","בכ\"ו אדר ראשון."],["2","2","ל' הכתוב — איוב יא, ט. וראה שמו\"ר פמ\"ו, א."],["3","3","ב\"מ קו, ריש ע\"ב."],["4","4","ראה תוד\"ה נפסל — מנחות כ, ב. ובכ\"מ."],["5","5","שהש\"ר פ\"א, ט. קה\"ר רפ\"א. יל\"ש מלכים רמז קעה. ולהלכה — רמ\"א יו\"ד סו\"ס רמו (משבת קיח, סע\"ב ואילך). ועד\"ז ברמ\"א או\"ח סתקנ\"א ס\"י. ובטור ורמ\"א שם סתרס\"ט לענין סיום תושב\"כ."],["6","6","רמ\"א יו\"ד שם."],["7","7","ל' הרמב\"ם בהקדמתו לספר היד."],["8","8","ל' הכתוב — משלי יד, כח. וראה אנציקלופדי' תלמודית (כרך ד) ערך ברב עם. וש\"נ."],["9","9","ראה יומא כו, א."]]]]});
